INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大方", "is_correct": false, "explanation": "语义：“大方”指慷慨或举止自然，与“一次也不原谅”的语境矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”指明白、不模糊，不用来说对迟到者的态度。"}, {"text": "无情", "is_correct": true, "explanation": "正确。“无情”指不讲情面，与“一次也不原谅”的语境相合。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指场面喧闹，与经理对迟到者的态度无关。"}], "explanations": {"大方": "语义：“大方”指慷慨或举止自然，与“一次也不原谅”的语境矛盾。", "清楚": "搭配：“清楚”指明白、不模糊，不用来说对迟到者的态度。", "无情": "正确。“无情”指不讲情面，与“一次也不原谅”的语境相合。", "热闹": "语义：“热闹”指场面喧闹，与经理对迟到者的态度无关。"}, "sentence_index": 6, "correct_answer": "无情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师对学生很无情，一道题讲十遍也不着急。", "explanation": "这里应该用〈耐心〉。耐心指做事不急躁、不厌烦，无情指不讲情面，与“讲十遍也不着急”的态度相反。"}, {"text": "这位大妈很无情，总是帮邻居做饭。", "explanation": "这里应该用〈热心〉。热心指乐于帮助他人，无情指不讲情面，与“总是帮邻居做饭”的态度相反。"}, {"text": "他很无情，常把钱送给穷人。", "explanation": "这里应该用〈慷慨〉。慷慨指大方、乐于给予，无情指不讲情面，与“把钱送给穷人”的行为相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个裁判无情得罚下了那名球员。", "corrected_sentence": "这个裁判无情地罚下了那名球员。", "error_description": "状语标记用错。“无情”修饰动词“罚下”，作状语，中间应用“地”，不能用“得”。应说“无情地罚下”，不能说“无情得罚下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事一向无情很，从不讲情面。", "corrected_sentence": "他做事一向无情得很，从不讲情面。", "error_description": "程度补语的“得”缺失。形容词“无情”后要用“得”引出“很”，应说“无情得很”，不能说“无情很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
