INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（谦辞）把自己的作品请人指正。", "primary_collocate": null, "pronunciation": "jiù zhèng", "ipa": "tɕjoʊ˥˩ ʈʂəŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这是我写的拙文，敬请就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小文一篇，请各位老师就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小诗一首，敬请先生就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这篇文章送上，请您就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新作完成了，寄给先生就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小册子是我写的，请读者就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的画还不成熟，请前辈就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天把文章带来了，请大家就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几首小诗是我写的，请您就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的小书出版了，敬请各位专家就正。", "target_word": "就正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "谦辞：把自己的作品呈给别人，请对方指正", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就正", "is_correct": true, "explanation": "就正：谦辞，请对方指正自己的作品，符合“敬请”的语境。"}, {"text": "复印", "is_correct": false, "explanation": "语义：复印只是复制文件，与自谦地请人指正自己作品的语境不符。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是毁掉，与自谦地请人指正的语境冲突。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休是离开工作岗位，不能带“拙文”作对象，与请人指正的语境无关。"}], "explanations": {"就正": "就正：谦辞，请对方指正自己的作品，符合“敬请”的语境。", "复印": "语义：复印只是复制文件，与自谦地请人指正自己作品的语境不符。", "销毁": "语义：销毁是毁掉，与自谦地请人指正的语境冲突。", "退休": "语义：退休是离开工作岗位，不能带“拙文”作对象，与请人指正的语境无关。"}, "sentence_index": 0, "correct_answer": "就正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份申请书已经就正了，下周就能办手续。", "explanation": "这里应该用〈批准〉。就正是请人指正作品，不能用来表示同意或批准申请。"}, {"text": "我把这块蛋糕就正给你，你拿去吃吧。", "explanation": "这里应该用〈送〉。就正是请人指正作品，不表示把东西送给别人。"}, {"text": "这是我的新同事，请您多多就正。", "explanation": "这里应该用〈关照〉。就正的对象是自己的作品，不能用来指人；请人照顾新同事要用关照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就正", "is_correct": true, "explanation": "就正：谦辞，请对方指正，符合“我的画还不成熟，请前辈”的语境。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语应是食物，不能说“请前辈吃掉”。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：撕毁是把东西撕坏，与请前辈指正的语境相反。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：烧掉是把东西烧毁，与自谦地请前辈看画的意图不符。"}], "explanations": {"就正": "就正：谦辞，请对方指正，符合“我的画还不成熟，请前辈”的语境。", "吃掉": "搭配：“吃掉”的宾语应是食物，不能说“请前辈吃掉”。", "撕毁": "语义：撕毁是把东西撕坏，与请前辈指正的语境相反。", "烧掉": "语义：烧掉是把东西烧毁，与自谦地请前辈看画的意图不符。"}, "sentence_index": 6, "correct_answer": "就正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在就正新产品，希望让更多人知道。", "explanation": "这里应该用〈宣传〉。就正是请人指出作品的错误，让更多人知道某事物要用宣传。"}, {"text": "我的包裹请您就正一下。", "explanation": "这里应该用〈签收〉。就正是请人指正作品，收取、签收包裹要用签收。"}, {"text": "我的自行车坏了，想请您就正一下。", "explanation": "这里应该用〈修理〉。就正是请人指正作品，修好坏了的东西要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是先生的新作，敬请就正。", "corrected_sentence": "这是我的新作，敬请就正。", "error_description": "“就正”是谦辞，只能用于把自己的作品请别人指正，不能用于别人的作品。应把“先生的新作”改为“我的新作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首小诗还很粗糙，请先生就正着。", "corrected_sentence": "这首小诗还很粗糙，请先生就正。", "error_description": "“就正”是请对方指正的动作，还没有发生，不能加表示持续的“着”。应说“请先生就正”，去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
