INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "无视是看见了却当作没看见。", "primary_collocate": null, "pronunciation": "wú shì", "ipa": "u˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他看见我，却无视我，直接走过去了。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机无视红灯，开车冲了过去。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她无视旁边的人，大声打电话。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能无视那些小孩的哭声。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无视老师的话，继续玩手机。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人无视路边的牌子，走进了草地。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别无视身体发出的信号，累了就休息。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他假装没听见，无视了我的问题。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无视前面的行人，按着喇叭开过去。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都无视他，他觉得很难过。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无视了", "label": "体标"}, {"form": "無視", "label": "繁体"}], "register": "中性", "sense_fingerprint": "明明看见或知道却装作没看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90779, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：无视，wú shì，看见了却当作没看见。"}, {"text": "武士", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是古代的武人。"}, {"text": "无师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是没有老师。"}, {"text": "物事", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是事物。"}], "explanations": {"无视": "正确：无视，wú shì，看见了却当作没看见。", "武士": "wǔ（第三声）与 wú（第二声）声调不同，意思是古代的武人。", "无师": "shī（第一声）与 shì（第四声）声调不同，意思是没有老师。", "物事": "wù（第四声）与 wú（第二声）声调不同，意思是事物。"}, "sentence_index": null, "correct_answer": "无视"}, "level_3": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：与前文“看见我”形成转折，表示看见了却装作不理。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”与后文“直接走过去了”的动作矛盾，不合语境。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是物品，不能用来搭配“我”。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎我”与后文“直接走过去了”相矛盾，不合语境。"}], "explanations": {"无视": "正确：与前文“看见我”形成转折，表示看见了却装作不理。", "拥抱": "语义：“拥抱”与后文“直接走过去了”的动作矛盾，不合语境。", "搬运": "搭配：“搬运”的对象是物品，不能用来搭配“我”。", "欢迎": "语义：“欢迎我”与后文“直接走过去了”相矛盾，不合语境。"}, "sentence_index": 0, "correct_answer": "无视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我没有看见桌上的那张纸，所以无视了它。", "explanation": "这里应该用〈忽略〉。无视表示明明看见或知道却故意不理，这里说没看见，应该用〈忽略〉。"}, {"text": "考试时他粗心，无视了题目上的一个条件。", "explanation": "这里应该用〈忽略〉。粗心是没注意到，无视表示明明看见却故意不理，二者不符，应该用〈忽略〉。"}, {"text": "他的眼睛受伤了，所以无视前面的车。", "explanation": "这里应该用〈看不见〉。无视要求能看见却故意不理，眼睛受伤看不见，不能说无视。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90779, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：无视，wú shì，看见了却当作没看见。"}, {"text": "误事", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是耽误事情。"}, {"text": "午市", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是午间的营业时段。"}, {"text": "五十", "is_correct": false, "explanation": "wǔ shí（第三声、第二声）与 wú shì（第二声、第四声）声调不同，意思是数字50。"}], "explanations": {"无视": "正确：无视，wú shì，看见了却当作没看见。", "误事": "wù（第四声）与 wú（第二声）声调不同，意思是耽误事情。", "午市": "wǔ（第三声）与 wú（第二声）声调不同，意思是午间的营业时段。", "五十": "wǔ shí（第三声、第二声）与 wú shì（第二声、第四声）声调不同，意思是数字50。"}, "sentence_index": null, "correct_answer": "无视"}, "level_3": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：“别……”之后用“无视”，表示明明察觉却不理会，与后文“累了就休息”形成对照。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的对象是文字或课文，不能背诵身体发出的信号。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人或帮助，不用于身体发出的信号，与语境不合。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”身体的信号与后文“累了就休息”相悖，不合语境。"}], "explanations": {"无视": "正确：“别……”之后用“无视”，表示明明察觉却不理会，与后文“累了就休息”形成对照。", "背诵": "搭配：“背诵”的对象是文字或课文，不能背诵身体发出的信号。", "感谢": "搭配：“感谢”的对象是人或帮助，不用于身体发出的信号，与语境不合。", "迎接": "语义：“迎接”身体的信号与后文“累了就休息”相悖，不合语境。"}, "sentence_index": 6, "correct_answer": "无视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的耳机坏了，听不见老师说话，所以无视了老师。", "explanation": "这里应该用〈没有回应〉。无视要求明明听见或察觉却故意不理，耳机坏了听不见，只是没有回应，不能说无视。"}, {"text": "他生病了，只好无视这次比赛。", "explanation": "这里应该用〈放弃〉。因生病而不能参加，不是明知却故意不理，应该用〈放弃〉。"}, {"text": "他一直低着头玩手机，没有留意老师在叫他，却无视了老师。", "explanation": "这里应该用〈察觉〉。无视要求明明察觉却故意不理，这里是根本没有注意到，应该用〈察觉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师明明听到了我的回答，却把无视了它，继续讲课。", "corrected_sentence": "老师明明听到了我的回答，却无视了它，继续讲课。", "error_description": "错误形式：“却把无视了它”，“把”字句中“无视”之前多出“把”，句子不通；正确形式：“却无视了它”，去掉“把”即可，无视是动词，宾语“它”放在其后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他无视的了我的话，转身就走。", "corrected_sentence": "他无视了我的话，转身就走。", "error_description": "错误形式：“无视的了”，“的”插在动词“无视”和“了”之间，不通；正确形式：“无视了”，“了”应直接接在动词后，表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90780, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重视", "is_correct": true, "explanation": "正确：与“无视”意思相反，指认为重要、认真对待。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是动词，但与“无视”的任何义项都没有反义或近义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是动词，但与“无视”的任何义项都没有反义或近义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "“洗澡”是动词，但与“无视”的任何义项都没有反义或近义关系。"}], "correct_answer": "重视", "explanations": {"重视": "正确：与“无视”意思相反，指认为重要、认真对待。", "散步": "“散步”是动词，但与“无视”的任何义项都没有反义或近义关系。", "唱歌": "“唱歌”是动词，但与“无视”的任何义项都没有反义或近义关系。", "洗澡": "“洗澡”是动词，但与“无视”的任何义项都没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90780, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "重视", "is_correct": true, "explanation": "正确：与“无视”意思相反，指认为重要、认真对待。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是动词，但与“无视”的任何义项都没有反义或近义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是动词，但与“无视”的任何义项都没有反义或近义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是动词，但与“无视”的任何义项都没有反义或近义关系。"}], "correct_answer": "重视", "explanations": {"重视": "正确：与“无视”意思相反，指认为重要、认真对待。", "跑步": "“跑步”是动词，但与“无视”的任何义项都没有反义或近义关系。", "睡觉": "“睡觉”是动词，但与“无视”的任何义项都没有反义或近义关系。", "游泳": "“游泳”是动词，但与“无视”的任何义项都没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不放在眼里，不重视。", "primary_collocate": null, "pronunciation": "wú shì", "ipa": "u˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他很骄傲，无视别人的意见。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司无视安全问题，终于出了事故。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不应该无视老人的经验。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家无视国际规则。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无视对手，结果输了比赛。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人无视法律，做了坏事。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板无视工人的要求，大家很生气。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能无视自己的健康。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直无视我的存在。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说不要无视小问题，它会变大。", "target_word": "无视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无视了", "label": "体标"}, {"form": "無視", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不把人或事放在眼里，不当回事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：无视，wú shì，不把人或事放在眼里。"}, {"text": "误事", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是耽误事情。"}, {"text": "无师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是没有老师。"}, {"text": "武士", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是古代的武人。"}], "explanations": {"无视": "正确：无视，wú shì，不把人或事放在眼里。", "误事": "wù（第四声）与 wú（第二声）声调不同，意思是耽误事情。", "无师": "shī（第一声）与 shì（第四声）声调不同，意思是没有老师。", "武士": "wǔ（第三声）与 wú（第二声）声调不同，意思是古代的武人。"}, "sentence_index": null, "correct_answer": "无视"}, "level_3": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：与“很骄傲”的态度相合，表示不把别人的意见放在眼里。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”的态度与“很骄傲”相反，不合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“意见”作宾语，不说吃别人的意见。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”多用于人或成绩，不说赞美别人的意见，与语境也不合。"}], "explanations": {"无视": "正确：与“很骄傲”的态度相合，表示不把别人的意见放在眼里。", "尊重": "语义：“尊重”的态度与“很骄傲”相反，不合语境。", "吃": "搭配：“吃”不能带“意见”作宾语，不说吃别人的意见。", "赞美": "搭配：“赞美”多用于人或成绩，不说赞美别人的意见，与语境也不合。"}, "sentence_index": 0, "correct_answer": "无视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我忙得没顾上看群消息，就无视了老板的通知。", "explanation": "这里应该用〈忽略〉。无视表示有意不放在眼里，这里是忙得没顾上看，并非有意，应该用〈忽略〉。"}, {"text": "他从来没听说过这件事，所以无视了它。", "explanation": "这里应该用〈不知道〉。无视要求明明知情却不放在眼里，这里是根本不知道，不能说无视。"}, {"text": "老师无视了我的努力，天天表扬我。", "explanation": "这里应该用〈肯定〉。无视表示不重视，与后文“天天表扬我”相矛盾，应该用〈肯定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：无视，wú shì，不把人或事放在眼里。"}, {"text": "午市", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是午间的营业时段。"}, {"text": "物事", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是事物。"}, {"text": "五十", "is_correct": false, "explanation": "wǔ shí（第三声、第二声）与 wú shì（第二声、第四声）声调不同，意思是数字50。"}], "explanations": {"无视": "正确：无视，wú shì，不把人或事放在眼里。", "午市": "wǔ（第三声）与 wú（第二声）声调不同，意思是午间的营业时段。", "物事": "wù（第四声）与 wú（第二声）声调不同，意思是事物。", "五十": "wǔ shí（第三声、第二声）与 wú shì（第二声、第四声）声调不同，意思是数字50。"}, "sentence_index": null, "correct_answer": "无视"}, "level_3": {"options": [{"text": "无视", "is_correct": true, "explanation": "正确：与“要求”搭配，表示不把工人的要求放在眼里，与后文“大家很生气”相合。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“答应”工人的要求与后文“大家很生气”相矛盾，不合语境。"}, {"text": "回收", "is_correct": false, "explanation": "搭配：“回收”的对象是物品，不说回收“要求”。"}, {"text": "赠送", "is_correct": false, "explanation": "搭配：“赠送”的对象是物品或礼物，不说赠送“要求”。"}], "explanations": {"无视": "正确：与“要求”搭配，表示不把工人的要求放在眼里，与后文“大家很生气”相合。", "答应": "语义：“答应”工人的要求与后文“大家很生气”相矛盾，不合语境。", "回收": "搭配：“回收”的对象是物品，不说回收“要求”。", "赠送": "搭配：“赠送”的对象是物品或礼物，不说赠送“要求”。"}, "sentence_index": 6, "correct_answer": "无视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师一直无视学生的进步，还天天在班会上表扬每一个人的进步。", "explanation": "这里应该用〈关注〉。无视表示不放在眼里，与后文“天天表扬每一个人的进步”直接相矛盾，应该用〈关注〉。"}, {"text": "妈妈一直无视我的身体，每天都关心我。", "explanation": "这里应该用〈重视〉。无视表示不放在眼里、不重视，与后文“每天都关心我”的意思相反，应该用〈重视〉。"}, {"text": "他认真无视别人的意见，每次都认真听取。", "explanation": "这里应该用〈采纳〉。无视表示不理会，与“认真”的态度相矛盾，应该用〈采纳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直很无视我的建议，最后吃了亏。", "corrected_sentence": "他一直无视我的建议，最后吃了亏。", "error_description": "错误形式：“很无视”，副词“很”不能直接修饰动词“无视”，不通；正确形式：“无视”，去掉“很”即可，无视是动词，直接带宾语“我的建议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈一直了无视我的请求，从来不答应。", "corrected_sentence": "妈妈一直无视我的请求，从来不答应。", "error_description": "错误形式：“了无视”，“了”放在动词前。正确形式：“无视”，句中无需“了”，应直接用动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
