INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90781, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90781, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里怎么想事情，是开心还是难过。", "primary_collocate": null, "pronunciation": "xīn tài", "ipa": "ɕin˥ tʰai˥˩", "syllable_count": 2, "sentences": [{"text": "他最近心态很好，每天都笑。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，她的心态不太好。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的心态变好了，不再难过。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行让他有了轻松愉快的心态。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心态不好，总是哭。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难时，他的心态很积极。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了朋友的话，他的心态马上变好了。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心态乐观，遇到难事也不难过。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，他的心态一下子变差了。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，快乐的心态最重要。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种心态", "label": "量词"}], "register": "中性", "sense_fingerprint": "心态·心情好坏的内心状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心态", "is_correct": true, "explanation": "“心态”指心里对事情的感受与看法，“他最近心态很好”符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”是外界环境，不能作为“他”的属性来评价，不说“他最近天气很好”。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是先天固定的，不会“最近”变化，也谈不上“很好”。"}, {"text": "籍贯", "is_correct": false, "explanation": "语义：籍贯指祖籍或出生地，不是可以“最近”变好或变坏的状态。"}], "explanations": {"心态": "“心态”指心里对事情的感受与看法，“他最近心态很好”符合句意。", "天气": "搭配：“天气”是外界环境，不能作为“他”的属性来评价，不说“他最近天气很好”。", "血型": "语义：血型是先天固定的，不会“最近”变化，也谈不上“很好”。", "籍贯": "语义：籍贯指祖籍或出生地，不是可以“最近”变好或变坏的状态。"}, "sentence_index": 0, "correct_answer": "心态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用心态写了一封信。", "explanation": "这里应该用〈用心〉（副词，“用心写”表示认真）。“心态”是名词，不能作状语修饰动词“写”。"}, {"text": "他把心态装进了箱子里。", "explanation": "这里应该用〈东西〉（指具体物品）。“心态”是抽象的心理状态，不能像东西一样被装进箱子。"}, {"text": "他有一把快乐的心态，每天都笑。", "explanation": "这里应该用量词〈种〉（一种心态）。“把”用于有柄的器具，不用于“心态”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心态", "is_correct": true, "explanation": "“心态”指内心的状态，听了朋友的话后“马上变好了”符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会因为听了朋友的话就马上改变。"}, {"text": "户口", "is_correct": false, "explanation": "语义：户口是登记的身份信息，不会因为一番话而“变好”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不会因为听了几句话就马上变化，也不说体重“变好了”。"}], "explanations": {"心态": "“心态”指内心的状态，听了朋友的话后“马上变好了”符合句意。", "年龄": "语义：年龄不会因为听了朋友的话就马上改变。", "户口": "语义：户口是登记的身份信息，不会因为一番话而“变好”。", "体重": "语义：体重不会因为听了几句话就马上变化，也不说体重“变好了”。"}, "sentence_index": 6, "correct_answer": "心态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈说，她有一片快乐的心态，总是笑。", "explanation": "这里应该用量词〈种〉（一种心态）。“片”多用于树叶、天空等平面事物，不用于“心态”。"}, {"text": "她是一位很有名的心态医生，帮助很多人。", "explanation": "这里应该用〈心理〉。“心理医生”是固定说法，“心态”不能用来指这一职业。"}, {"text": "她每天都把心态画下来，挂在墙上。", "explanation": "这里应该用〈风景〉（风景可以画下来）。“心态”是抽象的心理状态，无法被画下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛输了以后，他的一把心态慢慢好起来了。", "corrected_sentence": "比赛输了以后，他的心态慢慢好起来了。", "error_description": "“心态”前不能加量词“把”（“把”用于有柄的器具），不能说“他的一把心态”。这里应直接说“他的心态慢慢好起来了”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的心态好变了。", "corrected_sentence": "他的心态变好了。", "error_description": "动补结构应为“变好了”（动词加补语）。“好变了”的顺序错误，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
