INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心理状态；对事物的态度。", "primary_collocate": null, "pronunciation": "xīn tài", "ipa": "ɕin˥ tʰai˥˩", "syllable_count": 2, "sentences": [{"text": "面对失败，要有平和的心态。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时要调整好自己的心态。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对学习的心态很积极。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人应该有积极的心态。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房的人常有一种着急的心态。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用什么心态面对这件事？", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事要有放松的心态，别太紧张。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心态变了，不再怕困难。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好心态能帮你把事情做好。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要理解老人的心态。", "target_word": "心态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种心态", "label": "量词"}], "register": "中性", "sense_fingerprint": "心态·对人对事的心理状态与态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心态", "is_correct": true, "explanation": "“心态”指对人对事的心理状态与态度，“平和的心态”符合句意。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“平和”不能用来形容面积，面积只说大小。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是具体的家具，无法作为面对失败时的内心态度。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“成绩”可以说好坏，但不说“平和的成绩”，与“面对失败”也不相合。"}], "explanations": {"心态": "“心态”指对人对事的心理状态与态度，“平和的心态”符合句意。", "面积": "搭配：“平和”不能用来形容面积，面积只说大小。", "桌子": "语义：桌子是具体的家具，无法作为面对失败时的内心态度。", "成绩": "搭配：“成绩”可以说好坏，但不说“平和的成绩”，与“面对失败”也不相合。"}, "sentence_index": 0, "correct_answer": "心态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学学的是心态学，专门研究人的想法。", "explanation": "这里应该用〈心理学〉。“心态”不能作学科名称，“心理学”才是固定说法。"}, {"text": "他有一把积极的心态，总是乐观。", "explanation": "这里应该用量词〈种〉（一种心态）。“把”用于有柄的器具，不用于“心态”。"}, {"text": "他提出的心态很新颖。", "explanation": "这里应该用〈观点〉。“提出”和“新颖”都针对观点、想法，“心态”不能被提出，也不能说新颖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心态", "is_correct": true, "explanation": "“心态”指做事时的心理状态与态度，“放松的心态”符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“放松”不能修饰身高，身高只说高矮。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不是做事时的心理状态。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是外部环境，不能作为做事时的内心态度。"}], "explanations": {"心态": "“心态”指做事时的心理状态与态度，“放松的心态”符合句意。", "身高": "搭配：“放松”不能修饰身高，身高只说高矮。", "房子": "语义：房子是建筑，不是做事时的心理状态。", "天气": "语义：天气是外部环境，不能作为做事时的内心态度。"}, "sentence_index": 6, "correct_answer": "心态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要理解老人的一颗心态。", "explanation": "这里应该用量词〈种〉（一种心态）。“颗”用于心脏、珠粒等，不用于“心态”。"}, {"text": "他对家乡有很深的心态。", "explanation": "这里应该用〈感情〉。“很深”形容感情的深浅，“心态”不能用“很深”来形容。"}, {"text": "他制定的心态很周密。", "explanation": "这里应该用〈计划〉。“制定”和“周密”针对计划，“心态”不能被制定，也不说周密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对新工作的心态积极起来着。", "corrected_sentence": "他对新工作的心态积极起来了。", "error_description": "体标错误：“心态积极起来”表示变化已经发生，句末应用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把心态调整了好。", "corrected_sentence": "她把心态调整好了。", "error_description": "“调整”后的补语应紧跟动词，正确为“调整好了”。“调整了好”的补语位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
