INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90783, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奖学金是奖励学习好的学生的钱。", "primary_collocate": null, "pronunciation": "jiǎng xué jīn", "ipa": "tɕjɑŋ˨˩˦ ɕɥɛ˧˥ tɕin˥", "syllable_count": 3, "sentences": [{"text": "她拿到了奖学金。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔奖学金有五千块。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想申请奖学金去学习。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奖学金只给学习好的学生。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用奖学金买了一台电脑。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年发一次奖学金。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠奖学金读完了大学。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份奖学金很不容易得到。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你得过奖学金，真厉害！", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们怎么申请奖学金。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔奖学金", "label": "量词"}, {"form": "一份奖学金", "label": "量词"}, {"form": "獎學金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "奖给学习好的学生的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90783, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奖学金", "is_correct": true, "explanation": "奖学金：奖给学习好的学生的钱，“拿到”搭配它，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“拿到”搭配物品或证书，患病应说“得了感冒”。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是场所，不能被拿到。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不是可以拿到的东西。"}], "explanations": {"奖学金": "奖学金：奖给学习好的学生的钱，“拿到”搭配它，符合句意。", "感冒": "搭配：“拿到”搭配物品或证书，患病应说“得了感冒”。", "公园": "语义：公园是场所，不能被拿到。", "春天": "语义：春天是季节，不是可以拿到的东西。"}, "sentence_index": 0, "correct_answer": "奖学金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔奖学金毕业后要还给学校。", "explanation": "这里应该用〈贷款〉。奖学金是奖励给学生的钱，不用归还；毕业后要还的是助学贷款。"}, {"text": "她每个学期都要交奖学金。", "explanation": "这里应该用〈学费〉。学费是要交的钱，奖学金是发给学生的钱，不用交。"}, {"text": "他拿到了一台奖学金。", "explanation": "这里应该用〈笔〉或〈份〉。〈台〉用于机器，奖学金是钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奖学金", "is_correct": true, "explanation": "奖学金：奖励学习好的学生的钱，可以作为读完大学的凭借，符合句意。"}, {"text": "小学", "is_correct": false, "explanation": "语义：小学是学校的一个阶段，不能作为读完大学的凭借。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能作为读书的凭借。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“靠”要求能提供帮助的资源，地毯不能提供经济支持。"}], "explanations": {"奖学金": "奖学金：奖励学习好的学生的钱，可以作为读完大学的凭借，符合句意。", "小学": "语义：小学是学校的一个阶段，不能作为读完大学的凭借。", "沙发": "语义：沙发是家具，不能作为读书的凭借。", "地毯": "搭配：“靠”要求能提供帮助的资源，地毯不能提供经济支持。"}, "sentence_index": 6, "correct_answer": "奖学金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府每个月给老人发奖学金。", "explanation": "这里应该用〈补贴〉。补贴是给生活困难的人的帮助，奖学金是奖励学习成绩好的学生的钱。"}, {"text": "公司年底给员工发了一笔奖学金。", "explanation": "这里应该用〈奖金〉。奖金是单位发给员工的，奖学金只发给学生。"}, {"text": "他申请了一场奖学金。", "explanation": "这里应该用〈笔〉或〈份〉。〈场〉用于比赛、演出等，奖学金是钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她拿到了一只奖学金。", "corrected_sentence": "她拿到了一笔奖学金。", "error_description": "量词错误：奖学金是钱，应说“一笔奖学金”。“只”多用于动物或成对的东西，不能用于奖学金。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他靠一件奖学金读完了大学。", "corrected_sentence": "他靠一笔奖学金读完了大学。", "error_description": "量词错误：奖学金是钱，应说“一笔奖学金”。“件”用于衣服、事情等，不能用于奖学金。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
