INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奖励学习成绩优异的学生的钱款。", "primary_collocate": null, "pronunciation": "jiǎng xué jīn", "ipa": "tɕjɑŋ˨˩˦ ɕɥɛ˧˥ tɕin˥", "syllable_count": 3, "sentences": [{"text": "因为成绩很好，他得了奖学金。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奖学金可以帮他交学费。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学期谁得奖学金？", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把奖学金寄给了妈妈。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家奖学金比学校的多一些。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了拿奖学金，他每天都很努力。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奖学金不是礼物，是对好成绩的奖励。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次拿奖学金时特别高兴。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请奖学金要先写一封信。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有奖学金，只好打工。", "target_word": "奖学金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔奖学金", "label": "量词"}, {"form": "一份奖学金", "label": "量词"}, {"form": "国家奖学金", "label": "复合"}, {"form": "獎學金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "奖励成绩优异学生的钱款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奖学金", "is_correct": true, "explanation": "奖学金：因成绩好而得到的钱，“得了”搭配它，符合句意。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是病症，与“成绩很好”而获得奖励的语境不符，不能填入此句。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不是可以“得”到的东西，与成绩无关。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能“得”到，与“成绩很好”的语境不符。"}], "explanations": {"奖学金": "奖学金：因成绩好而得到的钱，“得了”搭配它，符合句意。", "发烧": "语义：发烧是病症，与“成绩很好”而获得奖励的语境不符，不能填入此句。", "雨水": "语义：雨水不是可以“得”到的东西，与成绩无关。", "石头": "语义：石头不能“得”到，与“成绩很好”的语境不符。"}, "sentence_index": 0, "correct_answer": "奖学金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司上班，每个月领的奖学金是他的薪水。", "explanation": "这里应该用〈工资〉。工资是工作的报酬，奖学金是奖励学习成绩好的学生的钱，不能当薪水。"}, {"text": "奖学金一般在开学前交。", "explanation": "这里应该用〈学费〉。学费是要交的钱，奖学金是发给学生的钱，不能交。"}, {"text": "她得了一辆奖学金。", "explanation": "这里应该用〈笔〉或〈份〉。〈辆〉用于车辆，奖学金是钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奖学金", "is_correct": true, "explanation": "奖学金：奖励成绩优异的学生的钱，是对好成绩的奖励，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不可能是对好成绩的奖励。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是奖励，与“是……的奖励”矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“奖励”的内容一般是奖品或奖金，作业是任务，不能作为奖励。"}], "explanations": {"奖学金": "奖学金：奖励成绩优异的学生的钱，是对好成绩的奖励，符合句意。", "感冒": "语义：感冒是疾病，不可能是对好成绩的奖励。", "垃圾": "语义：垃圾不是奖励，与“是……的奖励”矛盾。", "作业": "搭配：“奖励”的内容一般是奖品或奖金，作业是任务，不能作为奖励。"}, "sentence_index": 6, "correct_answer": "奖学金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "社区每个月给困难家庭发奖学金。", "explanation": "这里应该用〈补贴〉。补贴是给困难家庭的帮助，奖学金是奖励成绩好的学生的钱。"}, {"text": "这家公司每年给优秀员工发奖学金。", "explanation": "这里应该用〈奖金〉。奖金是单位发给员工的，奖学金只发给学生。"}, {"text": "她得了一条奖学金。", "explanation": "这里应该用〈笔〉或〈份〉。〈条〉用于长条形的东西，奖学金是钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这学期他拿到一颗奖学金。", "corrected_sentence": "这学期他拿到一笔奖学金。", "error_description": "量词错误：奖学金是钱，应说“一笔奖学金”。“颗”用于小而圆的东西，不能用于奖学金。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一本奖学金存进了银行。", "corrected_sentence": "她把一笔奖学金存进了银行。", "error_description": "量词错误：奖学金是钱，应说“一笔奖学金”。“本”用于书本，不能用于奖学金。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
