INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90785, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人对你很好、帮了你。", "primary_collocate": null, "pronunciation": "ēn", "ipa": "ən˥", "syllable_count": 1, "sentences": [{"text": "他帮过我很多次，对我有恩。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我受过他的恩，一定要好好回报他。", "target_word": "恩", "complexity_tier": "T3", "furigana": "wǒ shòuguo tā de ēn, yídìng yào hǎohāo huíbào tā.", "sentence_source": "generated"}, {"text": "他在我最难的时候帮了我，我一辈子都记得他的恩。", "target_word": "恩", "complexity_tier": "T3", "furigana": "tā zài wǒ zuì nán de shíhou bāng le wǒ, wǒ yíbèizi dōu jìde tā de ēn.", "sentence_source": "generated"}, {"text": "你有恩于我，我不会忘。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对我们有恩，我们要报答。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年他借钱给我，我一直记着这份恩。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她救过我，我欠她一份恩。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有恩的人，我们一定要感谢。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居照顾我家多年，对我家有恩。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我终于有机会回报他的恩了。", "target_word": "恩", "complexity_tier": "T3", "furigana": "wǒ zhōngyú yǒu jīhuì huíbào tā de ēn le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "中性", "sense_fingerprint": "恩：别人对自己有帮助、有恩情的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90785, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。恩（ēn）指对自己有帮助、有恩情的事。"}, {"text": "安", "is_correct": false, "explanation": "安（ān）与 ēn 的韵母不同（an 与 en），声调相同，意思是平安。"}, {"text": "因", "is_correct": false, "explanation": "因（yīn）与 ēn 韵母不同（in 与 en），声调相同，意思是因为。"}, {"text": "根", "is_correct": false, "explanation": "根（gēn）比 ēn 多一个 g 声母，韵母与声调相同，意思是根。"}], "explanations": {"恩": "正确答案。恩（ēn）指对自己有帮助、有恩情的事。", "安": "安（ān）与 ēn 的韵母不同（an 与 en），声调相同，意思是平安。", "因": "因（yīn）与 ēn 韵母不同（in 与 en），声调相同，意思是因为。", "根": "根（gēn）比 ēn 多一个 g 声母，韵母与声调相同，意思是根。"}, "sentence_index": null, "correct_answer": "恩"}, "level_3": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。“对我有恩”指对我有过帮助，与“帮过我很多次”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指事物的色彩，不能用来指对我施过的帮助。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状指事物的外形，与帮助、人情无关。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“对我有名字”不成立，与“帮过我很多次”的语境也不相符。"}], "explanations": {"恩": "正确答案。“对我有恩”指对我有过帮助，与“帮过我很多次”相合。", "颜色": "语义：颜色指事物的色彩，不能用来指对我施过的帮助。", "形状": "语义：形状指事物的外形，与帮助、人情无关。", "名字": "搭配：“对我有名字”不成立，与“帮过我很多次”的语境也不相符。"}, "sentence_index": 0, "correct_answer": "恩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的恩放在桌子上，我很喜欢。", "explanation": "这里应该用〈礼物〉。恩指无形的帮助与情谊，不是可以放在桌上的东西。"}, {"text": "你给我一把恩，我不会忘。", "explanation": "这里应该用〈份〉。量词〈把〉多用于有柄的器具，恩要用量词〈份〉。"}, {"text": "这份恩是红色的，我一直记着。", "explanation": "这里不能用来形容颜色。恩是无形的帮助与情谊，没有颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90785, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。恩（ēn）指对自己有帮助、有恩情的事。"}, {"text": "鞍", "is_correct": false, "explanation": "鞍（ān）与 ēn 韵母不同（an 与 en），声调相同，意思是马鞍。"}, {"text": "奔", "is_correct": false, "explanation": "奔（bēn）比 ēn 多一个 b 声母，韵母与声调相同，意思是跑。"}, {"text": "因", "is_correct": false, "explanation": "因（yīn）与 ēn 韵母不同（in 与 en），声调相同，意思是因为。"}], "explanations": {"恩": "正确答案。恩（ēn）指对自己有帮助、有恩情的事。", "鞍": "鞍（ān）与 ēn 韵母不同（an 与 en），声调相同，意思是马鞍。", "奔": "奔（bēn）比 ēn 多一个 b 声母，韵母与声调相同，意思是跑。", "因": "因（yīn）与 ēn 韵母不同（in 与 en），声调相同，意思是因为。"}, "sentence_index": null, "correct_answer": "恩"}, "level_3": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。“欠她一份恩”指欠下对方救助的人情，与“救过我”相合。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿的物品，不是可以欠下的人情。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“一份手机”不自然，手机也不能表示所欠的人情。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，与救助、人情无关。"}], "explanations": {"恩": "正确答案。“欠她一份恩”指欠下对方救助的人情，与“救过我”相合。", "鞋子": "语义：鞋子是穿的物品，不是可以欠下的人情。", "手机": "搭配：“一份手机”不自然，手机也不能表示所欠的人情。", "钥匙": "语义：钥匙是开锁的工具，与救助、人情无关。"}, "sentence_index": 6, "correct_answer": "恩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的恩很好，我很高兴。", "explanation": "这里应该用〈天气〉。恩指帮助与情谊，不能用来形容天气。"}, {"text": "这个恩很简单，大家都懂。", "explanation": "这里应该用〈道理〉。恩指帮助与情谊，不能用“简单”来形容。"}, {"text": "他的恩很慢，我们等了很久。", "explanation": "这里应该用〈脚步〉。恩不是动作，不能用“慢”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他帮过我一次，我欠他一只大恩。", "corrected_sentence": "他帮过我一次，我欠他一份大恩。", "error_description": "量词错误：恩应配量词“份”，“只”用于动物或成对的东西，应说“一份大恩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直记着他的恩大。", "corrected_sentence": "我一直记着他的大恩。", "error_description": "语序错误：形容词“大”应放在名词“恩”前作定语，应说“大恩”，不说“恩大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
