INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "恩惠；深厚的情谊。", "primary_collocate": null, "pronunciation": "ēn", "ipa": "ən˥", "syllable_count": 1, "sentences": [{"text": "这份恩，我一辈子都不会忘。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我有恩，我一定要报答他。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，他的大恩我永远记得。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我欠她的恩，以后一定报答她。", "target_word": "恩", "complexity_tier": "T3", "furigana": "wǒ qiàn tā de ēn, yǐhòu yídìng bàodá tā.", "sentence_source": "generated"}, {"text": "你对我的恩，我今天才明白有多重。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要记得别人的恩，也要懂得报答。", "target_word": "恩", "complexity_tier": "T3", "furigana": "zuò rén yào jìde biérén de ēn, yě yào dǒngde bàodá.", "sentence_source": "generated"}, {"text": "朋友之间不要总提自己的恩。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小恩不值得一提。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说，母亲的恩比山还重。", "target_word": "恩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我的恩，我一直记在心里。", "target_word": "恩", "complexity_tier": "T3", "furigana": "tā gěi wǒ de ēn, wǒ yìzhí jì zài xīnlǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}], "register": "中性", "sense_fingerprint": "恩：别人给予的恩惠与深厚情谊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。恩（ēn）指别人给予的恩惠与深厚情谊。"}, {"text": "安", "is_correct": false, "explanation": "安（ān）与 ēn 的韵母不同（an 与 en），声调相同，意思是平安。"}, {"text": "摁", "is_correct": false, "explanation": "摁（èn）与 ēn 声调不同（第四声与第一声），意思是用手按、压。"}, {"text": "因", "is_correct": false, "explanation": "因（yīn）与 ēn 韵母不同（in 与 en），声调相同，意思是原因、因为。"}, {"text": "根", "is_correct": false, "explanation": "根（gēn）比 ēn 多一个 g 声母，韵母与声调相同，意思是根。"}], "explanations": {"恩": "正确答案。恩（ēn）指别人给予的恩惠与深厚情谊。", "安": "安（ān）与 ēn 的韵母不同（an 与 en），声调相同，意思是平安。", "摁": "摁（èn）与 ēn 声调不同（第四声与第一声），意思是用手按、压。", "因": "因（yīn）与 ēn 韵母不同（in 与 en），声调相同，意思是原因、因为。", "根": "根（gēn）比 ēn 多一个 g 声母，韵母与声调相同，意思是根。"}, "sentence_index": null, "correct_answer": "恩"}, "level_3": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。“这份恩”指别人给的恩惠，与“一辈子都不会忘”相合。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池是供电的元件，不是别人给予的恩惠，也不会让人一辈子都记得。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是固定零件的小件，与别人给予的恩惠无关。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是别人给予的恩惠，也不会让人一辈子都记得。"}], "explanations": {"恩": "正确答案。“这份恩”指别人给的恩惠，与“一辈子都不会忘”相合。", "电池": "语义：电池是供电的元件，不是别人给予的恩惠，也不会让人一辈子都记得。", "螺丝": "语义：螺丝是固定零件的小件，与别人给予的恩惠无关。", "汽油": "语义：汽油是燃料，不是别人给予的恩惠，也不会让人一辈子都记得。"}, "sentence_index": 0, "correct_answer": "恩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份恩有三公斤重，我搬不动。", "explanation": "这里应该用〈箱子〉。恩指别人给予的恩惠与情谊，是无形的，没有斤两，不能搬。"}, {"text": "我欠她一只恩，以后一定报答她。", "explanation": "这里应该用〈份〉。量词〈只〉用于动物或成对的东西，恩要用量词〈份〉。"}, {"text": "这份恩的颜色很红，我一直记着。", "explanation": "这里不能用来形容颜色。恩指别人给的帮助与情谊，是无形的，没有颜色，不能说“红”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90786, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。恩（ēn）指别人给予的恩惠与深厚情谊。"}, {"text": "鞍", "is_correct": false, "explanation": "鞍（ān）与 ēn 韵母不同（an 与 en），声调相同，意思是马鞍。"}, {"text": "奔", "is_correct": false, "explanation": "奔（bēn）比 ēn 多一个 b 声母，韵母与声调相同，意思是跑。"}, {"text": "跟", "is_correct": false, "explanation": "跟（gēn）比 ēn 多一个 g 声母，韵母与声调相同，意思是跟随。"}], "explanations": {"恩": "正确答案。恩（ēn）指别人给予的恩惠与深厚情谊。", "鞍": "鞍（ān）与 ēn 韵母不同（an 与 en），声调相同，意思是马鞍。", "奔": "奔（bēn）比 ēn 多一个 b 声母，韵母与声调相同，意思是跑。", "跟": "跟（gēn）比 ēn 多一个 g 声母，韵母与声调相同，意思是跟随。"}, "sentence_index": null, "correct_answer": "恩"}, "level_3": {"options": [{"text": "恩", "is_correct": true, "explanation": "正确答案。“自己的恩”指自己帮助过别人的情分，“不要总提”正好对应。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“提自己的脸色”不成立，脸色不是朋友之间会反复提起的人情。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是朋友之间会反复提起的人情。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光照下的形象，不能用来指需要反复提起的人情。"}], "explanations": {"恩": "正确答案。“自己的恩”指自己帮助过别人的情分，“不要总提”正好对应。", "脸色": "搭配：“提自己的脸色”不成立，脸色不是朋友之间会反复提起的人情。", "汽油": "语义：汽油是燃料，不是朋友之间会反复提起的人情。", "影子": "语义：影子是光照下的形象，不能用来指需要反复提起的人情。"}, "sentence_index": 6, "correct_answer": "恩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我的恩，我一直放在家里。", "explanation": "这里应该用〈礼物〉。恩指帮助与情谊，是无形的，不能说放在家里。"}, {"text": "这次考试的恩很好，我很高兴。", "explanation": "这里应该用〈成绩〉。恩指帮助与情谊，不指考试的结果。"}, {"text": "这盘菜的恩很咸，我们都吃不下去。", "explanation": "这里应该用〈味道〉。恩指帮助与情谊，没有咸淡，不能用来形容菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
