INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90787, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生发是新事物、新叶或新情感产生出来。", "primary_collocate": null, "pronunciation": "shēng fā", "ipa": "ʂɤŋ˥ fa˥", "syllable_count": 2, "sentences": [{"text": "春风一吹，田野里的新草开始生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的城市文化正在这里生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水多的时候，树上的新叶会很快生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了那本书，我心里生发了很多感想。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次旅行后，他心里生发出新的计划。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来后，湖边的小花都生发出来了。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老师的鼓励下，我心里生发出了对画画的兴趣。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城里，很多故事都从这里生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的竹林里，新笋一个个生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑话让大家心里生发出快乐。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生发了", "label": "体标"}, {"form": "生發", "label": "繁体"}], "register": "书面", "sense_fingerprint": "新事物、新叶或新情感产生出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生发", "is_correct": true, "explanation": "正确答案：生发。句子说春风一吹，新草开始生长出来。"}, {"text": "凋零", "is_correct": false, "explanation": "语义：“春风一吹”带来生机，与“凋零”的衰败相反。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“春风一吹”的暖意与“冻结”的寒冷状态相冲突。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”多用于火、灯，不说“草开始熄灭”。"}], "explanations": {"生发": "正确答案：生发。句子说春风一吹，新草开始生长出来。", "凋零": "语义：“春风一吹”带来生机，与“凋零”的衰败相反。", "冻结": "语义：“春风一吹”的暖意与“冻结”的寒冷状态相冲突。", "熄灭": "搭配：“熄灭”多用于火、灯，不说“草开始熄灭”。"}, "sentence_index": 0, "correct_answer": "生发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的孩子这一年生发了十厘米。", "explanation": "这里应该用〈长〉。生发指新事物、新感情的产生，不用于人的身高增加。"}, {"text": "爱迪生生发了电灯。", "explanation": "这里应该用〈发明〉。生发指自然产生或感情的萌生，不用于人为创造的器物。"}, {"text": "我的弟弟今天生发了一个漂亮的娃娃。", "explanation": "搭配：“娃娃”是被制作出来的，应说〈做〉或〈买〉，不能说“生发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生发", "is_correct": true, "explanation": "正确答案：生发。句子说在老师的鼓励下，兴趣产生了。"}, {"text": "萎缩", "is_correct": false, "explanation": "搭配：“萎缩”多用于器官或组织，不说心里萎缩出兴趣。"}, {"text": "消退", "is_correct": false, "explanation": "语义：“在老师的鼓励下”是积极情况，与“消退”的减弱相冲突。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“老师的鼓励”的积极语境与“冷却”的降温相冲突，兴趣不会因此冷却。"}], "explanations": {"生发": "正确答案：生发。句子说在老师的鼓励下，兴趣产生了。", "萎缩": "搭配：“萎缩”多用于器官或组织，不说心里萎缩出兴趣。", "消退": "语义：“在老师的鼓励下”是积极情况，与“消退”的减弱相冲突。", "冷却": "语义：“老师的鼓励”的积极语境与“冷却”的降温相冲突，兴趣不会因此冷却。"}, "sentence_index": 6, "correct_answer": "生发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的笑话给大家生发了快乐。", "explanation": "这里应该用〈带来〉。“生发”不能用“给”引出受益对象，应说“他的笑话给大家带来了快乐”。"}, {"text": "这场争论生发了大家的注意。", "explanation": "这里应该用〈引起〉。“注意”不能说“生发”，应说“引起大家的注意”。"}, {"text": "这家工厂每天生发一千台电脑。", "explanation": "这里应该用〈生产〉。生发指新事物、新想法或感情的自然萌生，不用于工厂的批量制造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片山林的小草在春天里生发了了。", "corrected_sentence": "这片山林的小草在春天里生发了。", "error_description": "动态助词“了”已经附在“生发”之后，不能再重复加一个“了”。错误形式：“生发了了”；正确形式：“生发了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几句话在他心里生发出了了新的想法。", "corrected_sentence": "几句话在他心里生发出了新的想法。", "error_description": "动态助词“了”已经附在“出”之后，不能再重复加一个“了”。错误形式：“生发出了了”；正确形式：“生发出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
