INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90788, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90788, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "生发是新事物、新情感或新芽产生并发展。", "primary_collocate": null, "pronunciation": "shēng fā", "ipa": "ʂɤŋ˥ fa˥", "syllable_count": 2, "sentences": [{"text": "春天到了，万物都开始生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子们笑，我心里生发出一种温暖。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种子在雨后慢慢生发出新芽。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小故事让我心里生发了许多想法。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场雨后，山上的小草又生发了。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这首老歌，我心里生发出很多回忆。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的想法常常在讨论中生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春雨过后，田里的小苗一天天生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到别人的帮助，他心中生发出一股感激之情。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的希望在大家心里慢慢生发。", "target_word": "生发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生发了", "label": "体标"}, {"form": "生發", "label": "繁体"}], "register": "书面", "sense_fingerprint": "新事物、新情感或新芽产生并发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生发", "is_correct": true, "explanation": "正确答案：生发。句子说春天万物开始生发新的生机。"}, {"text": "凋零", "is_correct": false, "explanation": "语义：“春天到了”的生机与“凋零”的衰败相反，不能说万物开始凋零。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”是冬季景象，与“春天到了”的季节相冲突。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”多用于火、灯，不说“万物开始熄灭”。"}], "explanations": {"生发": "正确答案：生发。句子说春天万物开始生发新的生机。", "凋零": "语义：“春天到了”的生机与“凋零”的衰败相反，不能说万物开始凋零。", "冻结": "语义：“冻结”是冬季景象，与“春天到了”的季节相冲突。", "熄灭": "搭配：“熄灭”多用于火、灯，不说“万物开始熄灭”。"}, "sentence_index": 0, "correct_answer": "生发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵小树一年里生发了两米。", "explanation": "这里应该用〈生长〉。生发指新事物、新想法或感情的产生，不用于树木高度的增加。"}, {"text": "他一个月生发了三斤。", "explanation": "这里应该用〈长〉或〈胖〉。生发指新事物、新想法或感情的产生，不用于人体重量的增加。"}, {"text": "妈妈的话让我的眼泪在心里生发了。", "explanation": "搭配：眼泪应说〈流出〉，不能说“生发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生发", "is_correct": true, "explanation": "正确答案：生发。句子说好的想法在讨论中不断产生。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”用于建筑、设施，不能用于想法。"}, {"text": "煮熟", "is_correct": false, "explanation": "搭配：“煮熟”用于食物，不能说想法在讨论中煮熟。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”多用于冰雪，不说想法在讨论中融化。"}], "explanations": {"生发": "正确答案：生发。句子说好的想法在讨论中不断产生。", "拆除": "搭配：“拆除”用于建筑、设施，不能用于想法。", "煮熟": "搭配：“煮熟”用于食物，不能说想法在讨论中煮熟。", "融化": "搭配：“融化”多用于冰雪，不说想法在讨论中融化。"}, "sentence_index": 6, "correct_answer": "生发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里生发出了一锅好汤。", "explanation": "这里应该用〈熬出〉。生发指新事物、新想法或感情的自然萌生，不用于人为制作的食物。"}, {"text": "这位画家在纸上生发了一只猫。", "explanation": "搭配：“生发”指新事物、新感情的产生，不能说“生发一只猫”，应说〈画出〉。"}, {"text": "她去年生发了一个女儿。", "explanation": "这里应该用〈生育〉。生发指新事物、新想法或感情的产生，不用于人的生育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天一到，树枝上都生发了出新芽。", "corrected_sentence": "春天一到，树枝上都生发出了新芽。", "error_description": "结果补语“出”应紧跟在“生发”之后，写作“生发出了新芽”；写成“生发了出新芽”，“出”被挪到“了”之后，补语位置错误，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌让我心里了生发出许多回忆。", "corrected_sentence": "这首歌让我心里生发出许多回忆。", "error_description": "“了”放在“生发”前面是错误的，时态助词应放在动词或补语之后。错误形式：“心里了生发”；正确形式：“心里生发出许多回忆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
