INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "企业各类产品在整体中的构成与比例。", "primary_collocate": null, "pronunciation": "chǎn pǐn jié gòu", "ipa": "ʈʂʰan˧˥ pʰin˨˩ tɕjɛ˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "这家公司的产品结构很简单。", "target_word": "产品结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要调整产品结构。", "target_word": "产品结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想改善产品结构。", "target_word": "产品结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "产品结构太单一，公司卖得不好。", "target_word": "产品结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个工厂的产品结构已经变了。", "target_word": "产品结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年他们的产品结构有很大变化。", "target_word": "产品结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的产品结构能让公司赚更多钱。", "target_word": "产品结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报告里分析了产品结构。", "target_word": "产品结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在研究公司的产品结构。", "target_word": "产品结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新产品多了，产品结构变得更合理。", "target_word": "产品结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种产品结构", "label": "量词"}, {"form": "产品结构调整", "label": "复合"}], "register": "中性", "sense_fingerprint": "企业各类产品所占的构成和比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产品结构", "is_correct": true, "explanation": "正确：“产品结构”指企业产品的构成，可以说“这家公司的产品结构很简单”。"}, {"text": "员工年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不能用“很简单”来形容。"}, {"text": "注册资本", "is_correct": false, "explanation": "搭配：“很简单”不搭配注册资本这类金额，说不通。"}, {"text": "员工身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，不能说“公司的员工身高很简单”。"}], "explanations": {"产品结构": "正确：“产品结构”指企业产品的构成，可以说“这家公司的产品结构很简单”。", "员工年龄": "语义：“年龄”是人的岁数，不能用“很简单”来形容。", "注册资本": "搭配：“很简单”不搭配注册资本这类金额，说不通。", "员工身高": "体貌：身高是人的外形特征，不能说“公司的员工身高很简单”。"}, "sentence_index": 0, "correct_answer": "产品结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的产品结构很长。", "explanation": "这里应该用〈产品线〉。产品线指一家公司的产品系列，可以说长或短；产品结构说的是各类产品所占的构成比例，不谈长短。"}, {"text": "这家公司有一把产品结构。", "explanation": "这里应该用〈种〉。量词〈把〉用于有柄或可握的器具，产品结构是抽象的构成，应说“一种产品结构”。"}, {"text": "这家公司的产品结构包括董事会和三个部门。", "explanation": "此句说的是公司的组织结构（董事会、部门的层级），不是产品构成。产品结构只指企业各类产品所占的构成与比例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产品结构", "is_correct": true, "explanation": "正确：“好的产品结构”能让公司赚钱，搭配合理。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，与公司赚钱无关。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：国籍是人的身份归属，“好的国籍”不能让公司赚钱。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不会让公司赚钱，句子不通。"}], "explanations": {"产品结构": "正确：“好的产品结构”能让公司赚钱，搭配合理。", "体重": "体貌：体重是人的身体特征，与公司赚钱无关。", "国籍": "语义：国籍是人的身份归属，“好的国籍”不能让公司赚钱。", "温度": "语义：温度不会让公司赚钱，句子不通。"}, "sentence_index": 6, "correct_answer": "产品结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新产品多了，产品结构增加到三百种。", "explanation": "这里应该用〈产品数量〉。产品结构是各类产品所占的比例，不能说增加到几种；说产品数量增加到多少种要用〈产品数量〉。"}, {"text": "这篇论文的产品结构分成三部分。", "explanation": "此句说的是论文的章节安排，不是企业产品的构成。产品结构只指企业各类产品所占的构成与比例。"}, {"text": "新产品多了，我们有了一台产品结构。", "explanation": "这里应该用〈种〉。量词〈台〉用于机器，产品结构不是器械，应说“一种产品结构”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司有一台产品结构，比较简单。", "corrected_sentence": "我们公司有一种产品结构，比较简单。", "error_description": "量词错误：“产品结构”应搭配“种”，写成“一台”是把“台”（用于机器）用在产品构成上。正确应为“一种产品结构”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司把产品结构调整很好。", "corrected_sentence": "公司把产品结构调整得很好。", "error_description": "补语错误：“调整”后接程度补语时要用“得”，应为“调整得很好”；少了“得”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
