INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90795, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留意是注意地看着某人某物，观察其动静。", "primary_collocate": null, "pronunciation": "liú yì", "ipa": "ljoʊ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "走在路上，请留意前面的车。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你留意一下他的表情。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一直留意着孩子的动作。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，要留意黑板上的字。", "target_word": "留意", "complexity_tier": "T3", "furigana": "lǎo shī shuō, yào liú yì hēi bǎn shàng de zì.", "sentence_source": "generated"}, {"text": "我留意过那家店，人很多。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他留意着窗外的动静。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请留意天上的云怎么变化。", "target_word": "留意", "complexity_tier": "T3", "furigana": "qǐng liú yì tiān shàng de yún zěn me biàn huà.", "sentence_source": "generated"}, {"text": "她没有留意桌上的小纸条。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你留意他手里拿着什么。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机一直留意着后面的灯光。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "留意了", "label": "体标"}, {"form": "留意着", "label": "体标"}, {"form": "留意过", "label": "体标"}], "register": "中性", "sense_fingerprint": "注意地看着某人某物，观察其动静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90795, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "留意", "is_correct": true, "explanation": "正确：“留意”是小心看着、注意。"}, {"text": "流利", "is_correct": false, "explanation": "第二个音节声母不同：“利”是 lì，“意”没有声母（yì），意思是说话或写作流畅。"}, {"text": "六亿", "is_correct": false, "explanation": "第一个音节声调不同：“六”是第四声（liù），“留”是第二声（liú），意思是六亿。"}, {"text": "六一", "is_correct": false, "explanation": "两个音节的声调都与“留意”不同：“六一”（liù yī）意思是六月一日，常指儿童节。"}, {"text": "流气", "is_correct": false, "explanation": "第二个音节声母不同：“气”是 q，“意”没有声母，意思是轻浮、不正派的样子。"}], "explanations": {"留意": "正确：“留意”是小心看着、注意。", "流利": "第二个音节声母不同：“利”是 lì，“意”没有声母（yì），意思是说话或写作流畅。", "六亿": "第一个音节声调不同：“六”是第四声（liù），“留”是第二声（liú），意思是六亿。", "六一": "两个音节的声调都与“留意”不同：“六一”（liù yī）意思是六月一日，常指儿童节。", "流气": "第二个音节声母不同：“气”是 q，“意”没有声母，意思是轻浮、不正派的样子。"}, "sentence_index": null, "correct_answer": "留意"}, "level_3": {"options": [{"text": "留意", "is_correct": true, "explanation": "正确：“留意”是注意地看着，与“走在路上”的安全提醒相符。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”是不理会，与“走在路上，请……前面的车”的安全提醒相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多用于风景、作品，不用来指提醒自己注意前面的车。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是把坏了的东西修好，前面的车并没有损坏，句意不通。"}], "explanations": {"留意": "正确：“留意”是注意地看着，与“走在路上”的安全提醒相符。", "忽略": "语义：“忽略”是不理会，与“走在路上，请……前面的车”的安全提醒相反。", "欣赏": "搭配：“欣赏”多用于风景、作品，不用来指提醒自己注意前面的车。", "修理": "语义：“修理”是把坏了的东西修好，前面的车并没有损坏，句意不通。"}, "sentence_index": 0, "correct_answer": "留意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上留意一杯牛奶。", "explanation": "这里应该用〈喝〉。“留意”表示注意地看着，不表示喝东西，喝牛奶要用“喝”。"}, {"text": "工人每天留意两百吨矿石。", "explanation": "这里应该用〈开采〉。“留意”不表示挖掘资源，开采矿石要用“开采”。"}, {"text": "市政府留意了一座新桥。", "explanation": "这里应该用〈修建〉。“留意”不表示建造，建一座新桥要用“修建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留意", "is_correct": true, "explanation": "正确：“留意”是注意、看着，与“请……天上的云怎么变化”相符。"}, {"text": "控制", "is_correct": false, "explanation": "搭配：“控制”多用于局面、情绪，不能说控制天上的云怎么变化。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清除脏物，天上的云不需要也不能被打扫。"}, {"text": "追逐", "is_correct": false, "explanation": "语义：“追逐”是紧跟着赶，句中是请人观察云的变化，与追赶的意思不符。"}], "explanations": {"留意": "正确：“留意”是注意、看着，与“请……天上的云怎么变化”相符。", "控制": "搭配：“控制”多用于局面、情绪，不能说控制天上的云怎么变化。", "打扫": "语义：“打扫”是清除脏物，天上的云不需要也不能被打扫。", "追逐": "语义：“追逐”是紧跟着赶，句中是请人观察云的变化，与追赶的意思不符。"}, "sentence_index": 6, "correct_answer": "留意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里留意了三个菜，大家吃得很饱。", "explanation": "这里应该用〈做〉。“留意”表示注意地看着，不表示烹饪，做菜要用“做”。"}, {"text": "他留意了这项任务，三天就做完了。", "explanation": "这里应该用〈完成〉。“留意”表示注意，不表示做完某件事，完成任务要用“完成”。"}, {"text": "工人用卡车留意这批货物。", "explanation": "这里应该用〈运〉。“留意”不表示搬运，用卡车运货物要用“运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他留意很仔细。", "corrected_sentence": "他留意得很仔细。", "error_description": "补语错误：“留意”后带程度补语时要用“得”连接，应说“留意得很仔细”，漏掉“得”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你留意着一下这个问题。", "corrected_sentence": "请你留意一下这个问题。", "error_description": "体标错误：“着”表示持续，与表示短时尝试的“一下”语义冲突，“留意着”不能与“一下”同用。应说“请你留意一下这个问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
