INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90796, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "注意，小心。", "primary_collocate": null, "pronunciation": "liú yì", "ipa": "ljoʊ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "过马路时要留意安全。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天地滑，大家留意脚下。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请留意天气变化，别感冒。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很小心，处处留意。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "留意别把手机忘在车上。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时要留意红绿灯。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有火，你要留意一点。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会留意路上的积水，别滑倒。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去人多的地方，要留意自己的东西。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家请留意，下一站就要下车了。", "target_word": "留意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "留意了", "label": "体标"}, {"form": "留意着", "label": "体标"}, {"form": "留意过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对可能的情况或危险提高注意、小心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90796, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "留意", "is_correct": true, "explanation": "正确：“留意”是注意、小心。"}, {"text": "流利", "is_correct": false, "explanation": "第二个音节声母不同：“利”是 lì，“意”没有声母（yì），意思是说话或写作流畅。"}, {"text": "六亿", "is_correct": false, "explanation": "第一个音节声调不同：“六”是第四声（liù），“留”是第二声（liú），意思是六亿。"}, {"text": "六一", "is_correct": false, "explanation": "两个音节的声调都与“留意”不同：“六一”（liù yī）意思是六月一日，常指儿童节。"}, {"text": "流气", "is_correct": false, "explanation": "第二个音节声母不同：“气”是 q，“意”没有声母，意思是轻浮、不正派的样子。"}], "explanations": {"留意": "正确：“留意”是注意、小心。", "流利": "第二个音节声母不同：“利”是 lì，“意”没有声母（yì），意思是说话或写作流畅。", "六亿": "第一个音节声调不同：“六”是第四声（liù），“留”是第二声（liú），意思是六亿。", "六一": "两个音节的声调都与“留意”不同：“六一”（liù yī）意思是六月一日，常指儿童节。", "流气": "第二个音节声母不同：“气”是 q，“意”没有声母，意思是轻浮、不正派的样子。"}, "sentence_index": null, "correct_answer": "留意"}, "level_3": {"options": [{"text": "留意", "is_correct": true, "explanation": "正确：“留意”是注意、小心，与“过马路时要……安全”相符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”是不当一回事，与“过马路时要……安全”的提醒相反。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于器物，安全不能修理，不说修理安全。"}, {"text": "追赶", "is_correct": false, "explanation": "语义：“追赶”是快步赶上，过马路时要的是关注安全，不是追赶安全。"}], "explanations": {"留意": "正确：“留意”是注意、小心，与“过马路时要……安全”相符。", "忽视": "语义：“忽视”是不当一回事，与“过马路时要……安全”的提醒相反。", "修理": "搭配：“修理”用于器物，安全不能修理，不说修理安全。", "追赶": "语义：“追赶”是快步赶上，过马路时要的是关注安全，不是追赶安全。"}, "sentence_index": 0, "correct_answer": "留意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校每年留意一批新教材。", "explanation": "这里应该用〈编写〉。“留意”表示注意，不表示写作或编辑书籍，编写教材要用“编写”。"}, {"text": "他留意了一篇新论文。", "explanation": "这里应该用〈撰写〉。“留意”表示注意，不表示动笔写文章，写论文要用“撰写”。"}, {"text": "工人用锤子留意了那座老房子。", "explanation": "这里应该用〈拆〉。“留意”表示注意、小心，不表示拆毁，用锤子拆房子要用“拆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留意", "is_correct": true, "explanation": "正确：“留意”是注意、小心，与“厨房里有火”的提醒相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“厨房里有火，你要……一点”的提醒相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏，与“厨房里有火，你要……一点”的安全提醒不符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与提醒注意火的语境不符。"}], "explanations": {"留意": "正确：“留意”是注意、小心，与“厨房里有火”的提醒相符。", "忘记": "语义：“忘记”与“厨房里有火，你要……一点”的提醒相反。", "欣赏": "语义：“欣赏”是赞赏，与“厨房里有火，你要……一点”的安全提醒不符。", "讨厌": "语义：“讨厌”表示不喜欢，与提醒注意火的语境不符。"}, "sentence_index": 6, "correct_answer": "留意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导演用三个月留意了一部电影。", "explanation": "这里应该用〈拍〉。“留意”表示注意、小心，不表示拍摄，拍电影要用“拍”。"}, {"text": "医生用新药留意了那种病毒。", "explanation": "这里应该用〈消灭〉。“留意”表示注意、小心，不表示清除，用药消灭病毒要用“消灭”。"}, {"text": "他在杂志上留意了一篇广告。", "explanation": "这里应该用〈刊登〉。“留意”不表示登出，在杂志上登广告要用“刊登”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前留意了过这个问题。", "corrected_sentence": "我以前留意过这个问题。", "error_description": "体标错误：表示经历的“过”后面不能再加“了”，应说“留意过”，不能说“留意了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机开车时一直留意了前方。", "corrected_sentence": "司机开车时一直留意着前方。", "error_description": "体标错误：“一直”表示动作持续，应用“着”，说“留意着前方”；“了”表示完成，与“一直”的持续语义冲突，不能说“留意了前方”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
