INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一天里的某一个时候，比如三点钟。", "primary_collocate": null, "pronunciation": "shí jiān diǎn", "ipa": "ʂɻ̩˧˥ tɕjɛn˥ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "我们定个时间点见面吧，比如下午三点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说个时间点，我准时到。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上八点是上班的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时间点路上车很多，很堵。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想在哪个时间点吃饭？", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点是他睡觉的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时间点商店已经关门了。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你到家的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这个时间点大家都在休息。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午五点是回家的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "时间点：一天里具体的钟点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间点", "is_correct": true, "explanation": "正确答案。“我们定个时间点见面”指约定一个钟点，与“比如下午三点”相合。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：见面要约定的是时间，不能约定脸色。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以约定的钟点，与见面无关。"}, {"text": "尺码", "is_correct": false, "explanation": "语义：尺码指衣物的大小，与约定见面的钟点无关。"}], "explanations": {"时间点": "正确答案。“我们定个时间点见面”指约定一个钟点，与“比如下午三点”相合。", "脸色": "搭配：见面要约定的是时间，不能约定脸色。", "颜色": "语义：颜色不是可以约定的钟点，与见面无关。", "尺码": "语义：尺码指衣物的大小，与约定见面的钟点无关。"}, "sentence_index": 0, "correct_answer": "时间点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的时间点很长。", "explanation": "这里应该用〈时长〉。时间点指一天中的钟点，不指持续多久。"}, {"text": "这个时间点很香，厨房里飘满了饭菜的味道。", "explanation": "这里应该用〈味道〉。时间点指钟点，没有气味，不能用“香”来形容。"}, {"text": "这只时间点很晚，他还没睡。", "explanation": "这里应该用〈个〉。时间点的量词是“个”，“只”用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间点", "is_correct": true, "explanation": "正确答案。“这个时间点商店已经关门了”指一天中的某个钟点，与“关门”相合。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印是踩过留下的痕迹，不能用来指商店关门的时刻。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指气味或滋味，与商店关门的时刻无关。"}, {"text": "大小", "is_correct": false, "explanation": "搭配：“这个大小商店”说不通，大小不能用来指时间。"}], "explanations": {"时间点": "正确答案。“这个时间点商店已经关门了”指一天中的某个钟点，与“关门”相合。", "脚印": "语义：脚印是踩过留下的痕迹，不能用来指商店关门的时刻。", "味道": "语义：味道指气味或滋味，与商店关门的时刻无关。", "大小": "搭配：“这个大小商店”说不通，大小不能用来指时间。"}, "sentence_index": 6, "correct_answer": "时间点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个时间点很重，我提不动。", "explanation": "这里应该用〈重量〉。时间点指钟点，没有轻重，不能用“很重”来形容。"}, {"text": "今天的时间点很高。", "explanation": "这里应该用〈温度〉。时间点指钟点，不能用“高”来形容。"}, {"text": "这个箱子的时间点很大。", "explanation": "这里应该用〈重量〉或〈体积〉。时间点指钟点，不能用来形容箱子的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们定一把时间点见面吧。", "corrected_sentence": "我们定一个时间点见面吧。", "error_description": "量词错误：时间点应配量词“个”，“把”多用于有柄的器具，应说“一个时间点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们定好了一条每天固定的时间点。", "corrected_sentence": "我们定好了一个每天固定的时间点。", "error_description": "量词错误：时间点应配量词“个”，“条”用于细长的东西，不能用于时间点，应说“一个每天固定的时间点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
