INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间轴上的某一特定时刻。", "primary_collocate": null, "pronunciation": "shí jiān diǎn", "ipa": "ʂɻ̩˧˥ tɕjɛn˥ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "这件事发生的时间点，没有人知道。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你写出事情发生的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个时间点上，公司做了大决定。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上有很多重要的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这个时间点起，一切都不同了。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们找出故事里的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他记得每个重要的时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时间点对我们的计划很关键。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的时间点和他说的不一样。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画图的时候，要先标好时间点。", "target_word": "时间点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "时间点：时间轴上的某个特定时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间点", "is_correct": true, "explanation": "正确答案。“这件事发生的时间点”指事件发生的时刻，与“没有人知道”相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖的钱数，与事件发生的时刻无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是时间，不能说“发生的颜色”。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“发生的”后不接重量，此处只能用指时刻的词语。"}], "explanations": {"时间点": "正确答案。“这件事发生的时间点”指事件发生的时刻，与“没有人知道”相合。", "价格": "语义：价格指买卖的钱数，与事件发生的时刻无关。", "颜色": "语义：颜色不是时间，不能说“发生的颜色”。", "重量": "搭配：“发生的”后不接重量，此处只能用指时刻的词语。"}, "sentence_index": 0, "correct_answer": "时间点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个时间点很高，我们都够不着。", "explanation": "这里应该用〈高度〉。时间点指时刻，不能用“高”来形容，更不能说够不着。"}, {"text": "这条时间点很重要，大家都记住了。", "explanation": "这里应该用〈个〉。时间点的量词是“个”，“条”用于细长的东西，不能用于时间点。"}, {"text": "这场会议的时间点用了三个小时。", "explanation": "这里应该用〈时长〉。时间点指某一时刻，不指持续了多久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间点", "is_correct": true, "explanation": "正确答案。“重要的时间点”指重要的时刻，与“记得”相合。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不是需要一一记住的重要时刻。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋是穿在脚上的鞋，与需要记住的时刻无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“记得每个重要的颜色”说不通，颜色不是需要记住的时点。"}], "explanations": {"时间点": "正确答案。“重要的时间点”指重要的时刻，与“记得”相合。", "饼干": "语义：饼干是食物，不是需要一一记住的重要时刻。", "拖鞋": "语义：拖鞋是穿在脚上的鞋，与需要记住的时刻无关。", "颜色": "搭配：“记得每个重要的颜色”说不通，颜色不是需要记住的时点。"}, "sentence_index": 6, "correct_answer": "时间点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "时间点飞逝，我们都长大了。", "explanation": "这里应该用〈时光〉。时间点是某一时刻，不能说“飞逝”。"}, {"text": "这张桌子的时间点很高，我够不着。", "explanation": "这里应该用〈高度〉。时间点指时刻，不能用“高”来形容桌子。"}, {"text": "学校的时间点离这里很远。", "explanation": "这里应该用〈地点〉。时间点指时刻，不能说离这里远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经定好了一次时间点。", "corrected_sentence": "我们已经定好了一个时间点。", "error_description": "量词错误：时间点应配量词“个”，“次”指动作的次数，不能用来修饰时间点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把那只重要的时间点记在本子上。", "corrected_sentence": "我们把那个重要的时间点记在本子上。", "error_description": "量词错误：时间点应配量词“个”，“只”用于动物或成对的东西，不能用于时间点，应说“那个重要的时间点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
