INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90799, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发水是下大雨后，河里的水涨得很高。", "primary_collocate": null, "pronunciation": "fā shuǐ", "ipa": "fa˥ ʂueɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨天下大雨，河里发水了。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方夏天常常发水。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说上游发水了，我们快走吧。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天发水，农田都被淹了。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了三天雨，小河发水了。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里发水，路不能走了。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是发水，村里人会搬到高处。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河一下雨就发水。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家在河边，每年雨季都怕发水。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发水以后，河边的路都看不见了。", "target_word": "发水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发水了", "label": "体标"}, {"form": "发过水", "label": "体标"}], "register": "口语", "sense_fingerprint": "大雨后河水猛涨，成了水灾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90799, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发水", "is_correct": true, "explanation": "正确答案：发水（fā shuǐ），指下大雨后河水涨得很高。"}, {"text": "放水", "is_correct": false, "explanation": "放水（fàng shuǐ）：fàng 与 fā 韵母不同（ang/a），声调也不同（第四声/第一声），意思是打开闸门放出水，不是河水自己大涨。"}, {"text": "风水", "is_correct": false, "explanation": "风水（fēng shuǐ）：fēng 与 fā 韵母不同（eng/a），意思是住宅选址的说法，不是河水涨。"}, {"text": "废水", "is_correct": false, "explanation": "废水（fèi shuǐ）：fèi 与 fā 韵母不同，声调也不同（第四声），意思是用过的污水。"}], "explanations": {"发水": "正确答案：发水（fā shuǐ），指下大雨后河水涨得很高。", "放水": "放水（fàng shuǐ）：fàng 与 fā 韵母不同（ang/a），声调也不同（第四声/第一声），意思是打开闸门放出水，不是河水自己大涨。", "风水": "风水（fēng shuǐ）：fēng 与 fā 韵母不同（eng/a），意思是住宅选址的说法，不是河水涨。", "废水": "废水（fèi shuǐ）：fèi 与 fā 韵母不同，声调也不同（第四声），意思是用过的污水。"}, "sentence_index": null, "correct_answer": "发水"}, "level_3": {"options": [{"text": "发水", "is_correct": true, "explanation": "正确：下大雨后河里涨水，与“昨天下大雨”相符。"}, {"text": "干", "is_correct": false, "explanation": "语义：“河里干了”说河水干涸，与前面的“下大雨”矛盾。"}, {"text": "断流", "is_correct": false, "explanation": "语义：断流指河水停止流动，与“下大雨”后河水猛涨矛盾。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”的主语是植物，不能用于河水。"}], "explanations": {"发水": "正确：下大雨后河里涨水，与“昨天下大雨”相符。", "干": "语义：“河里干了”说河水干涸，与前面的“下大雨”矛盾。", "断流": "语义：断流指河水停止流动，与“下大雨”后河水猛涨矛盾。", "开花": "搭配：“开花”的主语是植物，不能用于河水。"}, "sentence_index": 0, "correct_answer": "发水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "谣言在网上发水，很多人都信了。", "explanation": "这里应该用〈泛滥〉。发水只说河水等大涨成灾，不能用来说谣言这类抽象的东西。"}, {"text": "这块面包放久了发水了。", "explanation": "这里应该用〈发霉〉。发水指河水大涨或干货泡水涨大，面包长霉要说发霉。"}, {"text": "工人打开闸门发水，河水慢慢流走了。", "explanation": "这里应该用〈放水〉。发水是河水自己大涨成灾，不能由人主动做出；人打开闸门放出水要用放水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90799, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "发水", "is_correct": true, "explanation": "正确答案：发水（fā shuǐ），指下大雨后河水涨得很高。"}, {"text": "防水", "is_correct": false, "explanation": "防水（fáng shuǐ）：fáng 与 fā 韵母不同（ang/a），声调也不同（第二声/第一声），意思是防止水渗入。"}, {"text": "分水", "is_correct": false, "explanation": "分水（fēn shuǐ）：fēn 与 fā 韵母不同（en/a），意思是把水流分开，常见于“分水岭”。"}, {"text": "撒水", "is_correct": false, "explanation": "撒水（sā shuǐ）：sā 与 fā 声母不同（s/f），意思是把水洒出去。"}], "explanations": {"发水": "正确答案：发水（fā shuǐ），指下大雨后河水涨得很高。", "防水": "防水（fáng shuǐ）：fáng 与 fā 韵母不同（ang/a），声调也不同（第二声/第一声），意思是防止水渗入。", "分水": "分水（fēn shuǐ）：fēn 与 fā 韵母不同（en/a），意思是把水流分开，常见于“分水岭”。", "撒水": "撒水（sā shuǐ）：sā 与 fā 声母不同（s/f），意思是把水洒出去。"}, "sentence_index": null, "correct_answer": "发水"}, "level_3": {"options": [{"text": "发水", "is_correct": true, "explanation": "正确：说要是发水，村里人才会搬到高处，符合洪水的语境。"}, {"text": "退潮", "is_correct": false, "explanation": "语义：退潮是水往下落，村里人不需要搬到高处。"}, {"text": "干涸", "is_correct": false, "explanation": "语义：河水干涸不需要搬到高处，与句意矛盾。"}, {"text": "降温", "is_correct": false, "explanation": "搭配：“降温”说的是气温，不说水情，与“搬到高处”不搭。"}], "explanations": {"发水": "正确：说要是发水，村里人才会搬到高处，符合洪水的语境。", "退潮": "语义：退潮是水往下落，村里人不需要搬到高处。", "干涸": "语义：河水干涸不需要搬到高处，与句意矛盾。", "降温": "搭配：“降温”说的是气温，不说水情，与“搬到高处”不搭。"}, "sentence_index": 6, "correct_answer": "发水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大坝刚刚发水，城里一片慌乱。", "explanation": "这里应该用〈决堤〉。发水是河水大涨，大坝不能说发水；大坝被冲开要说决堤。"}, {"text": "物价发水了很多，大家都在省钱。", "explanation": "这里应该用〈涨〉。发水只用于河水或干货，不能用来说物价。"}, {"text": "他跑完步，后背都发水了。", "explanation": "这里应该用〈出汗〉。发水指河水大涨或干货泡水涨大，人出汗不说发水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前几天下暴雨，城外的河很发水了。", "corrected_sentence": "前几天下暴雨，城外的河也发水了。", "error_description": "错误：“很”修饰了动作动词“发水”。发水是动作，不能用“很”修饰；此处应用“也”，表示城外的河同样发生了水灾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前天下了大雨，山下的小溪发水了了。", "corrected_sentence": "前天下了大雨，山下的小溪发水了。", "error_description": "错误：“了”重复。“发水”后只用一个“了”，应说“发水了”，不说“发水了了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
