INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90801, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人心里最想玩、最想要的那一部分。", "primary_collocate": null, "pronunciation": "běn wǒ", "ipa": "pən˧˥ wɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小孩的本我总是想玩，不想写作业。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里的本我，想一直玩游戏。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到蛋糕，我的本我马上想吃。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本我只想要快乐，不想等。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的本我想买所有好看的东西。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很累，本我只想躺着睡觉。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本我说“我要玩”，理智说“先学习”。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的本我很强，想要什么就哭。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放假的时候，我的本我终于可以出来玩了。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的本我想休息，可是我得上班。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本我：内心只想玩、只想要的那部分自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肚子", "is_correct": false, "explanation": "搭配：“想玩”需要有意愿的主体，“肚子”不能想玩。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，没有想玩或不想写作业的欲望。"}, {"text": "本我", "is_correct": true, "explanation": "本我指人心里最想玩、最想要的那部分，与“小孩……总是想玩”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，没有想玩或不想写作业的愿望，句意不通。"}], "explanations": {"肚子": "搭配：“想玩”需要有意愿的主体，“肚子”不能想玩。", "书包": "语义：书包是物品，没有想玩或不想写作业的欲望。", "本我": "本我指人心里最想玩、最想要的那部分，与“小孩……总是想玩”相合。", "桌子": "语义：桌子是物品，没有想玩或不想写作业的愿望，句意不通。"}, "sentence_index": 0, "correct_answer": "本我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的本我提醒我不要乱花钱。", "explanation": "这里应该用〈超我〉。超我是人格中讲道德规则、提醒人克制的部分，本我只想要快乐，不会提醒人克制。"}, {"text": "他很有本我，一直在看书学习。", "explanation": "这里应该用〈自觉〉。“很有自觉”指主动学习、不用督促；本我指人心里最想玩、最想要的那部分，与主动学习相矛盾。"}, {"text": "面对诱惑，他总是用本我克制自己。", "explanation": "这里应该用〈理智〉。本我只追求满足欲望，不会用来克制冲动，克制要靠理智。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会说话，也没有欲望，句意不通。"}, {"text": "本我", "is_correct": true, "explanation": "本我指人心里最想要快乐的部分，能与“理智说”形成对照，正确。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能开口表达愿望，句意不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“说”的主语通常是能开口的人，“眼睛”不能说话。"}], "explanations": {"冰箱": "语义：冰箱不会说话，也没有欲望，句意不通。", "本我": "本我指人心里最想要快乐的部分，能与“理智说”形成对照，正确。", "天气": "语义：天气不能开口表达愿望，句意不通。", "眼睛": "搭配：“说”的主语通常是能开口的人，“眼睛”不能说话。"}, "sentence_index": 6, "correct_answer": "本我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的本我会背唐诗。", "explanation": "这里应该用〈记性〉。背唐诗靠的是记性；本我指人心里最想要的那部分，不负责记忆。"}, {"text": "人的本我会解数学题。", "explanation": "这里应该用〈智力〉。智力指认知和解题能力；本我指人心里最想要的那部分，不负责解题。"}, {"text": "他的本我开朗，从小就爱笑。", "explanation": "这里应该用〈天性〉。本我是欲望的部分，不能用来描述“开朗”这类性格特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟本我总想吃甜的，我只好把糖藏起来。", "corrected_sentence": "弟弟的本我总想吃甜的，我只好把糖藏起来。", "error_description": "漏字：“本我”前作定语需加“的”，应说“弟弟的本我”，不说“弟弟本我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我心里本我总想出去玩。", "corrected_sentence": "我心里的本我总想出去玩。", "error_description": "漏字：“本我”前作定语需加“的”，应说“我心里的本我”，不说“我心里本我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
