INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90802, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "精神分析学说中指人格里本能欲望的部分。", "primary_collocate": null, "pronunciation": "běn wǒ", "ipa": "pən˧˥ wɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "弗洛伊德说，人格有本我、自我和超我。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在心理学里，本我来自人的本能。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本我是人格中最原始的部分。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精神分析认为，本我只追求满足欲望。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本我不管社会规则，只讲快乐。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学书里说，婴儿的人格主要是本我。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文写的是本我和自我的关系。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本我里有人类最基本的本能欲望。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了什么是本我。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据这个学说，本我从出生就有。", "target_word": "本我", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "本我：精神分析学说中人格的本能欲望部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：“人格”是心理结构，“有汽车”指拥有实物，句意不通。"}, {"text": "本我", "is_correct": true, "explanation": "本我是人格中本能欲望的部分，与“自我、超我”并列，正确。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“人格”可以“有”特质，不说“人格有体重”。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不是人格的组成部分，与“自我、超我”并列不成立。"}], "explanations": {"汽车": "语义：“人格”是心理结构，“有汽车”指拥有实物，句意不通。", "本我": "本我是人格中本能欲望的部分，与“自我、超我”并列，正确。", "体重": "搭配：“人格”可以“有”特质，不说“人格有体重”。", "小猫": "语义：小猫不是人格的组成部分，与“自我、超我”并列不成立。"}, "sentence_index": 0, "correct_answer": "本我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本我让人遵守道德规则。", "explanation": "这里应该用〈超我〉。道德规则由超我负责，本我只追求满足欲望，不会让人遵守规则。"}, {"text": "本我在欲望和现实之间调节。", "explanation": "这里应该用〈自我〉。调节欲望与现实的是自我，本我只追求满足欲望，不负责调节。"}, {"text": "本我让人冷静地思考后果。", "explanation": "这里应该用〈理智〉。冷静思考后果是理智的作用，本我只追求满足欲望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哥们", "is_correct": false, "explanation": "语域：“论文”属书面学术语体，“哥们”是口语，不合语境。"}, {"text": "本我", "is_correct": true, "explanation": "本我是精神分析中人格的本能欲望部分，与“自我”构成学理关系，正确。"}, {"text": "巧克力", "is_correct": false, "explanation": "语义：论文不写巧克力与自我的关系，语义不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与自我之间无法构成学术上的关系，句意荒谬。"}], "explanations": {"哥们": "语域：“论文”属书面学术语体，“哥们”是口语，不合语境。", "本我": "本我是精神分析中人格的本能欲望部分，与“自我”构成学理关系，正确。", "巧克力": "语义：论文不写巧克力与自我的关系，语义不通。", "天气": "语义：天气与自我之间无法构成学术上的关系，句意荒谬。"}, "sentence_index": 6, "correct_answer": "本我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人的本我分为清醒和睡眠两种状态。", "explanation": "这里应该用〈意识〉。清醒和睡眠是意识的状态，本我指人格中的欲望部分，不能描述清醒与睡眠。"}, {"text": "我凭本我判断事情的对错。", "explanation": "这里应该用〈直觉〉。判断对错不是本我的作用，本我只追求满足欲望，不负责判断。"}, {"text": "人的本我能保存经验。", "explanation": "这里应该用〈记忆〉。保存经验是记忆的功能，本我指人格中的本能欲望，不负责保存经验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "心理学家认为，人本我由本能欲望组成。", "corrected_sentence": "心理学家认为，人的本我由本能欲望组成。", "error_description": "漏字：“人”修饰“本我”时需加“的”，应说“人的本我”，不说“人本我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "心理学认为，我们本我从出生就有。", "corrected_sentence": "心理学认为，我们的本我从出生就有。", "error_description": "漏字：“我们”修饰“本我”时需加“的”，应说“我们的本我”，不说“我们本我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
