INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皇上是古时候国家最大的人。", "primary_collocate": null, "pronunciation": "huáng shang", "ipa": "xwɑŋ˧˥ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "古时候，皇上住在很大的房子里。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上是国家最大的人。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，皇上有很多大臣。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上说的话，没有人敢不听。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的皇上很爱他的孩子。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位皇上让人修了一条长路。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上每天早上都要见大臣。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的皇上住在宫里。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们都很怕皇上。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上有一个很大的花园。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "古时候国家最大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇上", "is_correct": true, "explanation": "正确：“皇上”指古时候国家最大的人，能够住在很大的房子里。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能住在房子里。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能住在房子里。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“住在房子里”要求主语是人或动物，“树”不能与之搭配。"}], "explanations": {"皇上": "正确：“皇上”指古时候国家最大的人，能够住在很大的房子里。", "石头": "语义：石头没有生命，不能住在房子里。", "电脑": "语义：电脑是机器，不能住在房子里。", "树": "搭配：“住在房子里”要求主语是人或动物，“树”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "皇上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在部队里当皇上，指挥着一个团的士兵。", "explanation": "这里应该用〈将军〉。〈皇上〉指古代的皇帝，不用于军队中的高级军官。"}, {"text": "欧洲的皇上在议会里讲话。", "explanation": "这里应该用〈国王〉。〈皇上〉专指中国古代的皇帝，欧洲君主国的君主应称〈国王〉。"}, {"text": "现在的皇上是总统，我们每五年选一次。", "explanation": "这里应该用〈元首〉。〈皇上〉只指古代的最高统治者，不能用来称呼现代民选的国家元首。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇上", "is_correct": true, "explanation": "正确：“皇上”能够去见大臣，与“每天早上都要见大臣”相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能去见大臣，与“见大臣”的动作不相容。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物品，不能去见大臣。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“见”的主语须是人，“面包”不能与“每天早上都要见大臣”搭配。"}], "explanations": {"皇上": "正确：“皇上”能够去见大臣，与“每天早上都要见大臣”相符。", "小狗": "语义：小狗不能去见大臣，与“见大臣”的动作不相容。", "黑板": "语义：黑板是物品，不能去见大臣。", "面包": "搭配：“见”的主语须是人，“面包”不能与“每天早上都要见大臣”搭配。"}, "sentence_index": 6, "correct_answer": "皇上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "非洲部落的皇上很受尊敬。", "explanation": "这里应该用〈酋长〉。〈皇上〉专指中国古代的皇帝，部落首领不能称为皇上。"}, {"text": "我们公司的皇上每天很晚下班。", "explanation": "这里应该用〈老板〉。〈皇上〉指古代的皇帝，不用来称呼公司的负责人。"}, {"text": "这个村子的皇上带领大家修路。", "explanation": "这里应该用〈村长〉。〈皇上〉指古代国家的最高统治者，不能用于村里的领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古时候，一只皇上住在很大的宫殿里。", "corrected_sentence": "古时候，一位皇上住在很大的宫殿里。", "error_description": "量词“只”不能用于人，指皇上应用“位”。错误形式：“一只皇上”；正确形式：“一位皇上”；原因：“只”多用于动物或物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "皇上住很大的宫殿里。", "corrected_sentence": "皇上住在很大的宫殿里。", "error_description": "错误形式：“皇上住很大的宫殿里”；正确形式：“皇上住在很大的宫殿里”；原因：动词“住”后引出处所时须用介词“在”，此处缺少“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
