INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对在位皇帝的称呼。", "primary_collocate": null, "pronunciation": "huáng shang", "ipa": "xwɑŋ˧˥ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "大臣跪下说：“皇上，好消息！”", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太监对皇上说：“请您休息吧。”", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是皇上最喜欢的妃子。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧里，大家都叫他皇上。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上，外面有人想见您。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们对皇上说：“天下很平安。”", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上今天心情不太好。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员向皇上报告了这件事。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说皇上很聪明。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇上，请喝茶。", "target_word": "皇上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "对在位皇帝的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇上", "is_correct": true, "explanation": "正确：“皇上”是对在位皇帝的称呼，用在大臣的话里正合适。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯是物件，不能被称呼为“皇上”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能作为呼语。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：呼语要指向有生命的人，“河流”不能作为“好消息”的听话人。"}], "explanations": {"皇上": "正确：“皇上”是对在位皇帝的称呼，用在大臣的话里正合适。", "电灯": "语义：电灯是物件，不能被称呼为“皇上”。", "窗户": "语义：窗户是物件，不能作为呼语。", "河流": "搭配：呼语要指向有生命的人，“河流”不能作为“好消息”的听话人。"}, "sentence_index": 0, "correct_answer": "皇上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上课时，学生对老师说：“皇上，请您讲课。”", "explanation": "这里应该用〈老师〉。〈皇上〉只用于称呼在位的皇帝，不能用来称呼任课的老师。"}, {"text": "我在书店看见一位皇上，他在买书。", "explanation": "这里应该用〈顾客〉。〈皇上〉只用于称呼在位的皇帝，不能用来指书店里买书的人。"}, {"text": "我在商店对售货员说：“皇上，这个多少钱？”", "explanation": "这里应该用〈师傅〉。〈皇上〉只用于称呼在位的皇帝，不能用来称呼售货员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇上", "is_correct": true, "explanation": "正确：“皇上”有心情，与“今天心情不太好”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“心情”需要有感情的人作主语，“天气”不能说“心情不太好”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，没有心情。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视机没有心情，不能与“心情不太好”搭配。"}], "explanations": {"皇上": "正确：“皇上”有心情，与“今天心情不太好”相符。", "天气": "搭配：“心情”需要有感情的人作主语，“天气”不能说“心情不太好”。", "石头": "语义：石头没有感情，没有心情。", "电视": "语义：电视机没有心情，不能与“心情不太好”搭配。"}, "sentence_index": 6, "correct_answer": "皇上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员走过来说：“皇上，您要点什么？”", "explanation": "这里应该用〈先生〉。〈皇上〉只用于称呼在位的皇帝，不能用来称呼餐厅里的顾客。"}, {"text": "我对医生说：“皇上，我头很疼。”", "explanation": "这里应该用〈大夫〉。〈皇上〉只用于称呼在位的皇帝，不能用来称呼医生。"}, {"text": "我们小区的皇上每天早上在公园跳舞。", "explanation": "这里应该用〈大爷〉。〈皇上〉指在位的皇帝，不能用来称呼小区里的老人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宫女皇上送来了一杯茶。", "corrected_sentence": "宫女给皇上送来了一杯茶。", "error_description": "错误形式：“宫女皇上送来”；正确形式：“宫女给皇上送来”；原因：“送”的接受者要用介词“给”引出，漏掉“给”后两个名词连在一起，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大臣皇上禀报了这件事。", "corrected_sentence": "大臣向皇上禀报了这件事。", "error_description": "错误形式：“大臣皇上禀报”；正确形式：“大臣向皇上禀报”；原因：“禀报”的接受者要用介词“向”引出，漏掉“向”后两个名词连在一起，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
