INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90806, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "长度单位，一毫米等于千分之一米。", "primary_collocate": null, "pronunciation": "háo mǐ", "ipa": "xaʊ˧˥ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "一毫米等于千分之一米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十毫米就是一厘米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一米有一千毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尺子上最小的格子是一毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长度单位有米、厘米和毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用毫米来量这个小零件。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做零件时，差一毫米也不行。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把尺子可以量到零点五毫米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，毫米比厘米小。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字的单位是毫米，不是厘米。", "target_word": "毫米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方毫米", "label": "复合"}, {"form": "立方毫米", "label": "复合"}], "register": "中性", "sense_fingerprint": "毫米：长度单位，千分之一米", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de67917-7f36-4640-ba0a-be9730ecd119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毫米", "is_correct": true, "explanation": "正确：毫米是长度单位，一毫米等于千分之一米。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：公斤是重量单位，不能和长度换算成“千分之一米”。"}, {"text": "小时", "is_correct": false, "explanation": "语义：小时是时间单位，不能换算成长度。"}, {"text": "公顷", "is_correct": false, "explanation": "搭配：公顷是面积单位，和“千分之一米”这样的长度换算不搭配。"}], "explanations": {"毫米": "正确：毫米是长度单位，一毫米等于千分之一米。", "公斤": "语义：公斤是重量单位，不能和长度换算成“千分之一米”。", "小时": "语义：小时是时间单位，不能换算成长度。", "公顷": "搭配：公顷是面积单位，和“千分之一米”这样的长度换算不搭配。"}, "sentence_index": 0, "correct_answer": "毫米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥长一百毫米。", "explanation": "这里应该用〈米〉。毫米只用于很小的长度，桥的长度要用米。"}, {"text": "这瓶水重一毫米。", "explanation": "这里应该用〈克〉。毫米是长度单位，说重量要用克。"}, {"text": "我每天跑步十毫米。", "explanation": "这里应该用〈千米〉。毫米只用于很小的长度，跑步的距离要用千米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毫米", "is_correct": true, "explanation": "正确：毫米是长度单位，零件的尺寸差可以用毫米来说。"}, {"text": "亩", "is_correct": false, "explanation": "语义：亩是面积单位，不能用来说零件的长度差。"}, {"text": "公里", "is_correct": false, "explanation": "搭配：公里太长，不能用来说零件的尺寸差。"}, {"text": "平方米", "is_correct": false, "explanation": "语义：平方米是面积单位，不能用来说零件的长度差。"}], "explanations": {"毫米": "正确：毫米是长度单位，零件的尺寸差可以用毫米来说。", "亩": "语义：亩是面积单位，不能用来说零件的长度差。", "公里": "搭配：公里太长，不能用来说零件的尺寸差。", "平方米": "语义：平方米是面积单位，不能用来说零件的长度差。"}, "sentence_index": 6, "correct_answer": "毫米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班有四十毫米学生。", "explanation": "这里应该用〈名〉。毫米是长度单位，不能用来数人。"}, {"text": "我昨晚睡了五毫米。", "explanation": "这里应该用〈小时〉。毫米量长度，不能用来说睡眠的时间。"}, {"text": "这个城市的人口是十毫米。", "explanation": "这里应该用〈万人〉。毫米量长度，不能用来说人口数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两的毫米比一厘米小。", "corrected_sentence": "两毫米比一厘米小。", "error_description": "错误：数词“两”和“毫米”之间多加了“的”。正确：“两毫米比一厘米小”。数词后面直接接量词“毫米”，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "做零件时，差毫米也不行。", "corrected_sentence": "做零件时，差零点一毫米也不行。", "error_description": "错误：“毫米”前面漏掉了数量。正确：“差零点一毫米也不行”。量词前必须有数量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
