INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真性是真正的性情，真实的样子。", "primary_collocate": null, "pronunciation": "zhēn xìng", "ipa": "ʈʂən˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他在老朋友面前不用装，可以放心露出真性。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大自然里，孩子们都显出了自己的真性。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她表面很冷淡，其实真性很热情。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事让我们看到了老人的真性。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章要写出人物的真性，不能只写好话。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了，才把真性全都表现出来。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见到小狗时，她忘了装样子，露出了真性。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家想画出这位老人的真性。", "target_word": "真性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在困难面前，才能看清一个人的真性。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话直，从不隐藏自己的真性。", "target_word": "真性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真性情", "label": "复合"}], "register": "书面", "sense_fingerprint": "真正的性情，真实的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真性", "is_correct": true, "explanation": "真性指真正的性情、真实的样子，可以放心露出，正好填入这里。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：钞票是钱，露出钱不符合“放心”的语境。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“露出行李”不说，行李不是真实的性情或样子。"}, {"text": "考卷", "is_correct": false, "explanation": "搭配：“露出考卷”不说，考卷不是能放心露出的真实样子。"}], "explanations": {"真性": "真性指真正的性情、真实的样子，可以放心露出，正好填入这里。", "钞票": "语义：钞票是钱，露出钱不符合“放心”的语境。", "行李": "搭配：“露出行李”不说，行李不是真实的性情或样子。", "考卷": "搭配：“露出考卷”不说，考卷不是能放心露出的真实样子。"}, "sentence_index": 0, "correct_answer": "真性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事的真性很大。", "explanation": "这里应该用〈影响〉。真性指人的本性或真实的样子，不指事情的作用。"}, {"text": "这里离车站的真性很近。", "explanation": "这里应该用〈距离〉。真性不指空间的远近，不能说“近”。"}, {"text": "她的真性很好听。", "explanation": "这里应该用〈声音〉。真性指本性，不用来形容声音的好听与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真性", "is_correct": true, "explanation": "真性指真实的样子，见到小狗时露出来，正好填入这里。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是要付的钱的单子，不是能露出来的样子。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“露出钥匙”不说，钥匙不是真实的性情或样子。"}, {"text": "日记", "is_correct": false, "explanation": "语义：日记是记事的本子，与“忘了装样子”的语境不符。"}], "explanations": {"真性": "真性指真实的样子，见到小狗时露出来，正好填入这里。", "账单": "语义：账单是要付的钱的单子，不是能露出来的样子。", "钥匙": "搭配：“露出钥匙”不说，钥匙不是真实的性情或样子。", "日记": "语义：日记是记事的本子，与“忘了装样子”的语境不符。"}, "sentence_index": 6, "correct_answer": "真性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的真性很鲜。", "explanation": "这里应该用〈味道〉。真性指本性，不指食物的味道。"}, {"text": "这根绳子的真性够了。", "explanation": "这里应该用〈长度〉。真性指本性，不能说“够”。"}, {"text": "列车的真性很快。", "explanation": "这里应该用〈速度〉。真性指本性，不指运动的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在草地上玩，真性一下子显出去了。", "corrected_sentence": "孩子们在草地上玩，真性一下子显出来了。", "error_description": "补语错误：“显出去”不说，表示显露出来应说“显出来”，应把“去”改为“来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有露出了真性。", "corrected_sentence": "他从来没有露出过真性。", "error_description": "体标错误：“没有”否定经历时，动词后应用“过”而不用“了”，应把“了”改为“过”，即“从来没有露出过真性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
