INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90809, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在一段时间里流过的水或人，也指手机用掉的上网量。", "primary_collocate": null, "pronunciation": "liú liàng", "ipa": "ljoʊ˧˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这条河春天的流量很大。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我的手机流量用完了。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的流量不够了，不能看视频。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管的流量太小，水流得很慢。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河夏天的流量比冬天大。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家有网络吗？我想省点流量。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前我买了一些流量。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的流量还剩一半。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家连上网，就不用花流量了。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，河里的流量变大了。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人流量", "label": "复合"}, {"form": "流量卡", "label": "复合"}], "register": "中性", "sense_fingerprint": "一段时间里流过的水或手机用掉的上网量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90809, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流量", "is_correct": true, "explanation": "流量指一段时间里流过的水或人，也指手机用掉的上网量，与听到的读音一致。"}, {"text": "流浪", "is_correct": false, "explanation": "liàng 与 làng 的介音不同（有无 i），意思是漂泊、没有固定住处。"}, {"text": "留恋", "is_correct": false, "explanation": "liàn 与 liàng 的韵尾不同（n 与 ng），意思是舍不得离开。"}, {"text": "流连", "is_correct": false, "explanation": "lián 与 liàng 的韵尾不同（n 与 ng），声调也不同，意思是停留不愿离去。"}], "explanations": {"流量": "流量指一段时间里流过的水或人，也指手机用掉的上网量，与听到的读音一致。", "流浪": "liàng 与 làng 的介音不同（有无 i），意思是漂泊、没有固定住处。", "留恋": "liàn 与 liàng 的韵尾不同（n 与 ng），意思是舍不得离开。", "流连": "lián 与 liàng 的韵尾不同（n 与 ng），声调也不同，意思是停留不愿离去。"}, "sentence_index": null, "correct_answer": "流量"}, "level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "搭配：“很大”说体积、数量，温度要说高低，不能说“温度很大”。"}, {"text": "流量", "is_correct": true, "explanation": "流量指一段时间里流过的水量，春天河水的流量大，语义和搭配都合适。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是人的收入，河没有工资，句子说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来描述一条河。"}], "explanations": {"温度": "搭配：“很大”说体积、数量，温度要说高低，不能说“温度很大”。", "流量": "流量指一段时间里流过的水量，春天河水的流量大，语义和搭配都合适。", "工资": "语义：工资是人的收入，河没有工资，句子说不通。", "身材": "体貌：身材指人的体形，不能用来描述一条河。"}, "sentence_index": 0, "correct_answer": "流量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个水桶的流量很大。", "explanation": "这里应该用〈容量〉。流量指流动的水或人的量，水桶里的水并不流动，说能装多少要用容量。"}, {"text": "这条河的流量很快。", "explanation": "这里应该用〈流速〉。流量是流过的量，不说快慢；说水流快慢要用流速。"}, {"text": "今天这条河的流量涨到了三米。", "explanation": "这里应该用〈水位〉。水位是水面的高度，说涨到几米要用水位；流量指流过的量，不用米来量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90809, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "流量", "is_correct": true, "explanation": "流量指一段时间里流过的水或人，也指手机用掉的上网量，与听到的读音一致。"}, {"text": "流向", "is_correct": false, "explanation": "xiàng 与 liàng 的声母不同（x 与 l），意思是水流的方向。"}, {"text": "六两", "is_correct": false, "explanation": "liù liǎng 与 liú liàng 声母韵母相同，声调不同，意思是六两重。"}, {"text": "流浪", "is_correct": false, "explanation": "làng 与 liàng 的介音不同（有无 i），意思是漂泊、没有固定住处。"}], "explanations": {"流量": "流量指一段时间里流过的水或人，也指手机用掉的上网量，与听到的读音一致。", "流向": "xiàng 与 liàng 的声母不同（x 与 l），意思是水流的方向。", "六两": "liù liǎng 与 liú liàng 声母韵母相同，声调不同，意思是六两重。", "流浪": "làng 与 liàng 的介音不同（有无 i），意思是漂泊、没有固定住处。"}, "sentence_index": null, "correct_answer": "流量"}, "level_3": {"options": [{"text": "脾气", "is_correct": false, "explanation": "搭配：“买”的对象要能买到，脾气不能买，不能说“买了一些脾气”。"}, {"text": "流量", "is_correct": true, "explanation": "流量可以买，出国前买一些流量，用于上网，语义和搭配都合适。"}, {"text": "亲情", "is_correct": false, "explanation": "语义：亲情是人与人之间的感情，不是可以买到的东西。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“买”不能接体温，体温是身体的状况，不是可以买的东西。"}], "explanations": {"脾气": "搭配：“买”的对象要能买到，脾气不能买，不能说“买了一些脾气”。", "流量": "流量可以买，出国前买一些流量，用于上网，语义和搭配都合适。", "亲情": "语义：亲情是人与人之间的感情，不是可以买到的东西。", "体温": "搭配：“买”不能接体温，体温是身体的状况，不是可以买的东西。"}, "sentence_index": 6, "correct_answer": "流量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块草地的流量很大。", "explanation": "这里应该用〈面积〉。草地是静止的，说大小要用面积；流量只指流过的量。"}, {"text": "这箱苹果的流量很重。", "explanation": "这里应该用〈重量〉。苹果在箱子里并不流动，说轻重要用重量，流量不能用来说轻重。"}, {"text": "这场会议的流量很长。", "explanation": "这里应该用〈时长〉。会议持续多久要说时长，流量指流过的量，不能用来说长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的流量昨天用完。", "corrected_sentence": "我的流量昨天用完了。", "error_description": "漏了“了”。“昨天”说明这件事已经发生，“用完”后要用“了”表示完成；应说“我的流量昨天用完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月我买了一只流量。", "corrected_sentence": "这个月我买了一些流量。", "error_description": "数量词错误：“流量”是不可数的，前面不能用个体量词“一只”，应说“买了一些流量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
