INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定时间内流过的量；也指网络数据的传输量。", "primary_collocate": null, "pronunciation": "liú liàng", "ipa": "ljoʊ˧˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个水龙头的流量很小。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水的流量每个月都不一样。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看视频很费流量。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，小河的流量变大了。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站的流量突然多了很多。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的网站每天的流量很高。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡每个月有一些免费流量。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天都要记录河水的流量。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下载大文件要用很多流量。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个管子的流量不够，需要换大的。", "target_word": "流量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人流量", "label": "复合"}, {"form": "流量卡", "label": "复合"}], "register": "中性", "sense_fingerprint": "一定时间内流过的量或网络数据传输量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流量", "is_correct": true, "explanation": "流量指一定时间内流过的量，也指网络数据的传输量，与听到的读音一致。"}, {"text": "流浪", "is_correct": false, "explanation": "liàng 与 làng 的介音不同（有无 i），意思是漂泊、没有固定住处。"}, {"text": "留恋", "is_correct": false, "explanation": "liàn 与 liàng 的韵尾不同（n 与 ng），意思是舍不得离开。"}, {"text": "流连", "is_correct": false, "explanation": "lián 与 liàng 的韵尾不同（n 与 ng），声调也不同，意思是停留不愿离去。"}], "explanations": {"流量": "流量指一定时间内流过的量，也指网络数据的传输量，与听到的读音一致。", "流浪": "liàng 与 làng 的介音不同（有无 i），意思是漂泊、没有固定住处。", "留恋": "liàn 与 liàng 的韵尾不同（n 与 ng），意思是舍不得离开。", "流连": "lián 与 liàng 的韵尾不同（n 与 ng），声调也不同，意思是停留不愿离去。"}, "sentence_index": null, "correct_answer": "流量"}, "level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：工资是人的收入，水龙头没有工资，句子说不通。"}, {"text": "流量", "is_correct": true, "explanation": "流量指一定时间内流过的量，水龙头的流量小，与“很小”搭配。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“很小”说体积、数量，温度要说高低，不能说“温度很小”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体特征，不能用来描述水龙头。"}], "explanations": {"工资": "语义：工资是人的收入，水龙头没有工资，句子说不通。", "流量": "流量指一定时间内流过的量，水龙头的流量小，与“很小”搭配。", "温度": "搭配：“很小”说体积、数量，温度要说高低，不能说“温度很小”。", "身高": "体貌：身高是人的身体特征，不能用来描述水龙头。"}, "sentence_index": 0, "correct_answer": "流量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段急流的流量很快。", "explanation": "这里应该用〈流速〉。流量指流过的量，说快慢要用流速，急流的快慢不能说流量。"}, {"text": "这片湖的流量很深。", "explanation": "这里应该用〈水深〉。湖的深浅要说水深，流量指流过的量，不能用来说深浅。"}, {"text": "这条小河的流量涨了两米。", "explanation": "这里应该用〈水位〉。水位是水面的高度，说涨了几米要用水位；流量指流过的量，不用米来量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90810, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "流量", "is_correct": true, "explanation": "流量指一定时间内流过的量，也指网络数据的传输量，与听到的读音一致。"}, {"text": "流向", "is_correct": false, "explanation": "xiàng 与 liàng 的声母不同（x 与 l），意思是水流的方向。"}, {"text": "六两", "is_correct": false, "explanation": "liù liǎng 与 liú liàng 声母韵母相同，声调不同，意思是六两重。"}, {"text": "流浪", "is_correct": false, "explanation": "làng 与 liàng 的介音不同（有无 i），意思是漂泊、没有固定住处。"}], "explanations": {"流量": "流量指一定时间内流过的量，也指网络数据的传输量，与听到的读音一致。", "流向": "xiàng 与 liàng 的声母不同（x 与 l），意思是水流的方向。", "六两": "liù liǎng 与 liú liàng 声母韵母相同，声调不同，意思是六两重。", "流浪": "làng 与 liàng 的介音不同（有无 i），意思是漂泊、没有固定住处。"}, "sentence_index": null, "correct_answer": "流量"}, "level_3": {"options": [{"text": "脾气", "is_correct": false, "explanation": "搭配：“免费”不能修饰脾气，脾气不能免费获得。"}, {"text": "流量", "is_correct": true, "explanation": "流量指一定时间内流过的量，也指网络数据的传输量，免费流量与句意相合。"}, {"text": "亲情", "is_correct": false, "explanation": "语义：亲情是感情，不是卡能提供的东西。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来描述一张卡。"}], "explanations": {"脾气": "搭配：“免费”不能修饰脾气，脾气不能免费获得。", "流量": "流量指一定时间内流过的量，也指网络数据的传输量，免费流量与句意相合。", "亲情": "语义：亲情是感情，不是卡能提供的东西。", "身材": "体貌：身材指人的体形，不能用来描述一张卡。"}, "sentence_index": 6, "correct_answer": "流量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个木箱的流量很大。", "explanation": "这里应该用〈体积〉。木箱不流动，说大小要用体积；流量只指流过的量。"}, {"text": "这箱西瓜的流量很重。", "explanation": "这里应该用〈重量〉。西瓜不流动，说轻重要用重量，流量不能用来说轻重。"}, {"text": "这杯水的流量很烫。", "explanation": "这里应该用〈温度〉。水的冷热要说温度，流量指流过的量，不能用来说烫不烫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网站的流量昨天突然多很多。", "corrected_sentence": "网站的流量昨天突然多了很多。", "error_description": "漏了“了”。“昨天”说明这件事已经发生，“多”后要用“了”表示变化完成；应说“网站的流量昨天突然多了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每个月都要买一只流量。", "corrected_sentence": "我每个月都要买一些流量。", "error_description": "数量词错误：“流量”是不可数的，前面不能用个体量词“一只”，应说“买一些流量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
