INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90811, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "碗是吃饭、喝汤时用的圆形餐具。", "primary_collocate": null, "pronunciation": "wǎn", "ipa": "wan˨˩˦", "syllable_count": 1, "sentences": [{"text": "我家的饭桌上有三个碗。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我一个小碗，让我盛汤。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，我马上洗碗。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个碗太烫了，你拿的时候小心。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用大碗喝了一碗热汤。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一个白色的碗。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不小心把碗掉在地上了。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个新碗吃面条。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碗里有米饭，盘子里有青菜。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给客人拿来了碗和筷子。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "饭碗", "label": "复合"}, {"form": "碗筷", "label": "复合"}], "register": "中性", "sense_fingerprint": "碗：吃饭、喝汤用的圆形餐具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90811, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：碗，wǎn，吃饭、喝汤用的圆形餐具。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wǎn（第三声）声调不同，意思是数字“一万”。"}, {"text": "完", "is_correct": false, "explanation": "wán（第二声）与 wǎn（第三声）声调不同，意思是完成、结束。"}, {"text": "网", "is_correct": false, "explanation": "韵母不同（-ǎng 与 -ǎn），wǎng 意思是网子。"}, {"text": "满", "is_correct": false, "explanation": "声母不同（m 与 w），mǎn 意思是充满、满足。"}], "explanations": {"碗": "正确：碗，wǎn，吃饭、喝汤用的圆形餐具。", "万": "wàn（第四声）与 wǎn（第三声）声调不同，意思是数字“一万”。", "完": "wán（第二声）与 wǎn（第三声）声调不同，意思是完成、结束。", "网": "韵母不同（-ǎng 与 -ǎn），wǎng 意思是网子。", "满": "声母不同（m 与 w），mǎn 意思是充满、满足。"}, "sentence_index": null, "correct_answer": "碗"}, "level_3": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：与“饭桌上”的语境相合，是饭桌上常见的餐具。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：饭桌上不会摆放黑板，与语境不合。"}, {"text": "电视", "is_correct": false, "explanation": "语义：饭桌上不会摆放电视，与语境不合。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会放在饭桌上，与语境不合。"}], "explanations": {"碗": "正确：与“饭桌上”的语境相合，是饭桌上常见的餐具。", "黑板": "语义：饭桌上不会摆放黑板，与语境不合。", "电视": "语义：饭桌上不会摆放电视，与语境不合。", "汽车": "语义：汽车不会放在饭桌上，与语境不合。"}, "sentence_index": 0, "correct_answer": "碗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用碗洗衣服，洗得很干净。", "explanation": "这里应该用〈盆〉。碗太小，不能用来洗衣服，应该用〈盆〉。"}, {"text": "我把鞋子放进碗里，放在门口。", "explanation": "这里应该用〈鞋盒〉。碗是盛饭菜、汤水的器皿，不能用来装鞋，应该用〈鞋盒〉。"}, {"text": "他用碗做了一个书架。", "explanation": "这里应该用〈木板〉。碗太小，不能拿来做书架，应该用〈木板〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90811, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：碗，wǎn，吃饭、喝汤用的圆形餐具。"}, {"text": "玩", "is_correct": false, "explanation": "wán（第二声）与 wǎn（第三声）声调不同，意思是玩耍。"}, {"text": "腕", "is_correct": false, "explanation": "wàn（第四声）与 wǎn（第三声）声调不同，意思是手腕。"}, {"text": "懒", "is_correct": false, "explanation": "声母不同（l 与 w），lǎn 意思是懒惰。"}, {"text": "喊", "is_correct": false, "explanation": "声母不同（h 与 w），hǎn 意思是大声叫。"}], "explanations": {"碗": "正确：碗，wǎn，吃饭、喝汤用的圆形餐具。", "玩": "wán（第二声）与 wǎn（第三声）声调不同，意思是玩耍。", "腕": "wàn（第四声）与 wǎn（第三声）声调不同，意思是手腕。", "懒": "声母不同（l 与 w），lǎn 意思是懒惰。", "喊": "声母不同（h 与 w），hǎn 意思是大声叫。"}, "sentence_index": null, "correct_answer": "碗"}, "level_3": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：与“不小心”和“掉在地上”相合，指一种易碎的餐具。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“掉”的对象须是具体的东西，不能说把空气掉在地上。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不会掉到地上，与“掉在地上了”的语境不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会掉到地上，与“掉在地上了”的语境不合。"}], "explanations": {"碗": "正确：与“不小心”和“掉在地上”相合，指一种易碎的餐具。", "空气": "搭配：“掉”的对象须是具体的东西，不能说把空气掉在地上。", "星星": "语义：星星不会掉到地上，与“掉在地上了”的语境不合。", "月亮": "语义：月亮不会掉到地上，与“掉在地上了”的语境不合。"}, "sentence_index": 6, "correct_answer": "碗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在碗里洗了个澡，很舒服。", "explanation": "这里应该用〈浴缸〉。碗太小，人不能坐在里面洗澡，应该用〈浴缸〉。"}, {"text": "他把整个西瓜装进碗里，抱着走了。", "explanation": "这里应该用〈篮子〉。碗太小，装不下整个西瓜，应该用〈篮子〉。"}, {"text": "他戴着碗出门，像一顶帽子。", "explanation": "这里应该用〈头盔〉。碗是餐具，不能当作头饰戴在头上，应该用〈头盔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的柜子里有五条碗。", "corrected_sentence": "厨房的柜子里有五个碗。", "error_description": "错误形式：“五条碗”，“条”用于细长的东西。正确形式：“五个碗”，碗用“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一个碗大。", "corrected_sentence": "我买了一个大碗。", "error_description": "错误形式：“一个碗大”，形容词“大”放在名词后。正确形式：“一个大碗”，形容词作定语应放在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
