INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盛饭菜或汤水的圆形器皿，口大底小。", "primary_collocate": null, "pronunciation": "wǎn", "ipa": "wan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个碗口大底小，盛汤很方便。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用碗盛了满满一碗饭。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把碗里的菜吃完。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的碗都洗干净了。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他端着一碗热面走过来。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只碗是圆的，上面有蓝花。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把汤倒进碗里。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上摆着四个碗，每个碗里都有菜。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碗太小，装不下这么多饭。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸喜欢用大碗喝茶。", "target_word": "碗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "饭碗", "label": "复合"}, {"form": "碗筷", "label": "复合"}], "register": "中性", "sense_fingerprint": "碗：盛饭菜汤水、口大底小的圆形器皿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：碗，wǎn，盛饭菜汤水、口大底小的圆形器皿。"}, {"text": "腕", "is_correct": false, "explanation": "wàn（第四声）与 wǎn（第三声）声调不同，意思是手腕。"}, {"text": "懒", "is_correct": false, "explanation": "声母不同（l 与 w），lǎn 意思是懒惰。"}, {"text": "网", "is_correct": false, "explanation": "韵母不同（-ǎng 与 -ǎn），wǎng 意思是网子。"}], "explanations": {"碗": "正确：碗，wǎn，盛饭菜汤水、口大底小的圆形器皿。", "腕": "wàn（第四声）与 wǎn（第三声）声调不同，意思是手腕。", "懒": "声母不同（l 与 w），lǎn 意思是懒惰。", "网": "韵母不同（-ǎng 与 -ǎn），wǎng 意思是网子。"}, "sentence_index": null, "correct_answer": "碗"}, "level_3": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：口大底小的器皿，与“盛汤很方便”的语境相合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是盛汤的器皿，与“盛汤很方便”的语境不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不用来盛汤，与“盛汤很方便”的语境不合。"}, {"text": "句子", "is_correct": false, "explanation": "搭配：“句子”没有“口”和“底”，“口大底小”只用于器皿。"}], "explanations": {"碗": "正确：口大底小的器皿，与“盛汤很方便”的语境相合。", "书包": "语义：书包不是盛汤的器皿，与“盛汤很方便”的语境不合。", "窗户": "语义：窗户不用来盛汤，与“盛汤很方便”的语境不合。", "句子": "搭配：“句子”没有“口”和“底”，“口大底小”只用于器皿。"}, "sentence_index": 0, "correct_answer": "碗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提着碗去井边打水。", "explanation": "这里应该用〈桶〉。碗太小，装不了多少水，不能用来打水，应该用〈桶〉。"}, {"text": "我把整件大衣泡在碗里。", "explanation": "这里应该用〈盆〉。碗太小，装不下整件大衣，应该用〈盆〉。"}, {"text": "妈妈在碗里炒菜，油烟很大。", "explanation": "这里应该用〈锅〉。碗太浅，不能用来炒菜，应该用〈锅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90812, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：碗，wǎn，盛饭菜汤水、口大底小的圆形器皿。"}, {"text": "玩", "is_correct": false, "explanation": "wán（第二声）与 wǎn（第三声）声调不同，意思是玩耍。"}, {"text": "喊", "is_correct": false, "explanation": "声母不同（h 与 w），hǎn 意思是大声叫。"}, {"text": "满", "is_correct": false, "explanation": "声母不同（m 与 w），mǎn 意思是充满、满足。"}], "explanations": {"碗": "正确：碗，wǎn，盛饭菜汤水、口大底小的圆形器皿。", "玩": "wán（第二声）与 wǎn（第三声）声调不同，意思是玩耍。", "喊": "声母不同（h 与 w），hǎn 意思是大声叫。", "满": "声母不同（m 与 w），mǎn 意思是充满、满足。"}, "sentence_index": null, "correct_answer": "碗"}, "level_3": {"options": [{"text": "碗", "is_correct": true, "explanation": "正确：盛汤的器皿，与“老人把汤倒进”的动作相合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“倒进”的对象须是能盛东西的器皿，不能说倒进空气里。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：把汤倒进鞋子里不合常理，与语境不符。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：汤不会倒进树叶里，与“老人把汤倒进”的语境不合。"}], "explanations": {"碗": "正确：盛汤的器皿，与“老人把汤倒进”的动作相合。", "空气": "搭配：“倒进”的对象须是能盛东西的器皿，不能说倒进空气里。", "鞋子": "语义：把汤倒进鞋子里不合常理，与语境不符。", "树叶": "语义：汤不会倒进树叶里，与“老人把汤倒进”的语境不合。"}, "sentence_index": 6, "correct_answer": "碗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在碗上拍照，动作很可爱。", "explanation": "这里应该用〈凳子〉。碗是盛饭菜的器皿，不能用来站，应该用〈凳子〉。"}, {"text": "爸爸睡觉时用碗垫着脑袋，睡得很香。", "explanation": "这里应该用〈枕头〉。碗是餐具，又硬又小，不能拿来垫脑袋，应该用〈枕头〉。"}, {"text": "妈妈在碗里跳舞，动作很优美。", "explanation": "这里应该用〈舞台〉。碗太小，人无法在里面跳舞，应该用〈舞台〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在厨房里洗了三张碗。", "corrected_sentence": "妈妈在厨房里洗了三个碗。", "error_description": "错误形式：“三张碗”，“张”用于扁平的东西。正确形式：“三个碗”，碗用“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶给我拿来了两只碗们。", "corrected_sentence": "奶奶给我拿来了两只碗。", "error_description": "错误形式：“碗们”，“们”只用于指人的名词，不能加在“碗”后面。正确形式：“两只碗”，碗的数量由量词表示。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
