INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90813, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "礼物是送给别人，让他开心的东西。", "primary_collocate": null, "pronunciation": "lǐ wù", "ipa": "li˨˩ wu˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈给我买了一个新礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟打开礼物，笑得很开心。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个礼物是给你的，你喜欢吗？", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给女朋友买一个礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都喜欢圣诞节的礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你猜猜我给你带了什么礼物？", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一个红色的礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把礼物藏在了门后面。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到礼物，小朋友马上笑了。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想送爸爸一个特别的礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "圣诞礼物", "label": "复合"}, {"form": "禮物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "送给别人、让人开心的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90813, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "搭配：“买”可以买实物，不能说“买了一个新感冒”。"}, {"text": "礼物", "is_correct": true, "explanation": "礼物是可以买来送人的东西，与“妈妈给我买了一个新”相合，正确。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不可数，也不能用“买”获得，不能说“一个新空气”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能买，“买了一个新天气”荒谬。"}], "explanations": {"感冒": "搭配：“买”可以买实物，不能说“买了一个新感冒”。", "礼物": "礼物是可以买来送人的东西，与“妈妈给我买了一个新”相合，正确。", "空气": "语义：空气不可数，也不能用“买”获得，不能说“一个新空气”。", "天气": "语义：天气不能买，“买了一个新天气”荒谬。"}, "sentence_index": 0, "correct_answer": "礼物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很讲礼物，从不大声说话。", "explanation": "这里应该用〈礼节〉。“讲礼节”指遵守待人接物的规矩，礼物是赠送的东西，不能用“讲”来说。"}, {"text": "我们在礼物里唱歌。", "explanation": "这里应该用〈礼堂〉。礼物是赠送的东西，不能作表演场所；“在……唱歌”的场所应是礼堂。"}, {"text": "这个礼物我很忙。", "explanation": "这里应该用〈礼拜〉。“这个礼拜”指本周，礼物是送人的东西，不能表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海浪", "is_correct": false, "explanation": "语义：海浪不能放在桌子上当作红色的物品，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“红色的”修饰有颜色的具体事物，不说“红色的心情”。"}, {"text": "礼物", "is_correct": true, "explanation": "礼物是可以放在桌子上的具体物品，有颜色，正确。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能放在桌子上，“桌子上有一个红色的河流”不通。"}], "explanations": {"海浪": "语义：海浪不能放在桌子上当作红色的物品，句意不通。", "心情": "搭配：“红色的”修饰有颜色的具体事物，不说“红色的心情”。", "礼物": "礼物是可以放在桌子上的具体物品，有颜色，正确。", "河流": "语义：河流不能放在桌子上，“桌子上有一个红色的河流”不通。"}, "sentence_index": 6, "correct_answer": "礼物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸的礼物很开朗，爱说笑。", "explanation": "这里应该用〈天性〉。天性指人的性格特点，“开朗”属于人的天性；礼物是送人的东西，不能形容开朗。"}, {"text": "礼物是人际交往的规范。", "explanation": "这里应该用〈礼仪〉。礼仪是人际交往的规范，礼物是送给别人的东西，不能作规范。"}, {"text": "他穿着礼物参加婚礼。", "explanation": "这里应该用〈礼服〉。礼服是穿的衣服，礼物是送人的东西，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天收到了一位礼物，很开心。", "corrected_sentence": "我昨天收到了一份礼物，很开心。", "error_description": "量词错误：“位”用于人，礼物应用“份”或“件”计量，不能说“一位礼物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹拆开了姐姐礼物，笑得很开心。", "corrected_sentence": "妹妹拆开了姐姐的礼物，笑得很开心。", "error_description": "漏字：表示所属的“姐姐”修饰“礼物”时需加“的”，应说“姐姐的礼物”，不说“姐姐礼物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
