INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为表示心意、祝贺或感谢而赠送给别人的物品。", "primary_collocate": null, "pronunciation": "lǐ wù", "ipa": "li˨˩ wu˥˩", "syllable_count": 2, "sentences": [{"text": "这是我送给你的生日礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你送我这么好的礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为结婚纪念日准备了一份礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了感谢老师，我们买了一件礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友结婚，我送了他一份礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼物是公司送给客人的。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收到礼物，高兴地说谢谢。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我给爷爷买了礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感谢你帮忙，这是一点小礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，同学们互相送礼物。", "target_word": "礼物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "件", "label": "量词"}, {"form": "生日礼物", "label": "复合"}, {"form": "禮物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为表达心意、祝贺或感谢而赠送的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "搭配：“送”的对象是可以送给别人的物品，“体重”不能送。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“送给你”，句意不通。"}, {"text": "礼物", "is_correct": true, "explanation": "礼物是为表达心意而赠送的物品，与“送给你的生日”相合，正确。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“送给你的生日垃圾”语义荒谬，不符合祝福的语境。"}], "explanations": {"体重": "搭配：“送”的对象是可以送给别人的物品，“体重”不能送。", "天气": "语义：天气不能被“送给你”，句意不通。", "礼物": "礼物是为表达心意而赠送的物品，与“送给你的生日”相合，正确。", "垃圾": "语义：“送给你的生日垃圾”语义荒谬，不符合祝福的语境。"}, "sentence_index": 0, "correct_answer": "礼物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈教我要讲礼物。", "explanation": "这里应该用〈礼节〉。“讲礼节”指遵守待人接物的规矩，礼物是赠送的东西，不能用“讲”来说。"}, {"text": "他对长辈很有礼物。", "explanation": "这里应该用〈礼貌〉。礼物是送给别人的东西，不能用来形容人的态度。"}, {"text": "我们在礼物开会。", "explanation": "这里应该用〈礼堂〉。礼物不是场所，开会要在礼堂等地方进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“收到作业”不会让人“高兴地说谢谢”，与语境矛盾。"}, {"text": "礼物", "is_correct": true, "explanation": "礼物是别人送来的东西，收到后高兴地道谢，正确。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“收到”接可接收的物品或消息，“感冒”不能被收到。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒不是人会高兴收到的东西，与“高兴地说谢谢”冲突。"}], "explanations": {"作业": "语义：“收到作业”不会让人“高兴地说谢谢”，与语境矛盾。", "礼物": "礼物是别人送来的东西，收到后高兴地道谢，正确。", "感冒": "搭配：“收到”接可接收的物品或消息，“感冒”不能被收到。", "病毒": "语义：病毒不是人会高兴收到的东西，与“高兴地说谢谢”冲突。"}, "sentence_index": 6, "correct_answer": "礼物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的礼物很稳重。", "explanation": "这里应该用〈性格〉。稳重是人的性格特点，礼物是送给别人的东西，不能用来形容它稳重。"}, {"text": "礼物是人际交往的规范。", "explanation": "这里应该用〈礼仪〉。礼仪是人际交往的规范，礼物是送给别人的东西，不能作规范。"}, {"text": "今天是礼物。", "explanation": "这里应该用〈礼拜〉。礼拜指星期，礼物是送人的东西，不能表示日期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们为妈妈准备了一把礼物，希望她喜欢。", "corrected_sentence": "我们为妈妈准备了一份礼物，希望她喜欢。", "error_description": "量词错误：礼物应用“份”或“件”计量，“把”用于有柄的物品，不能说“一把礼物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他收到了一份来自朋友礼物。", "corrected_sentence": "他收到了一份来自朋友的礼物。", "error_description": "漏字：“朋友”修饰“礼物”时需加“的”，应说“朋友的礼物”，不说“朋友礼物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
