INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90815, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让很多人受伤或没有家的很坏的事。", "primary_collocate": null, "pronunciation": "zāi nàn", "ipa": "tsaɪ̯˥ nan˥˩", "syllable_count": 2, "sentences": [{"text": "大地震是一场可怕的灾难，很多人没有了家。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山爆发了，当地的人遇到了大灾难。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到电视上的灾难，我心里很难过。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾难发生后，很多人受了伤。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在灾难里没有了家，大家都想帮他们。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场灾难让上千人受了伤。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾难来得很快，人们来不及跑。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把钱和衣服送给灾难中的人。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海啸是一场很大的灾难。", "target_word": "灾难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我希望世界上不再有这样的灾难。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "灾难片", "label": "复合"}, {"form": "災難", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让很多人受伤或失去家园的非常坏的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灾难", "is_correct": true, "explanation": "灾难：大规模的严重祸害，与“大地震”“可怕的”“没有了家”的语境相符。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”是欢庆的日子，与“很多人没有了家”的描述相冲突。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：“婚礼”是喜事，与“可怕的”和“没有了家”的描述相矛盾。"}, {"text": "演出", "is_correct": false, "explanation": "搭配：“可怕的”一般修饰灾害、事故、疾病，不修饰演出。"}], "explanations": {"灾难": "灾难：大规模的严重祸害，与“大地震”“可怕的”“没有了家”的语境相符。", "节日": "语义：“节日”是欢庆的日子，与“很多人没有了家”的描述相冲突。", "婚礼": "语义：“婚礼”是喜事，与“可怕的”和“没有了家”的描述相矛盾。", "演出": "搭配：“可怕的”一般修饰灾害、事故、疾病，不修饰演出。"}, "sentence_index": 0, "correct_answer": "灾难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个新灾难很有创意，大家都觉得很好。", "explanation": "这里应该用〈方案〉。方案指计划，可以有创意；灾难指严重的祸害，不能用来形容有创意的计划，意义相反。"}, {"text": "这次运动会的灾难很成功，同学们都很满意。", "explanation": "这里应该用〈安排〉。安排可以很成功；灾难指严重的祸害，不能用来形容成功的活动，意义相反。"}, {"text": "那次聚会很热闹，大家吃得很开心，是一场灾难。", "explanation": "这里应该用〈愉快的聚会〉，说“是一场愉快的聚会”。灾难指严重的祸害，不能用来形容热闹、开心的聚会，感情色彩正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灾难", "is_correct": true, "explanation": "灾难：突然降临的严重祸害，与“来得很快”“来不及跑”的语境相符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是值得庆祝的日子，与“人们来不及跑”的紧迫语境相冲突。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送给人的东西，不会让人“来不及跑”。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“笑声”一般说“响起”“传来”，不用“来得很快”来描述，也不会让人来不及跑。"}], "explanations": {"灾难": "灾难：突然降临的严重祸害，与“来得很快”“来不及跑”的语境相符。", "生日": "语义：生日是值得庆祝的日子，与“人们来不及跑”的紧迫语境相冲突。", "礼物": "语义：礼物是送给人的东西，不会让人“来不及跑”。", "笑声": "搭配：“笑声”一般说“响起”“传来”，不用“来得很快”来描述，也不会让人来不及跑。"}, "sentence_index": 6, "correct_answer": "灾难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个灾难很好听，我听了很多遍。", "explanation": "这里应该用〈音乐〉。音乐可以好听；灾难指严重的祸害，不能用来形容好听的声音，意义相反。"}, {"text": "我们的球队赢得了冠军，这真是一场灾难。", "explanation": "这里应该用〈胜利〉。灾难指严重的祸害，不能用来形容球队赢得冠军这样的好事；胜利表示取得好结果，感情色彩正好相反。"}, {"text": "我每天早上都吃丰富的灾难。", "explanation": "这里应该用〈早餐〉。早餐是食物，可以吃，也可以丰富；灾难指严重的祸害，不能吃，意思完全不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那次洪水灾难了很多人。", "corrected_sentence": "那次洪水伤害了很多人。", "error_description": "错误：“灾难”是名词，不能当动词用，“灾难了”不成立。正确说法是“伤害了很多人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那颗灾难让一个小镇变得冷清。", "corrected_sentence": "那场灾难让一个小镇变得冷清。", "error_description": "错误：“灾难”的量词应用“场”，不能用“颗”（“颗”多用于小而圆的东西）。正确说法是“那场灾难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
