INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然或人为造成的严重祸害。", "primary_collocate": null, "pronunciation": "zāi nàn", "ipa": "tsaɪ̯˥ nan˥˩", "syllable_count": 2, "sentences": [{"text": "地震给这个城市带来了很大的灾难。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争是人类最大的灾难之一。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染可能会给地球带来灾难。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场灾难过去以后，大家重新盖起了房子。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水给山下的农民带来了灾难。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故差点儿变成一场大灾难。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那里发生了灾难，人们都很担心。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们用爱心帮助灾难中的家庭。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这场灾难中失去了朋友。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次小小的错误，可能带来大灾难。", "target_word": "灾难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "灾难片", "label": "复合"}, {"form": "災難", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自然或人为原因造成的严重祸害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灾难", "is_correct": true, "explanation": "灾难：严重的自然或人为祸害，与“地震”和“很大的”搭配，符合句意。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：地震是灾害，不会给城市带来礼物，句子不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”通常说“发工资”“涨工资”，不说“带来很大的工资”。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”指令人愉快的情绪，与地震造成的破坏正好相反。"}], "explanations": {"灾难": "灾难：严重的自然或人为祸害，与“地震”和“很大的”搭配，符合句意。", "礼物": "语义：地震是灾害，不会给城市带来礼物，句子不通。", "工资": "搭配：“工资”通常说“发工资”“涨工资”，不说“带来很大的工资”。", "欢乐": "语义：“欢乐”指令人愉快的情绪，与地震造成的破坏正好相反。"}, "sentence_index": 0, "correct_answer": "灾难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的灾难很精彩，观众都很激动。", "explanation": "这里应该用〈比赛〉。比赛是体育或竞技活动，可以精彩、令人激动；灾难指严重的祸害，不能用来形容精彩的事，两者意义和感情色彩都相反。"}, {"text": "春节是我们最重要的灾难，全家人都团聚在一起。", "explanation": "这里应该用〈节日〉。节日指欢庆、团聚的日子；灾难指严重的祸害，不能用来指春节这样喜庆的节日，意义相反。"}, {"text": "这次郊游很顺利，大家玩得很开心，是一场灾难。", "explanation": "这里应该用〈愉快的郊游〉，说“是一场愉快的郊游”。灾难指严重的祸害，不能用来形容顺利、开心的郊游，感情色彩正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灾难", "is_correct": true, "explanation": "灾难：严重的祸害，与“发生了”和“人们都很担心”的语境相符。"}, {"text": "喜事", "is_correct": false, "explanation": "语义：“喜事”是令人高兴的事，与后半句“人们都很担心”相矛盾。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“发生”指事件出现，“游戏”是用来玩的，不说“发生了游戏”。"}, {"text": "演出", "is_correct": false, "explanation": "搭配：“演出”通常说“举办”“进行”，不说“发生了演出”。"}], "explanations": {"灾难": "灾难：严重的祸害，与“发生了”和“人们都很担心”的语境相符。", "喜事": "语义：“喜事”是令人高兴的事，与后半句“人们都很担心”相矛盾。", "游戏": "搭配：“发生”指事件出现，“游戏”是用来玩的，不说“发生了游戏”。", "演出": "搭配：“演出”通常说“举办”“进行”，不说“发生了演出”。"}, "sentence_index": 6, "correct_answer": "灾难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的灾难很好，我们去公园散步。", "explanation": "这里应该用〈天气〉。天气指每天的晴雨冷暖，可以好或不好；灾难指严重的祸害，不能用来形容天气好坏，意义完全不同。"}, {"text": "这家饭馆的灾难很好吃，我们常来这里吃饭。", "explanation": "这里应该用〈菜〉。菜可以好吃；灾难指严重的祸害，不能用来形容饭菜好吃，两者意义相反。"}, {"text": "他终于考上了梦想中的大学，这真是一场灾难。", "explanation": "这里应该用〈喜事〉。灾难指严重的祸害，不能用来形容考上梦想大学这样的好事，两者感情色彩正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的事故灾难了很多人。", "corrected_sentence": "这次的事故伤害了很多人。", "error_description": "错误：“灾难”是名词，不能当动词用，“灾难了”不成立。正确说法是“伤害了很多人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那颗灾难让很多家庭失去了亲人。", "corrected_sentence": "那场灾难让很多家庭失去了亲人。", "error_description": "错误：“灾难”的量词应用“场”，不能用“颗”（“颗”多用于小而圆的东西）。正确说法是“那场灾难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
