INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90817, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "笨蛋是说一个人不够聪明，常做错事。", "primary_collocate": null, "pronunciation": "bèn dàn", "ipa": "pən˥˩ tan˥˩", "syllable_count": 2, "sentences": [{"text": "小王常常算错数，大家都笑他是笨蛋。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个笨蛋又把门锁在外面了。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我真是笨蛋，今天又坐错了车。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是笨蛋，只是做事太着急。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笨蛋才会把钱放在桌子上不管。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个笨蛋总是写错同一个字。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟有时像个笨蛋，常常穿反鞋子。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想当笨蛋，所以每天认真检查作业。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我那个笨蛋同学又走错教室了。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，每个人都会做错事，你不是笨蛋。", "target_word": "笨蛋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "不够聪明、常做错事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笨蛋", "is_correct": true, "explanation": "正确：不够聪明、常做错事的人，与“常常算错数”相符。"}, {"text": "聪明人", "is_correct": false, "explanation": "语义：聪明人不会常算错数，与句中“算错数”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人指生病的人，与“算错数”无关，句子说不通。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：路灯不是人，不会“算错数”，句意说不通。"}], "explanations": {"笨蛋": "正确：不够聪明、常做错事的人，与“常常算错数”相符。", "聪明人": "语义：聪明人不会常算错数，与句中“算错数”矛盾。", "病人": "语义：病人指生病的人，与“算错数”无关，句子说不通。", "路灯": "语义：路灯不是人，不会“算错数”，句意说不通。"}, "sentence_index": 0, "correct_answer": "笨蛋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在街上遇见一块笨蛋。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，笨蛋指人，不能用“块”。"}, {"text": "这台笨蛋相机操作很简单。", "explanation": "这里应该用〈傻瓜〉。“傻瓜相机”是固定说法，笨蛋不能用来修饰相机。"}, {"text": "我看见一把笨蛋在门口吵架。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，笨蛋指人，不能用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笨蛋", "is_correct": true, "explanation": "正确：不够聪明、常做错事的人，与“常常穿反鞋子”的孩子气相符。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像不会穿鞋，与“常常穿反鞋子”的孩子气行为不符。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：“像个冰块”说的是冷漠，与“常常穿反鞋子”的行为无关。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“像个”后面要说人或动物的样子，窗户不能用来比喻弟弟。"}], "explanations": {"笨蛋": "正确：不够聪明、常做错事的人，与“常常穿反鞋子”的孩子气相符。", "雕像": "语义：雕像不会穿鞋，与“常常穿反鞋子”的孩子气行为不符。", "冰块": "语义：“像个冰块”说的是冷漠，与“常常穿反鞋子”的行为无关。", "窗户": "搭配：“像个”后面要说人或动物的样子，窗户不能用来比喻弟弟。"}, "sentence_index": 6, "correct_answer": "笨蛋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里来了一副笨蛋。", "explanation": "这里应该用〈个〉。“副”用于眼镜、扑克等成套的东西，笨蛋指人，不能用“副”。"}, {"text": "门口站着三条笨蛋。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，如鱼、河、裤子，笨蛋指人，不能用“条”。"}, {"text": "车站里走来一双笨蛋。", "explanation": "这里应该用〈个〉。“双”用于鞋袜、手等成对的东西，不用于指人的笨蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他嘴上说自己是一根笨蛋，心里却很骄傲。", "corrected_sentence": "他嘴上说自己是个笨蛋，心里却很骄傲。", "error_description": "错误：量词“根”用于细长的东西，笨蛋指人，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他虽然偶尔马虎，但绝不是一根笨蛋。", "corrected_sentence": "他虽然偶尔马虎，但绝不是个笨蛋。", "error_description": "错误：量词“根”用于细长的东西，笨蛋指人，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
