INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90819, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "章是书里的一大段。一本书常常分成很多章。", "primary_collocate": null, "pronunciation": "zhāng", "ipa": "ʈʂɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这本书分成八章。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天读完了第二章。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第四章里有一个很有意思的故事。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说下节课学第六章。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一章的名字是“春天”。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把第一章的故事讲给妹妹听。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说的每一章都很长。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看到第三章就睡着了。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的最后一章，主人公回家了。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一章太难了，我读了三遍。", "target_word": "章", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "章节", "label": "复合词"}], "register": "中性", "sense_fingerprint": "书里的一大段，常用“第几章”表示顺序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90819, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "章", "is_correct": true, "explanation": "zhāng（第一声）：书里的一大段，常用“第几章”表示顺序。"}, {"text": "掌", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是手掌。"}, {"text": "账", "is_correct": false, "explanation": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是账目。"}, {"text": "伤", "is_correct": false, "explanation": "shāng 与 zhāng 声母不同（sh／zh），意思是受伤。"}, {"text": "脏", "is_correct": false, "explanation": "zāng 与 zhāng 声母不同（z／zh），意思是不干净。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 zhāng 韵母不同（eng／ang），意思是争夺。"}], "explanations": {"章": "zhāng（第一声）：书里的一大段，常用“第几章”表示顺序。", "掌": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是手掌。", "账": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是账目。", "伤": "shāng 与 zhāng 声母不同（sh／zh），意思是受伤。", "脏": "zāng 与 zhāng 声母不同（z／zh），意思是不干净。", "争": "zhēng 与 zhāng 韵母不同（eng／ang），意思是争夺。"}, "sentence_index": null, "correct_answer": "章"}, "level_3": {"options": [{"text": "章", "is_correct": true, "explanation": "章指书里的一大段，“分成八章”表示分为八个部分。"}, {"text": "盆", "is_correct": false, "explanation": "语义：书不能分成盆，“分成八盆”与书的结构无关。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：瓶子不是书的组成部分，句子说不通。"}, {"text": "串", "is_correct": false, "explanation": "搭配：“分成”后接的应是书的组成部分，“串”不能与之搭配。"}], "explanations": {"章": "章指书里的一大段，“分成八章”表示分为八个部分。", "盆": "语义：书不能分成盆，“分成八盆”与书的结构无关。", "瓶": "语义：瓶子不是书的组成部分，句子说不通。", "串": "搭配：“分成”后接的应是书的组成部分，“串”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "章"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一章是我的朋友。", "explanation": "这里不能用〈章〉指人。〈章〉指书的一大段，指人的应说“朋友”。"}, {"text": "这一章里有八章。", "explanation": "这里不能用〈章〉指〈节〉。〈章〉是书的一大段，一章里不能包含八章，应说“八节”。"}, {"text": "这部电视剧的第三章很有意思。", "explanation": "这里不能用〈章〉指〈集〉。电视剧按〈集〉分，〈章〉是书的一大段，不能用于电视剧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90819, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "章", "is_correct": true, "explanation": "zhāng（第一声）：书里的一大段，常用“第几章”表示顺序。"}, {"text": "涨", "is_correct": false, "explanation": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是上涨。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是膨胀。"}, {"text": "招", "is_correct": false, "explanation": "zhāo 与 zhāng 韵母不同（ao／ang），意思是招手或招聘。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng（第一声）与 zhāng 只差介音 u，意思是装载、装饰。"}], "explanations": {"章": "zhāng（第一声）：书里的一大段，常用“第几章”表示顺序。", "涨": "zhǎng（第三声）与 zhāng（第一声）声调不同，意思是上涨。", "胀": "zhàng（第四声）与 zhāng（第一声）声调不同，意思是膨胀。", "招": "zhāo 与 zhāng 韵母不同（ao／ang），意思是招手或招聘。", "装": "zhuāng（第一声）与 zhāng 只差介音 u，意思是装载、装饰。"}, "sentence_index": null, "correct_answer": "章"}, "level_3": {"options": [{"text": "章", "is_correct": true, "explanation": "章是小说中的一大段，“每一章”指小说的每个组成部分。"}, {"text": "杯", "is_correct": false, "explanation": "语义：杯子不是小说的组成部分，“每一杯都很长”不成立。"}, {"text": "盒", "is_correct": false, "explanation": "语义：盒子不能“很长”，与小说的组成部分无关。"}, {"text": "锅", "is_correct": false, "explanation": "搭配：“每一”后接的应是书的组成部分，“锅”不能与之搭配。"}], "explanations": {"章": "章是小说中的一大段，“每一章”指小说的每个组成部分。", "杯": "语义：杯子不是小说的组成部分，“每一杯都很长”不成立。", "盒": "语义：盒子不能“很长”，与小说的组成部分无关。", "锅": "搭配：“每一”后接的应是书的组成部分，“锅”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "章"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一章是一座很高的山。", "explanation": "这里不能用〈章〉指地形。〈章〉是书的一大段，不指自然景物。"}, {"text": "这部话剧的第三章很长。", "explanation": "这里不能用〈章〉指〈幕〉。话剧一般分〈幕〉，不说“章”。"}, {"text": "这一章很好吃，我吃了三遍。", "explanation": "这里不能用〈章〉指食物。〈章〉是书的一大段，不能用来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书一共有十条章。", "corrected_sentence": "这本书一共有十章。", "error_description": "量词错误：计数书的章时不用“条”，直接说“十章”即可。“条”用于细长之物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部章的故事很感人。", "corrected_sentence": "这一章的故事很感人。", "error_description": "量词错误：“部”用于整部作品，书的一章应用“这一章”，不能用“这部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
