INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爸爸的爸爸。", "primary_collocate": null, "pronunciation": "yé ye", "ipa": "jɛ˧˥ jɛ", "syllable_count": 2, "sentences": [{"text": "我爷爷今年七十岁了。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上都去公园走路。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是我爸爸的爸爸。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去看爷爷和奶奶。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给我讲了一个很长的故事。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爷爷住在乡下，家里有一个大院子。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢坐在门口喝茶。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的头发已经白了。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷以前是一位老师。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，爷爷给了我一个红包。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老爷爷", "label": "复合"}, {"form": "爷爷奶奶", "label": "复合"}, {"form": "爺爺", "label": "繁体"}], "register": "口语", "sense_fingerprint": "爸爸的爸爸，亲属称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爷爷", "is_correct": true, "explanation": "爷爷：父亲的父亲，与“我”和“今年七十岁”相符，句意通顺。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不可能活到七十岁，句子语义不通。"}, {"text": "宝宝", "is_correct": false, "explanation": "语义：“宝宝”指幼小的孩子，与“七十岁”的年龄相矛盾。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不可能活到七十岁，与句中的年龄信息相矛盾。"}], "explanations": {"爷爷": "爷爷：父亲的父亲，与“我”和“今年七十岁”相符，句意通顺。", "小狗": "语义：小狗不可能活到七十岁，句子语义不通。", "宝宝": "语义：“宝宝”指幼小的孩子，与“七十岁”的年龄相矛盾。", "小猫": "语义：小猫不可能活到七十岁，与句中的年龄信息相矛盾。"}, "sentence_index": 0, "correct_answer": "爷爷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的爷爷是一位很年轻的女士，她每天都陪我玩。", "explanation": "这里应该用〈阿姨〉。“爷爷”指男性，不能用来指年轻女性，性别搭配错了。"}, {"text": "我爸爸的弟弟每天都来我家，我叫他爷爷。", "explanation": "这里应该用〈叔叔〉。“爷爷”指父亲的父亲，这里用来指父亲的弟弟，辈分不对，应当称叔叔。"}, {"text": "我爸爸是我的爷爷，他今年七十岁了。", "explanation": "这里应该用〈父亲〉。“爷爷”指父亲的父亲，这里却用来指父亲本人，指称的人完全不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爷爷", "is_correct": true, "explanation": "爷爷：年老的男性亲属，与“喜欢坐在门口喝茶”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“喝茶”需要有生命的施事，石头不能喝茶。"}, {"text": "火车", "is_correct": false, "explanation": "配价：“喜欢”和“喝茶”要求有生命的主语，火车不能喝茶。"}, {"text": "凳子", "is_correct": false, "explanation": "语义：凳子是给人坐的东西，不会“坐在门口”喝茶，句意不通。"}], "explanations": {"爷爷": "爷爷：年老的男性亲属，与“喜欢坐在门口喝茶”的语境相符。", "石头": "配价：“喝茶”需要有生命的施事，石头不能喝茶。", "火车": "配价：“喜欢”和“喝茶”要求有生命的主语，火车不能喝茶。", "凳子": "语义：凳子是给人坐的东西，不会“坐在门口”喝茶，句意不通。"}, "sentence_index": 6, "correct_answer": "爷爷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈的爸爸是我的爷爷，她经常带我去看他。", "explanation": "这里应该用〈外公〉。“爷爷”指父亲的父亲，母亲的父亲要说“外公”，指称错了。"}, {"text": "我的爷爷比我大五岁，我们经常一起打篮球。", "explanation": "这里应该用〈哥哥〉。“爷爷”指父亲的父亲，辈分和年龄都与孩子相差很大，不能用来指只比我大五岁的同龄亲属。"}, {"text": "我的爷爷今年才三岁，还在上幼儿园。", "explanation": "这里应该用〈弟弟〉。“爷爷”指父亲的父亲，年纪很大，不能用来指三岁的小孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家里有一只爷爷，他今年七十岁了。", "corrected_sentence": "我家里有一位爷爷，他今年七十岁了。", "error_description": "错误：“爷爷”指人，量词应用“位”，不能用“只”（“只”多用于动物）。正确说法是“一位爷爷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家附近有一颗爷爷，每天都在下棋。", "corrected_sentence": "我家附近有一位爷爷，每天都在下棋。", "error_description": "错误：“爷爷”指人，量词应用“位”，说成“颗”是错的（“颗”多用于小而圆的东西）。正确说法是“一位爷爷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
