INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "父亲的父亲；也用于尊称年老的男子。", "primary_collocate": null, "pronunciation": "yé ye", "ipa": "jɛ˧˥ jɛ", "syllable_count": 2, "sentences": [{"text": "爷爷，您慢点儿走，路上有水。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有一位爷爷在下棋。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷每天早上都喝一杯茶。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友对邻居老人说：“爷爷好！”", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁上，一位爷爷站了起来，我给他让座。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是爸爸的爸爸，今年八十岁。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位爷爷在街口卖了很多年水果。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷，请问去火车站怎么走？", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爷爷带着我去河边钓鱼。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的爷爷最喜欢看京剧。", "target_word": "爷爷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老爷爷", "label": "复合"}, {"form": "爷爷奶奶", "label": "复合"}, {"form": "爺爺", "label": "繁体"}], "register": "口语", "sense_fingerprint": "父亲的父亲，也尊称年老男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爷爷", "is_correct": true, "explanation": "爷爷：对年老男子的尊称，与“您”的敬称和“慢点儿走”的语境相符。"}, {"text": "宝贝", "is_correct": false, "explanation": "语域：“宝贝”是对孩子的亲昵称呼，与“您”的礼貌用语不协调。"}, {"text": "弟弟", "is_correct": false, "explanation": "语义：“弟弟”指同辈或小辈，不是年老的男子，与“您”的敬称相矛盾。"}, {"text": "孙子", "is_correct": false, "explanation": "语义：“孙子”是晚辈，用“您”称呼明显不合辈分。"}], "explanations": {"爷爷": "爷爷：对年老男子的尊称，与“您”的敬称和“慢点儿走”的语境相符。", "宝贝": "语域：“宝贝”是对孩子的亲昵称呼，与“您”的礼貌用语不协调。", "弟弟": "语义：“弟弟”指同辈或小辈，不是年老的男子，与“您”的敬称相矛盾。", "孙子": "语义：“孙子”是晚辈，用“您”称呼明显不合辈分。"}, "sentence_index": 0, "correct_answer": "爷爷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷今年四十岁，他每天都很忙。", "explanation": "这里应该用〈爸爸〉。“爷爷”是父亲的父亲，通常年纪较大，四十岁的人不能是爷爷，这里应当说爸爸。"}, {"text": "那位爷爷是一位老太太，她每天都在公园里跳舞。", "explanation": "这里应该用〈奶奶〉。“爷爷”指男性，不能指老太太，应当用“奶奶”。"}, {"text": "小朋友对路边的小孩说：“爷爷好！”", "explanation": "这里应该用〈小弟弟〉。“爷爷”是对年老男子的尊称，不能用来称呼小孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爷爷", "is_correct": true, "explanation": "爷爷：年老男子的尊称，与“很多年”和“卖水果”的语境相符。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不会“在街口卖了很多年水果”，与“很多年”的时间相矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会在街口“卖了很多年水果”，与“很多年”的时间和人物身份相矛盾。"}, {"text": "顾客", "is_correct": false, "explanation": "配价：“卖”要求有卖方作主语，“顾客”指买东西的人，不能做卖水果的主语。"}], "explanations": {"爷爷": "爷爷：年老男子的尊称，与“很多年”和“卖水果”的语境相符。", "小孩": "语义：小孩不会“在街口卖了很多年水果”，与“很多年”的时间相矛盾。", "婴儿": "语义：婴儿不会在街口“卖了很多年水果”，与“很多年”的时间和人物身份相矛盾。", "顾客": "配价：“卖”要求有卖方作主语，“顾客”指买东西的人，不能做卖水果的主语。"}, "sentence_index": 6, "correct_answer": "爷爷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的同学比我大两岁，我们都叫他爷爷。", "explanation": "这里应该用〈哥哥〉。“爷爷”指年老男子或父亲的父亲，不能用来称呼只比自己大两岁的同学。"}, {"text": "我的表姐很年轻，大家都叫她爷爷。", "explanation": "这里应该用〈姐姐〉。“爷爷”指男性，不能用于年轻的女性。"}, {"text": "幼儿园里的小朋友都叫老师爷爷，那位老师才二十岁。", "explanation": "这里应该用〈老师〉。“爷爷”用来称呼父亲的父亲或年老的男子，不能称呼二十岁的年轻人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只爷爷在街口摆了一个水果摊。", "corrected_sentence": "那位爷爷在街口摆了一个水果摊。", "error_description": "错误：“爷爷”指人，量词应用“位”，不能用“只”（“只”多用于动物）。正确说法是“那位爷爷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那颗爷爷在路边晒太阳。", "corrected_sentence": "那位爷爷在路边晒太阳。", "error_description": "错误：“爷爷”指人，量词应用“位”，不能用“颗”（“颗”多用于小而圆的东西）。正确说法是“那位爷爷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
