INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90825, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90825, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示差不多可以这样看。", "primary_collocate": null, "pronunciation": "suàn shì", "ipa": "suan˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这样也算是一种办法。", "target_word": "算是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的汉语算是不错的了。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天算是一个好天气。", "target_word": "算是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们算是老朋友了。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里冬天不冷，算是很舒服的城市。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她算是我们班最高的学生。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在学校旁边，算是方便的。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有一间小房子，也算是有个家。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天跑步，算是很爱运动的人。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事算是成功了。", "target_word": "算是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不算是", "label": "否定"}, {"form": "也算是", "label": "复合"}], "register": "口语", "sense_fingerprint": "差不多可以这样看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c25b5f-321c-4d4e-a8d4-6527f919495c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "算是", "is_correct": true, "explanation": "算是表示差不多可以这样看，与“也……一种办法”的判断相合。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是记不住，无法表示认定“是一种办法”。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”不能接“办法”，句子不成立。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的对象不能是办法，办法不能被打碎。"}], "explanations": {"算是": "算是表示差不多可以这样看，与“也……一种办法”的判断相合。", "忘记": "语义：“忘记”是记不住，无法表示认定“是一种办法”。", "吃掉": "搭配：“吃掉”不能接“办法”，句子不成立。", "打碎": "搭配：“打碎”的对象不能是办法，办法不能被打碎。"}, "sentence_index": 0, "correct_answer": "算是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "根据合同第三条，甲方算是乙方的代理人。", "explanation": "这里应该用〈确属〉。合同条款要求明确的身份关系，〈算是〉表示大致可以这样看，用于法律关系不合适。"}, {"text": "他考了三十分，算是满分。", "explanation": "这里应该用〈远非〉。三十分与满分相差甚远，〈算是〉表示大致可以这样看，不能说成满分。"}, {"text": "一米算是一百厘米。", "explanation": "这里应该用〈等于〉。换算关系是精确的，〈算是〉只表示大致可以这样看，不能用于换算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "算是", "is_correct": true, "explanation": "算是表示差不多可以这样看，与“住在学校旁边”的判断相合。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与“住在学校旁边”的便利评价不合。"}, {"text": "嫌", "is_correct": false, "explanation": "搭配：“嫌”后接形容词多说“嫌……不/太……”，“嫌方便的”不成立。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，无法对“方便”作出差不多可以这样看的评价。"}], "explanations": {"算是": "算是表示差不多可以这样看，与“住在学校旁边”的判断相合。", "讨厌": "语义：“讨厌”表示不喜欢，与“住在学校旁边”的便利评价不合。", "嫌": "搭配：“嫌”后接形容词多说“嫌……不/太……”，“嫌方便的”不成立。", "拒绝": "语义：“拒绝”表示不接受，无法对“方便”作出差不多可以这样看的评价。"}, "sentence_index": 6, "correct_answer": "算是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收据上的金额算是三百元。", "explanation": "这里应该用〈确为〉。收据上的金额必须确定，〈算是〉表示大致可以这样看，用于收据不合适。"}, {"text": "一年算是十二个月。", "explanation": "这里应该用〈有〉。一年有十二个月是确定的事实，〈算是〉表示大致可以这样看，不能用于确定的事实。"}, {"text": "这杯水只有半杯，算是满杯。", "explanation": "这里应该用〈不算〉。只有半杯远不到满杯，〈算是〉表示大致可以这样看，不能说成满杯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试他算是是进步了。", "corrected_sentence": "这次考试他算是进步了。", "error_description": "重复：“算是”已含“是”，不能再加一个“是”，应说“这次考试他算是进步了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛我算是是拿到了冠军。", "corrected_sentence": "这次比赛我算是拿到了冠军。", "error_description": "重复：“算是”已含“是”，不能再加一个“是”，应说“算是拿到了冠军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
