INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现在的样子。", "primary_collocate": null, "pronunciation": "xiàn zhuàng", "ipa": "ɕjɛn⁵¹ ʈʂwɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这座老城的现状和十年前完全不同。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了照片，我才知道这条河的现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看这家工厂的现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的现状很满意，不想换工作。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的现状是路窄、房子旧。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写写学校图书馆的现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不满意现状，所以每天学习英语。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片森林的现状让人担心。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍下了老房子的现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要改变现状，我们得先了解现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現狀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物现在的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add8433b-3ae1-4b98-b82a-1589f89692b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90827, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状（xiàn zhuàng）指事物现在的样子，是正确答案。"}, {"text": "线装", "is_correct": false, "explanation": "xiàn zhuāng 的第二音节为第一声，与 zhuàng（第四声）不同，意思是用线装订书的方式。"}, {"text": "现账", "is_correct": false, "explanation": "xiàn zhàng 的第二音节少了介音 u，意思是现金结算的账目。"}, {"text": "县长", "is_correct": false, "explanation": "xiàn zhǎng 的第二音节少了介音 u，声调为第三声，与 zhuàng（第四声）不同，意思是县的行政长官。"}], "explanations": {"现状": "现状（xiàn zhuàng）指事物现在的样子，是正确答案。", "线装": "xiàn zhuāng 的第二音节为第一声，与 zhuàng（第四声）不同，意思是用线装订书的方式。", "现账": "xiàn zhàng 的第二音节少了介音 u，意思是现金结算的账目。", "县长": "xiàn zhǎng 的第二音节少了介音 u，声调为第三声，与 zhuàng（第四声）不同，意思是县的行政长官。"}, "sentence_index": null, "correct_answer": "现状"}, "level_3": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状指事物现在的样子，与“十年前”对照，正合句意。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人或动物的身高，不能用来说一座老城的身高。"}, {"text": "作文", "is_correct": false, "explanation": "语义：“作文”指写出来的文章，与老城面貌的变化毫不相干。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”只用于人，不能说老城有学历。"}], "explanations": {"现状": "现状指事物现在的样子，与“十年前”对照，正合句意。", "身高": "搭配：“身高”指人或动物的身高，不能用来说一座老城的身高。", "作文": "语义：“作文”指写出来的文章，与老城面貌的变化毫不相干。", "学历": "搭配：“学历”只用于人，不能说老城有学历。"}, "sentence_index": 0, "correct_answer": "现状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想了解一下他昨天的现状。", "explanation": "这里应该用〈情况〉。现状指事物现在的样子，不能指昨天的情形。"}, {"text": "这家工厂的现状增加了三倍。", "explanation": "这里应该用〈产量〉。“增加”用于产量、人数等数量，现状是状况，不能说增加了几倍。"}, {"text": "这项工作的现状很快。", "explanation": "这里应该用〈进展〉。“很快”形容进展或速度，现状是静态的样子，不能描述速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90827, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状（xiàn zhuàng）指事物现在的样子，是正确答案。"}, {"text": "见状", "is_correct": false, "explanation": "jiàn zhuàng 的声母为 j，与 xiàn 的 x 不同，意思是看到情况后。"}, {"text": "闲装", "is_correct": false, "explanation": "闲装读 xián zhuāng，两个音节的声调都与 xiàn zhuàng 不同。意思是平时穿的便服。"}, {"text": "箱装", "is_correct": false, "explanation": "箱装读 xiāng zhuāng。第一音节是后鼻音 xiāng，不是前鼻音 xiàn，两个音节的声调也不同。意思是用箱子装的。"}], "explanations": {"现状": "现状（xiàn zhuàng）指事物现在的样子，是正确答案。", "见状": "jiàn zhuàng 的声母为 j，与 xiàn 的 x 不同，意思是看到情况后。", "闲装": "闲装读 xián zhuāng，两个音节的声调都与 xiàn zhuàng 不同。意思是平时穿的便服。", "箱装": "箱装读 xiāng zhuāng。第一音节是后鼻音 xiāng，不是前鼻音 xiàn，两个音节的声调也不同。意思是用箱子装的。"}, "sentence_index": null, "correct_answer": "现状"}, "level_3": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状指当前的状况，与“不满意”搭配，正合句意。"}, {"text": "原因", "is_correct": false, "explanation": "搭配：“满意”评价的是结果或状况，不能说对“原因”不满意。"}, {"text": "胜利", "is_correct": false, "explanation": "语义：“胜利”是已经取得的结果，与“不满意”的对象不符，句意不通。"}, {"text": "目的", "is_correct": false, "explanation": "搭配：“目的”是打算达到的结果，不能说“不满意目的”。"}], "explanations": {"现状": "现状指当前的状况，与“不满意”搭配，正合句意。", "原因": "搭配：“满意”评价的是结果或状况，不能说对“原因”不满意。", "胜利": "语义：“胜利”是已经取得的结果，与“不满意”的对象不符，句意不通。", "目的": "搭配：“目的”是打算达到的结果，不能说“不满意目的”。"}, "sentence_index": 6, "correct_answer": "现状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆现状很糟糕，我们得想办法。", "explanation": "这里应该用〈种〉。“辆”用于车辆，现状是抽象的状况，不能用“辆”计数。"}, {"text": "这座现状让人失望。", "explanation": "这里应该用〈种〉。“座”用于建筑、山峰等大型的东西，现状不能用“座”计数。"}, {"text": "这块现状很难改变。", "explanation": "这里应该用〈种〉。“块”用于块状或片状的东西，现状是抽象名词，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条现状值得我们重视。", "corrected_sentence": "这种现状值得我们重视。", "error_description": "量词错误：“条”用于细长的东西，现状是抽象名词，应该用“种”，写作“这种现状”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该先了解这种的现状。", "corrected_sentence": "我们应该先了解这种现状。", "error_description": "结构错误：指示代词“这种”后面不能再加“的”，应说“这种现状”，写作“先了解这种现状”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
