INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "目前的状况。", "primary_collocate": null, "pronunciation": "xiàn zhuàng", "ipa": "ɕjɛn⁵¹ ʈʂwɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这家公司的现状不太好，钱很少。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理向大家介绍了市场的现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了了解农村教育的现状，他去了很多学校。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市交通的现状很差，上班总是堵车。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话很直接，先讲了家里的现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对现状，我们只能努力工作。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里写了这个行业的现状和问题。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人生活的现状需要大家关心。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想改变现状，就去学了新技术。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份调查说明了年轻人睡眠的现状。", "target_word": "现状", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現狀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "目前的状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add8433b-3ae1-4b98-b82a-1589f89692b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状（xiàn zhuàng）指目前的状况，是正确答案。"}, {"text": "线装", "is_correct": false, "explanation": "xiàn zhuāng 的第二音节为第一声，与 zhuàng（第四声）不同，意思是用线装订书的方式。"}, {"text": "现账", "is_correct": false, "explanation": "xiàn zhàng 的第二音节少了介音 u，意思是现金结算的账目。"}, {"text": "县长", "is_correct": false, "explanation": "xiàn zhǎng 的第二音节少了介音 u，声调为第三声，与 zhuàng（第四声）不同，意思是县的行政长官。"}], "explanations": {"现状": "现状（xiàn zhuàng）指目前的状况，是正确答案。", "线装": "xiàn zhuāng 的第二音节为第一声，与 zhuàng（第四声）不同，意思是用线装订书的方式。", "现账": "xiàn zhàng 的第二音节少了介音 u，意思是现金结算的账目。", "县长": "xiàn zhǎng 的第二音节少了介音 u，声调为第三声，与 zhuàng（第四声）不同，意思是县的行政长官。"}, "sentence_index": null, "correct_answer": "现状"}, "level_3": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状指目前的状况，“钱很少”说明公司目前的情况不好，正合句意。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“身材”指人的体形，不能用来说一家公司的身材。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学生的功课或任务，与公司的经营状况无关。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“性别”只用于人或动植物，不能用来形容公司。"}], "explanations": {"现状": "现状指目前的状况，“钱很少”说明公司目前的情况不好，正合句意。", "身材": "搭配：“身材”指人的体形，不能用来说一家公司的身材。", "作业": "语义：“作业”指学生的功课或任务，与公司的经营状况无关。", "性别": "搭配：“性别”只用于人或动植物，不能用来形容公司。"}, "sentence_index": 0, "correct_answer": "现状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他取得了很大的现状。", "explanation": "这里应该用〈成果〉。“取得”的对象是成果、成绩，现状是当前的状况，不能被取得。"}, {"text": "他的现状很高。", "explanation": "这里应该用〈收入〉。“高”用于数量或水平，现状是状况，不说高低。"}, {"text": "这台现状很糟糕。", "explanation": "这里应该用〈种〉。“台”用于机器、设备，现状是抽象名词，不能用“台”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUD