INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90828, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状（xiàn zhuàng）指目前的状况，是正确答案。"}, {"text": "见状", "is_correct": false, "explanation": "jiàn zhuàng 的声母为 j，与 xiàn 的 x 不同，意思是看到情况后。"}, {"text": "闲装", "is_correct": false, "explanation": "闲装读 xián zhuāng，两个音节的声调都与 xiàn zhuàng 不同。意思是平时穿的便服。"}, {"text": "箱装", "is_correct": false, "explanation": "箱装读 xiāng zhuāng。第一音节是后鼻音 xiāng，不是前鼻音 xiàn，两个音节的声调也不同。意思是用箱子装的。"}], "explanations": {"现状": "现状（xiàn zhuàng）指目前的状况，是正确答案。", "见状": "jiàn zhuàng 的声母为 j，与 xiàn 的 x 不同，意思是看到情况后。", "闲装": "闲装读 xián zhuāng，两个音节的声调都与 xiàn zhuàng 不同。意思是平时穿的便服。", "箱装": "箱装读 xiāng zhuāng。第一音节是后鼻音 xiāng，不是前鼻音 xiàn，两个音节的声调也不同。意思是用箱子装的。"}, "sentence_index": null, "correct_answer": "现状"}, "level_3": {"options": [{"text": "现状", "is_correct": true, "explanation": "现状指行业目前的状况，正适合报告中“现状和问题”的说法。"}, {"text": "发音", "is_correct": false, "explanation": "语义：“发音”指读音，报告不会写一个行业的发音。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能用来说一个行业的体重。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人或物体的高度，不能用来说一个行业的身高。"}], "explanations": {"现状": "现状指行业目前的状况，正适合报告中“现状和问题”的说法。", "发音": "语义：“发音”指读音，报告不会写一个行业的发音。", "体重": "搭配：“体重”只用于人或动物，不能用来说一个行业的体重。", "身高": "搭配：“身高”指人或物体的高度，不能用来说一个行业的身高。"}, "sentence_index": 6, "correct_answer": "现状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条现状让人担心。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，现状是抽象的状况，不能用“条”计数。"}, {"text": "这张现状让我们失望。", "explanation": "这里应该用〈种〉。“张”用于平面的东西，如纸、桌子，现状不能用“张”计数。"}, {"text": "这把现状很难改变。", "explanation": "这里应该用〈种〉。“把”用于有把手、可握持的东西，现状是抽象名词，不能用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCL