INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗现状让人担心。", "corrected_sentence": "这种现状让人担心。", "error_description": "量词错误：“颗”用于粒状的小东西，现状是抽象名词，应该用“种”，写作“这种现状”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首现状我们不能接受。", "corrected_sentence": "这种现状我们不能接受。", "error_description": "量词错误：“首”用于诗词、歌曲，现状是抽象名词，应该用“种”，写作“这种现状”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90829, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "正确：马虎指做事不认真、不细心，与精心互为反义。"}, {"text": "轻松", "is_correct": false, "explanation": "无关：轻松指不费力、不紧张，与精心的用心程度没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：热闹形容场面喧嚷，与做事是否用心没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "无关：宽敞形容空间大，与做事是否用心没有反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "正确：马虎指做事不认真、不细心，与精心互为反义。", "轻松": "无关：轻松指不费力、不紧张，与精心的用心程度没有反义关系。", "热闹": "无关：热闹形容场面喧嚷，与做事是否用心没有反义关系。", "宽敞": "无关：宽敞形容空间大，与做事是否用心没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90829, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "正确：马虎指做事不认真、不细心，与精心互为反义。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：清楚形容清晰明白，与做事是否用心没有反义关系。"}, {"text": "热烈", "is_correct": false, "explanation": "无关：热烈形容情绪或场面的高涨，与做事是否用心没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：干净形容没有污物，与做事是否用心没有反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "正确：马虎指做事不认真、不细心，与精心互为反义。", "清楚": "无关：清楚形容清晰明白，与做事是否用心没有反义关系。", "热烈": "无关：热烈形容情绪或场面的高涨，与做事是否用心没有反义关系。", "干净": "无关：干净形容没有污物，与做事是否用心没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90829, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "精心是非常用心，一点也不马虎。", "primary_collocate": null, "pronunciation": "jīng xīn", "ipa": "tɕiŋ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "妈妈精心准备了一桌饭菜。", "target_word": "精心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他精心照顾着生病的奶奶。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼物是我精心挑选的。", "target_word": "精心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师精心设计了今天的课。", "target_word": "精心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天都精心整理自己的房间。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花是爷爷精心种的。", "target_word": "精心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们精心写好了每一份报告，一点错也没有。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这次比赛，他精心练习了三个月。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的作品精心包好，送给了朋友。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们精心做了一张生日卡片。", "target_word": "精心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "精心地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "做事非常用心，不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90829, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确答案：精心，意思是做事非常用心，一点也不马虎。"}, {"text": "静心", "is_correct": false, "explanation": "声调：静心 jìng xīn 与 精心 jīng xīn 只有第一个字的声调不同（第四声与第一声），静心意思是使心神安静。"}, {"text": "清心", "is_correct": false, "explanation": "声母：清心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），清心意思是使心境清净。"}, {"text": "精神", "is_correct": false, "explanation": "近音：精神 jīngshen 与 精心 jīng xīn 第一个字相同，第二个字读音不同，精神指人的意识、活力。"}], "explanations": {"精心": "正确答案：精心，意思是做事非常用心，一点也不马虎。", "静心": "声调：静心 jìng xīn 与 精心 jīng xīn 只有第一个字的声调不同（第四声与第一声），静心意思是使心神安静。", "清心": "声母：清心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），清心意思是使心境清净。", "精神": "近音：精神 jīngshen 与 精心 jīng xīn 第一个字相同，第二个字读音不同，精神指人的意识、活力。"}, "sentence_index": null, "correct_answer": "精心"}, "level_3": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确：精心修饰「准备」，说明妈妈做饭很用心，与「一桌饭菜」相合。"}, {"text": "粗心", "is_correct": false, "explanation": "语法：粗心是形容词，不能直接修饰动词「准备」（需加「地」），且与「精心」语义相反。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：随口多用于说话，与「准备一桌饭菜」搭配不自然。"}, {"text": "精彩", "is_correct": false, "explanation": "语法：精彩是形容词，不能直接修饰动词「准备」，需加「地」。"}], "explanations": {"精心": "正确：精心修饰「准备」，说明妈妈做饭很用心，与「一桌饭菜」相合。", "粗心": "语法：粗心是形容词，不能直接修饰动词「准备」（需加「地」），且与「精心」语义相反。", "随口": "搭配：随口多用于说话，与「准备一桌饭菜」搭配不自然。", "精彩": "语法：精彩是形容词，不能直接修饰动词「准备」，需加「地」。"}, "sentence_index": 0, "correct_answer": "精心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他精心翻了翻杂志。", "explanation": "这里应该用〈随意〉。精心表示特别用心，不能用来形容「翻了翻」这种随便看看的动作。"}, {"text": "他精心把垃圾扔在了桌子底下，就走了。", "explanation": "这里应该用〈随便〉。精心表示特别用心，与随手乱扔垃圾的做法相矛盾。"}, {"text": "他精心吃了几口就走了。", "explanation": "这里应该用〈随便〉。精心指特别用心，与吃几口就走的草率做法不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90829, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确答案：精心，意思是做事非常用心，一点也不马虎。"}, {"text": "冰心", "is_correct": false, "explanation": "声母：冰心 bīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（b 与 j），冰心指像冰一样纯洁的心。"}, {"text": "精金", "is_correct": false, "explanation": "声母：精金 jīng jīn 与 精心 jīng xīn 只有第二个字的声母不同（j 与 x），精金指纯度很高的金子。"}, {"text": "轻心", "is_correct": false, "explanation": "声母：轻心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），轻心指不在意、不重视（如「掉以轻心」）。"}], "explanations": {"精心": "正确答案：精心，意思是做事非常用心，一点也不马虎。", "冰心": "声母：冰心 bīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（b 与 j），冰心指像冰一样纯洁的心。", "精金": "声母：精金 jīng jīn 与 精心 jīng xīn 只有第二个字的声母不同（j 与 x），精金指纯度很高的金子。", "轻心": "声母：轻心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），轻心指不在意、不重视（如「掉以轻心」）。"}, "sentence_index": null, "correct_answer": "精心"}, "level_3": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确：精心修饰「写好」，说明报告写得细致，与「一点错也没有」相合。"}, {"text": "随手", "is_correct": false, "explanation": "语义：随手指顺便、不经心，与「一点错也没有」的要求相抵触。"}, {"text": "独自", "is_correct": false, "explanation": "配价：独自指单独一人，这里的主语是复数的「我们」，不能说我们独自写。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示次数很少，与「每一份报告」都要写好相冲突。"}], "explanations": {"精心": "正确：精心修饰「写好」，说明报告写得细致，与「一点错也没有」相合。", "随手": "语义：随手指顺便、不经心，与「一点错也没有」的要求相抵触。", "独自": "配价：独自指单独一人，这里的主语是复数的「我们」，不能说我们独自写。", "偶尔": "语义：偶尔表示次数很少，与「每一份报告」都要写好相冲突。"}, "sentence_index": 6, "correct_answer": "精心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他精心地三两下就把作业交了上去。", "explanation": "这里应该用〈草率〉。精心表示特别用心，不能用来形容三两下草草交作业的做法。"}, {"text": "他精心交了一份空白的试卷。", "explanation": "这里应该用〈马虎〉。精心表示细致不马虎，交白卷的做法与之相反。"}, {"text": "他精心看了一眼我的作业，就签了字。", "explanation": "这里应该用〈敷衍〉。精心表示细致用心，看一眼就签字的做法属于敷衍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
