INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90830, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "特别用心，细致周到。", "primary_collocate": null, "pronunciation": "jīng xīn", "ipa": "tɕiŋ˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "经理精心安排了客人的每一餐。", "target_word": "精心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的花都是工人们精心养的。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他精心布置着新家，每个地方都很漂亮。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店为客人精心准备了很多小点心。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生和护士精心照顾每一位病人。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她精心打扮了一下，才去参加朋友的婚礼。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板精心招待了远方来的朋友。", "target_word": "精心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校为新同学精心设计了欢迎活动。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶精心做的鞋垫又软又舒服。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕是师傅精心做出来的。", "target_word": "精心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精心地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "安排、照料得特别用心，细致周到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90830, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确答案：精心，意思是特别用心，细致周到。"}, {"text": "静心", "is_correct": false, "explanation": "声调：静心 jìng xīn 与 精心 jīng xīn 只有第一个字的声调不同（第四声与第一声），静心意思是使心神安静。"}, {"text": "清心", "is_correct": false, "explanation": "声母：清心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），清心意思是使心境清净。"}, {"text": "精神", "is_correct": false, "explanation": "近音：精神 jīngshen 与 精心 jīng xīn 第一个字相同，第二个字读音不同，精神指人的意识、活力。"}], "explanations": {"精心": "正确答案：精心，意思是特别用心，细致周到。", "静心": "声调：静心 jìng xīn 与 精心 jīng xīn 只有第一个字的声调不同（第四声与第一声），静心意思是使心神安静。", "清心": "声母：清心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），清心意思是使心境清净。", "精神": "近音：精神 jīngshen 与 精心 jīng xīn 第一个字相同，第二个字读音不同，精神指人的意识、活力。"}, "sentence_index": null, "correct_answer": "精心"}, "level_3": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确：精心修饰「安排」，说明经理安排得细致周到，与「客人的每一餐」相合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示次数很少，与「客人的每一餐」要全部安排相冲突。"}, {"text": "粗心", "is_correct": false, "explanation": "语法：粗心是形容词，不能直接修饰动词「安排」（需加「地」），且与「精心」语义相反。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：随口多用于说话，与「安排每一餐」搭配不自然。"}], "explanations": {"精心": "正确：精心修饰「安排」，说明经理安排得细致周到，与「客人的每一餐」相合。", "偶尔": "语义：偶尔表示次数很少，与「客人的每一餐」要全部安排相冲突。", "粗心": "语法：粗心是形容词，不能直接修饰动词「安排」（需加「地」），且与「精心」语义相反。", "随口": "搭配：随口多用于说话，与「安排每一餐」搭配不自然。"}, "sentence_index": 0, "correct_answer": "精心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他精心把钥匙落在了出租车上。", "explanation": "这里应该用〈粗心〉。精心表示特别用心，不能用来形容把钥匙落在车上这种疏忽。"}, {"text": "他精心地一拍脑袋，就决定了去国外工作。", "explanation": "这里应该用〈草率〉。精心表示细致考虑，一拍脑袋就决定的做法与之矛盾。"}, {"text": "他精心地把我的问题晾在一边，没有回答。", "explanation": "这里应该用〈敷衍〉。精心表示认真对待，把问题晾着不理的做法属于敷衍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90830, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确答案：精心，意思是特别用心，细致周到。"}, {"text": "冰心", "is_correct": false, "explanation": "声母：冰心 bīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（b 与 j），冰心指像冰一样纯洁的心。"}, {"text": "精金", "is_correct": false, "explanation": "声母：精金 jīng jīn 与 精心 jīng xīn 只有第二个字的声母不同（j 与 x），精金指纯度很高的金子。"}, {"text": "轻心", "is_correct": false, "explanation": "声母：轻心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），轻心指不在意、不重视（如「掉以轻心」）。"}], "explanations": {"精心": "正确答案：精心，意思是特别用心，细致周到。", "冰心": "声母：冰心 bīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（b 与 j），冰心指像冰一样纯洁的心。", "精金": "声母：精金 jīng jīn 与 精心 jīng xīn 只有第二个字的声母不同（j 与 x），精金指纯度很高的金子。", "轻心": "声母：轻心 qīng xīn 与 精心 jīng xīn 只有第一个字的声母不同（q 与 j），轻心指不在意、不重视（如「掉以轻心」）。"}, "sentence_index": null, "correct_answer": "精心"}, "level_3": {"options": [{"text": "精心", "is_correct": true, "explanation": "正确：精心修饰「招待」，说明老板对远方来的朋友很周到，与语境相合。"}, {"text": "随口", "is_correct": false, "explanation": "搭配：随口多用于说话，不能修饰「招待」。"}, {"text": "精彩", "is_correct": false, "explanation": "语法：精彩是形容词，不能直接修饰动词「招待」，需加「地」。"}, {"text": "随手", "is_correct": false, "explanation": "语义：随手指顺手、不经心，与招待远方来的朋友的郑重语境不合。"}], "explanations": {"精心": "正确：精心修饰「招待」，说明老板对远方来的朋友很周到，与语境相合。", "随口": "搭配：随口多用于说话，不能修饰「招待」。", "精彩": "语法：精彩是形容词，不能直接修饰动词「招待」，需加「地」。", "随手": "语义：随手指顺手、不经心，与招待远方来的朋友的郑重语境不合。"}, "sentence_index": 6, "correct_answer": "精心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他精心弄丢了那本书。", "explanation": "这里应该用〈马虎〉。精心表示细致用心，不能用来形容弄丢东西这种马虎的结果。"}, {"text": "她精心看了一眼文件，就把它扔进了垃圾桶。", "explanation": "这里应该用〈随便〉。精心表示细致周到，看一眼就扔掉的做法与之相反。"}, {"text": "她精心吃了一口饭，就急着去上班了。", "explanation": "这里应该用〈匆忙〉。精心表示细致周到，急着赶去上班的做法与之不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师精心着修好了那台旧钢琴。", "corrected_sentence": "老师精心修好了那台旧钢琴。", "error_description": "错误：「精心」作状语后不能接持续标记「着」，「着」在这里多余。正确：应说「老师精心修好了那台旧钢琴」，去掉「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶精心得缝了一件衣服。", "corrected_sentence": "奶奶精心地缝了一件衣服。", "error_description": "错误：状语后应用「地」，这里误用了「得」。「得」用于动词之后作补语。正确：应说「精心地缝了一件衣服」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
