INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "简要的介绍。", "primary_collocate": null, "pronunciation": "jiǎn jiè", "ipa": "tɕjɛn˨˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "请先看一下这本书的简介。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写一份简介，说说自己的爱好。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上有这家公司的简介。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影的简介只有两百字。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的后面有一段简介，介绍作者。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始前，经理先给大家读了一份简介。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份简介写得很清楚。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先读一下这门课的简介，再决定选不选。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上找到了这个城市的简介。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的简介发给我。", "target_word": "简介", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "段", "label": "量词"}, {"form": "内容简介", "label": "复合"}, {"form": "作者简介", "label": "复合"}, {"form": "簡介", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事物的简要介绍文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e181de4b-e0bb-4f31-9797-de1e0fbe4536') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90832, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简介", "is_correct": true, "explanation": "简介：jiǎn jiè，简要的介绍。"}, {"text": "简洁", "is_correct": false, "explanation": "第二个音节 jié（第二声）与 jiè（第四声）声调不同，意思是简单明了，不是介绍。"}, {"text": "间接", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）、jiē（第一声）与 jiè（第四声）声调不同，意思是不直接。"}, {"text": "剪接", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，意思是把影片等剪辑后连接起来。"}, {"text": "见解", "is_correct": false, "explanation": "jiàn（第四声）与 jiǎn（第三声）、jiě（第三声）与 jiè（第四声）声调不同，意思是对事情的看法。"}], "explanations": {"简介": "简介：jiǎn jiè，简要的介绍。", "简洁": "第二个音节 jié（第二声）与 jiè（第四声）声调不同，意思是简单明了，不是介绍。", "间接": "jiàn（第四声）与 jiǎn（第三声）、jiē（第一声）与 jiè（第四声）声调不同，意思是不直接。", "剪接": "jiē（第一声）与 jiè（第四声）声调不同，意思是把影片等剪辑后连接起来。", "见解": "jiàn（第四声）与 jiǎn（第三声）、jiě（第三声）与 jiè（第四声）声调不同，意思是对事情的看法。"}, "sentence_index": null, "correct_answer": "简介"}, "level_3": {"options": [{"text": "简介", "is_correct": true, "explanation": "简介：这里指书的内容简要介绍，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，书没有体重，不能说“这本书的体重”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人或动物的性情，书没有脾气，句子读不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体貌特征，不能用来描述一本书。"}], "explanations": {"简介": "简介：这里指书的内容简要介绍，符合句意。", "体重": "搭配：“体重”只用于人或动物，书没有体重，不能说“这本书的体重”。", "脾气": "语义：“脾气”指人或动物的性情，书没有脾气，句子读不通。", "身高": "体貌：“身高”是人的体貌特征，不能用来描述一本书。"}, "sentence_index": 0, "correct_answer": "简介"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位导游的简介讲了整整一个小时，大家都累了。", "explanation": "这里应该用〈讲解〉。简介强调简短，讲一个小时的长篇内容要用讲解，不能说简介很长。"}, {"text": "他把个人简介写了三十页，老师看了都很惊讶。", "explanation": "这里应该用〈自传〉。简介只用几句话说清楚，写三十页的个人经历要用自传。"}, {"text": "这份简介有三十个章节，我读了一个月。", "explanation": "这里应该用〈目录〉。简介只用几句话概括内容，列出三十个章节要用目录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简介", "is_correct": true, "explanation": "简介：这里指这份文字材料，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“写得很清楚”说的是文字内容，不能用来描述颜色。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能用“份”，也不是写出来的文字材料，句子不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音不能“写”得很清楚，这个搭配不成立。"}], "explanations": {"简介": "简介：这里指这份文字材料，符合句意。", "颜色": "搭配：“写得很清楚”说的是文字内容，不能用来描述颜色。", "天气": "搭配：“天气”不能用“份”，也不是写出来的文字材料，句子不通。", "声音": "搭配：声音不能“写”得很清楚，这个搭配不成立。"}, "sentence_index": 6, "correct_answer": "简介"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份简介很重，请你帮我搬到楼上。", "explanation": "这里应该用〈资料〉。简介是说明人或事的文字，不能说重或搬；大份资料才会用“重”。"}, {"text": "这份简介好吃极了。", "explanation": "这里应该用〈菜谱〉。简介是介绍人或事的文字，“好吃”用于食物，要用菜谱。"}, {"text": "老师在作文后面写了一段简介。", "explanation": "这里应该用〈评语〉。老师在作文后面写的是评价，简介只是简要介绍内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨晚写了一只简介给老师看。", "corrected_sentence": "我昨晚写了一份简介给老师看。", "error_description": "“一只简介”错误，应为“一份简介”。“只”一般用于动物或成对物体中的一个，文字材料不用“只”，量词要用“份”或“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我简介很短，你可以再看看。", "corrected_sentence": "我的简介很短，你可以再看看。", "error_description": "漏了“的”。“我的简介”是修饰关系，名词前面的人称代词要加“的”，不能说“我简介”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df20cb0f-a86a-4bbf-8f82-2ae245f1f64b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
