INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90833, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "开店卖东西，赚钱的事。", "primary_collocate": null, "pronunciation": "shēng yi", "ipa": "ʂɤŋ˥ i", "syllable_count": 2, "sentences": [{"text": "我家开了一个小店，生意还不错。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上饭店多，生意都很好。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天来买东西的人少，生意不好做。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在门口卖菜，做的是小生意。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想做点小生意，自己当老板。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你们照顾我的生意。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家面馆的生意一直很好，天天有人排队。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末商店的生意比平时好。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学校旁边开了家店，专做学生的生意。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市开在对面，我们店的生意少了。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "桩", "label": "量词"}], "register": "口语", "sense_fingerprint": "开店卖东西赚钱的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生意", "is_correct": true, "explanation": "生意（shēng yi）：开店卖东西、赚钱的事，即听到的词。"}, {"text": "声誉", "is_correct": false, "explanation": "shēng yù 与 shēng yi 韵母不同，意思是名声、信誉。"}, {"text": "生硬", "is_correct": false, "explanation": "yìng 与 yi 韵尾不同，意思是不柔和、不自然。"}, {"text": "声音", "is_correct": false, "explanation": "yīn 与 yi 相比多了韵尾 n，意思是声响、嗓音。"}], "explanations": {"生意": "生意（shēng yi）：开店卖东西、赚钱的事，即听到的词。", "声誉": "shēng yù 与 shēng yi 韵母不同，意思是名声、信誉。", "生硬": "yìng 与 yi 韵尾不同，意思是不柔和、不自然。", "声音": "yīn 与 yi 相比多了韵尾 n，意思是声响、嗓音。"}, "sentence_index": null, "correct_answer": "生意"}, "level_3": {"options": [{"text": "生意", "is_correct": true, "explanation": "正确：“生意还不错”指店里卖东西的情况好，说得通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：小店没有“年龄”，“年龄还不错”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：小店不会有“脾气”，这句话说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来评价一家小店。"}], "explanations": {"生意": "正确：“生意还不错”指店里卖东西的情况好，说得通。", "年龄": "语义：小店没有“年龄”，“年龄还不错”说不通。", "脾气": "语义：小店不会有“脾气”，这句话说不通。", "身材": "体貌：“身材”指人的体形，不能用来评价一家小店。"}, "sentence_index": 0, "correct_answer": "生意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶靠卖菜过生意。", "explanation": "这里应该用〈生活〉。“过”后接“生活”，生意指买卖，不能说“过生意”。"}, {"text": "她每天都去生意上学。", "explanation": "这里应该用〈学校〉。生意指买卖、经营活动，不是学习的地方；说去哪里上学要用“学校”。"}, {"text": "她做成了一只小生意。", "explanation": "量词错误：“生意”的量词是“笔”或“桩”，不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90833, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生意", "is_correct": true, "explanation": "生意（shēng yi）：开店卖东西、赚钱的事，即听到的词。"}, {"text": "生育", "is_correct": false, "explanation": "shēng yù（第四声）与 shēng yi（轻声）韵母不同，意思是生孩子、繁殖。"}, {"text": "生疑", "is_correct": false, "explanation": "yí（第二声）与 yi（轻声）声调不同，意思是产生怀疑。"}, {"text": "盛意", "is_correct": false, "explanation": "shèng yì 与 shēng yi 声调不同，意思是深厚的情意。"}], "explanations": {"生意": "生意（shēng yi）：开店卖东西、赚钱的事，即听到的词。", "生育": "shēng yù（第四声）与 shēng yi（轻声）韵母不同，意思是生孩子、繁殖。", "生疑": "yí（第二声）与 yi（轻声）声调不同，意思是产生怀疑。", "盛意": "shèng yì 与 shēng yi 声调不同，意思是深厚的情意。"}, "sentence_index": null, "correct_answer": "生意"}, "level_3": {"options": [{"text": "生意", "is_correct": true, "explanation": "正确：“这家面馆的生意一直很好”指经营状况，说得通。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：面馆没有“脸色”，这句话说的是店里的经营状况，说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：面馆没有“性格”，“性格一直很好”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高度，不能用来说一家面馆。"}], "explanations": {"生意": "正确：“这家面馆的生意一直很好”指经营状况，说得通。", "脸色": "语义：面馆没有“脸色”，这句话说的是店里的经营状况，说不通。", "性格": "语义：面馆没有“性格”，“性格一直很好”说不通。", "身高": "体貌：“身高”指人的身体高度，不能用来说一家面馆。"}, "sentence_index": 6, "correct_answer": "生意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的生意每个月都很高。", "explanation": "这里应该用〈工资〉。生意指买卖，不能用“高”来说个人收入的多少；说收入要用“工资”。"}, {"text": "我们去年谈成了一座生意。", "explanation": "量词错误：“生意”不用“座”，量词应用“笔”或“桩”。"}, {"text": "他每天在生意里看书。", "explanation": "这里应该用〈书店〉。生意指买卖、经营活动，不是地点；说在哪里看书要用“书店”或“图书馆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我们店做成了一座生意。", "corrected_sentence": "今天我们店做成了一笔生意。", "error_description": "量词错误：应说“一笔生意”，“座”多用于山、桥、建筑，不能用于生意。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条生意他做了二十年。", "corrected_sentence": "这门生意他做了二十年。", "error_description": "量词错误：做了多年的一种生意应说“这门生意”，“条”用于细长的东西，不能用于生意。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
