INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买卖；商业经营活动。", "primary_collocate": null, "pronunciation": "shēng yi", "ipa": "ʂɤŋ˥ i", "syllable_count": 2, "sentences": [{"text": "他做生意很多年了。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近生意不太好。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔生意能赚不少钱。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸想跟朋友一起做生意。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的生意做到了国外。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生意上的事，他从来不跟家人说。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，生意特别忙。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠做生意养大了三个孩子。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人很会做生意。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，今年冬天的生意差了很多。", "target_word": "生意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "桩", "label": "量词"}], "register": "口语", "sense_fingerprint": "买卖、商业经营活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生意", "is_correct": true, "explanation": "生意（shēng yi）：买卖、商业经营活动，即听到的词。"}, {"text": "生育", "is_correct": false, "explanation": "shēng yù（第四声）与 shēng yi（轻声）韵母不同，意思是生孩子、繁殖。"}, {"text": "生疑", "is_correct": false, "explanation": "yí（第二声）与 yi（轻声）声调不同，意思是产生怀疑。"}, {"text": "盛意", "is_correct": false, "explanation": "shèng yì 与 shēng yi 声调不同，意思是深厚的情意。"}], "explanations": {"生意": "生意（shēng yi）：买卖、商业经营活动，即听到的词。", "生育": "shēng yù（第四声）与 shēng yi（轻声）韵母不同，意思是生孩子、繁殖。", "生疑": "yí（第二声）与 yi（轻声）声调不同，意思是产生怀疑。", "盛意": "shèng yì 与 shēng yi 声调不同，意思是深厚的情意。"}, "sentence_index": null, "correct_answer": "生意"}, "level_3": {"options": [{"text": "生意", "is_correct": true, "explanation": "正确：“做生意”指经营买卖，与“很多年了”相合。"}, {"text": "错误", "is_correct": false, "explanation": "搭配：“做”不能接“错误”，应说“犯错误”。"}, {"text": "事故", "is_correct": false, "explanation": "搭配：“做”不能接“事故”，应说“出事故”。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：人不能“做”成小猫，这句话说不通。"}], "explanations": {"生意": "正确：“做生意”指经营买卖，与“很多年了”相合。", "错误": "搭配：“做”不能接“错误”，应说“犯错误”。", "事故": "搭配：“做”不能接“事故”，应说“出事故”。", "小猫": "语义：人不能“做”成小猫，这句话说不通。"}, "sentence_index": 0, "correct_answer": "生意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生意是老师。", "explanation": "这里应该用〈职业〉。生意指买卖、经营活动，不能用来说人的职业；说职业要用“工作”或“职业”。"}, {"text": "我每天都去生意上班。", "explanation": "这里应该用〈公司〉。生意指买卖、经营活动，不是工作的地点；说去哪里上班要用“公司”或“单位”。"}, {"text": "我刚谈成了一只生意。", "explanation": "量词错误：“生意”的量词是“笔”或“桩”，不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90834, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生意", "is_correct": true, "explanation": "生意（shēng yi）：买卖、商业经营活动，即听到的词。"}, {"text": "声誉", "is_correct": false, "explanation": "shēng yù 与 shēng yi 韵母不同，意思是名声、信誉。"}, {"text": "生硬", "is_correct": false, "explanation": "yìng 与 yi 韵尾不同，意思是不柔和、不自然。"}, {"text": "声音", "is_correct": false, "explanation": "yīn 与 yi 相比多了韵尾 n，意思是声响、嗓音。"}], "explanations": {"生意": "生意（shēng yi）：买卖、商业经营活动，即听到的词。", "声誉": "shēng yù 与 shēng yi 韵母不同，意思是名声、信誉。", "生硬": "yìng 与 yi 韵尾不同，意思是不柔和、不自然。", "声音": "yīn 与 yi 相比多了韵尾 n，意思是声响、嗓音。"}, "sentence_index": null, "correct_answer": "生意"}, "level_3": {"options": [{"text": "生意", "is_correct": true, "explanation": "正确：“生意”指买卖，“过年的时候，生意特别忙”说得通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“忙”一般不用来修饰“心情”，不能说“心情特别忙”。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不会“忙”，这里说的是人的经营活动繁忙。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能说“特别忙”。"}], "explanations": {"生意": "正确：“生意”指买卖，“过年的时候，生意特别忙”说得通。", "心情": "搭配：“忙”一般不用来修饰“心情”，不能说“心情特别忙”。", "饺子": "语义：饺子不会“忙”，这里说的是人的经营活动繁忙。", "身材": "体貌：“身材”指人的体形，不能说“特别忙”。"}, "sentence_index": 6, "correct_answer": "生意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月他的生意很高。", "explanation": "这里应该用〈收入〉。生意指买卖，不能用“高”来说它的多少；说收入多要用“收入”。"}, {"text": "我最喜欢的生意是读书。", "explanation": "这里应该用〈爱好〉。生意指买卖、经营活动，不指兴趣；说个人喜欢的事要用“爱好”。"}, {"text": "他们谈成了一条生意。", "explanation": "量词错误：“生意”不用“条”，量词应用“笔”或“桩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他父亲明天做过生意。", "corrected_sentence": "他父亲明天要做生意。", "error_description": "体的错误：“过”表示已经发生的经历，不能与“明天”这样的将来时间词一起用，应改为“要做生意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年谈成了一根大生意。", "corrected_sentence": "他去年谈成了一笔大生意。", "error_description": "量词错误：应说“一笔生意”，“根”用于细长的东西，不能用于生意。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
