INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用于办事的费用。", "primary_collocate": null, "pronunciation": "jīng fèi", "ipa": "tɕiŋ˥ fei˥˩", "syllable_count": 2, "sentences": [{"text": "办公室的经费要写清楚怎么用。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究所每年都有科研经费。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔经费只能用来修路。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部门要把经费用在最需要的地方。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责管理学校的教育经费。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请经费要先填一张表。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用这笔经费买了新机器。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议经费已经交给财务了。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家增加了农村学校的经费。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经费有限，大家要节约。", "target_word": "经费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔经费", "label": "量词"}, {"form": "科研经费", "label": "复合"}, {"form": "会议经费", "label": "复合"}], "register": "中性", "sense_fingerprint": "办事用的费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf72999-cc70-48ab-a55f-436b9cac05ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经费", "is_correct": true, "explanation": "“经费”指办事的费用，句子说的是这笔费用要写清楚怎么用。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能“写清楚怎么用”，句子说的是钱的用法。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，不能说“办公室的身高”。"}, {"text": "人数", "is_correct": false, "explanation": "语义：“人数”是人的数量，不能“写清楚怎么用”。"}], "explanations": {"经费": "“经费”指办事的费用，句子说的是这笔费用要写清楚怎么用。", "天气": "语义：“天气”不能“写清楚怎么用”，句子说的是钱的用法。", "身高": "搭配：“身高”只用于人或动物，不能说“办公室的身高”。", "人数": "语义：“人数”是人的数量，不能“写清楚怎么用”。"}, "sentence_index": 0, "correct_answer": "经费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的经费发展得很快。", "explanation": "这里应该用〈经济〉。“经费”指办事用的钱，不能说地区“发展得很快”。"}, {"text": "这台电脑的经费很高，我们没买。", "explanation": "这里应该用〈价格〉。“经费”指办事用的钱，不用来说东西的价钱。"}, {"text": "这位同事的经费很强，做事很快。", "explanation": "这里应该用〈能力〉。“经费”是钱，不能用来形容人的办事本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经费", "is_correct": true, "explanation": "“经费”指一笔用于办事的钱，这里是医院用来买机器的钱。"}, {"text": "人员", "is_correct": false, "explanation": "搭配：“这笔”只用于款项或财物，不能修饰“人员”。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“这笔”不能修饰“病人”，病人也不能用来买机器。"}, {"text": "医生", "is_correct": false, "explanation": "语义：“医生”是人，不能作买机器的钱，句子语义不通。"}], "explanations": {"经费": "“经费”指一笔用于办事的钱，这里是医院用来买机器的钱。", "人员": "搭配：“这笔”只用于款项或财物，不能修饰“人员”。", "病人": "搭配：“这笔”不能修饰“病人”，病人也不能用来买机器。", "医生": "语义：“医生”是人，不能作买机器的钱，句子语义不通。"}, "sentence_index": 6, "correct_answer": "经费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的经费很难，大家都没通过。", "explanation": "这里应该用〈难度〉。“难度”形容考试的难易，“经费”不能用来说难易。"}, {"text": "这场演出的经费很短，观众都没看够。", "explanation": "这里应该用〈时间〉。“经费”是钱，不能用来说演出时间的长短。"}, {"text": "这瓶经费很香，大家都很喜欢。", "explanation": "这里应该用〈香水〉。“经费”是钱，不能用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张经费必须按时用完。", "corrected_sentence": "这笔经费必须按时用完。", "error_description": "错误：“经费”是一笔款项，量词应用“笔”，不用“张”。正确：“这笔经费必须按时用完。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校用这笔的经费修了操场。", "corrected_sentence": "学校用这笔经费修了操场。", "error_description": "错误：指量词“这笔”与名词“经费”之间不能加“的”。正确：“学校用这笔经费修了操场。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
