INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "（粤语地区）指使用者。", "primary_collocate": null, "pronunciation": "yòng jiā", "ipa": "jʊŋ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这部相机的用家，大部分是年轻人。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香港的手机用家很多。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用家的意见，公司一定会听。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买之前，先看看其他用家怎么说。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是这个牌子的老用家了。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款电话的用家都说很耐用。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂商请用家试用新产品。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的用家到店里可以打八折。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用家反映，这个网站太慢了。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子产品的用家要小心看说明书。", "target_word": "用家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "方言", "sense_fingerprint": "粤语地区对产品使用者的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39432ac-a2b3-4cb2-a82d-341df50f8430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用家", "is_correct": true, "explanation": "用家指使用这部相机的人，填入后句意通顺。"}, {"text": "厂家", "is_correct": false, "explanation": "语义：厂家指生产方，不是使用这部相机的人，与“大部分是年轻人”不符。"}, {"text": "镜头", "is_correct": false, "explanation": "搭配：镜头是物品，不能说“大部分是年轻人”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格不是人，不能与“大部分是年轻人”搭配。"}], "explanations": {"用家": "用家指使用这部相机的人，填入后句意通顺。", "厂家": "语义：厂家指生产方，不是使用这部相机的人，与“大部分是年轻人”不符。", "镜头": "搭配：镜头是物品，不能说“大部分是年轻人”。", "价格": "搭配：价格不是人，不能与“大部分是年轻人”搭配。"}, "sentence_index": 0, "correct_answer": "用家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用家把钱交给收银员。", "explanation": "这里应该用〈买家〉。用家指使用某产品的人，付钱买东西的是买家。"}, {"text": "用家负责招呼客人。", "explanation": "这里应该用〈服务员〉。招呼客人是服务员的工作，用家指使用产品的人，不负责接待顾客。"}, {"text": "这个用家的门很大，我们一起进去。", "explanation": "这里把〈用家〉误当成房屋，用家指使用产品的人，不指地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用家", "is_correct": true, "explanation": "用家指试用产品的人，填入后句意通顺。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不能被厂商请去试用产品，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不能试用新产品。"}, {"text": "仓库", "is_correct": false, "explanation": "搭配：“试用新产品”的对象应是能使用产品的人，“仓库”不能与之搭配。"}], "explanations": {"用家": "用家指试用产品的人，填入后句意通顺。", "老鼠": "语义：老鼠不能被厂商请去试用产品，句意不通。", "花园": "语义：花园是场所，不能试用新产品。", "仓库": "搭配：“试用新产品”的对象应是能使用产品的人，“仓库”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "用家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "用家在医院里给病人打针。", "explanation": "这里应该用〈护士〉。给病人打针的是护士，用家指使用某产品的人。"}, {"text": "用家负责把货物发出去。", "explanation": "这里应该用〈卖家〉。发货的是卖方，用家指使用产品的人。"}, {"text": "用家在工厂里组装手机。", "explanation": "这里应该用〈工人〉。组装手机是工人的工作，用家指使用产品的人，不在工厂里做生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一台用家，他说这个软件很好用。", "corrected_sentence": "我认识一个用家，他说这个软件很好用。", "error_description": "量词错误：用家指人，量词应用「个」或「位」，不能用「台」（「台」用于机器）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一台老用家说，这款打印机很省墨。", "corrected_sentence": "一位老用家说，这款打印机很省墨。", "error_description": "量词错误：用家指人，量词应用「位」，不能用「台」（「台」用于机器）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
