INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90841, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自若是说遇到事情也不慌，像平常一样。", "primary_collocate": null, "pronunciation": "zì ruò", "ipa": "tsz̩˥˩ ʐuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "遇到大雨，他仍然神色自若。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对记者的问题，她谈笑自若。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车突然停了，老人还是自若地看书。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时他神态自若，一点也不紧张。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碰到麻烦，哥哥总是镇定自若。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车突然坏了，他坐在车里，神情自若。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大家的目光，她自若地笑了。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了这么大的事，他还能自若地吃饭。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师遇事自若，学生也不慌。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在水里遇到危险，他依然自若。", "target_word": "自若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自若：遇事不慌，像平常一样镇定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自若", "is_correct": true, "explanation": "正确：“神色自若”是固定搭配，表示遇事镇定，不慌不乱。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”形容温度、触感，不能修饰神色。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等，不能修饰“神色”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材，不能用来形容神色。"}], "explanations": {"自若": "正确：“神色自若”是固定搭配，表示遇事镇定，不慌不乱。", "冰凉": "搭配：“冰凉”形容温度、触感，不能修饰神色。", "锋利": "搭配：“锋利”形容刀刃等，不能修饰“神色”。", "高大": "体貌：“高大”描写身材，不能用来形容神色。"}, "sentence_index": 0, "correct_answer": "自若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器操作起来很自若，一学就会。", "explanation": "这里应该用〈自如〉。自若形容遇事不慌的神态；操作熟练要用“自如”。"}, {"text": "这段时间我的时间很自若，可以慢慢逛街。", "explanation": "这里应该用〈从容〉。“从容”可指时间、经济宽裕；“自若”只形容人的神态。"}, {"text": "湖面很自若，没有一丝波澜。", "explanation": "这里应该用〈平静〉。“自若”形容人的神态，湖面等景物应说“平静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自若", "is_correct": true, "explanation": "正确：“自若地笑”表示面对众人神态镇定。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容质地，不能修饰笑的样子。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”修饰声音、语言等，不修饰笑。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容质地，不能修饰笑的样子。"}], "explanations": {"自若": "正确：“自若地笑”表示面对众人神态镇定。", "坚硬": "搭配：“坚硬”形容质地，不能修饰笑的样子。", "清晰": "搭配：“清晰”修饰声音、语言等，不修饰笑。", "粗糙": "搭配：“粗糙”形容质地，不能修饰笑的样子。"}, "sentence_index": 6, "correct_answer": "自若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿着很自若，像在家里一样。", "explanation": "这里应该用〈随意〉。“自若”形容遇事不慌的神态，不能形容穿着；穿着随便应说“随意”。"}, {"text": "这份报告的内容很自若。", "explanation": "这里应该用〈严谨〉。“自若”形容人的神态，报告内容应说“严谨”。"}, {"text": "这块蛋糕的味道很自若。", "explanation": "这里应该用〈香甜〉。“自若”形容人的神态，食物的味道应说“香甜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地震时，他仍然很神色自若。", "corrected_sentence": "地震时，他仍然神色自若。", "error_description": "错误形式：“很神色自若”，“很”修饰名词“神色”，搭配不通；正确形式：“神色自若”，“神色”是名词、“自若”是形容词，中间不加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在台上自若得演讲，没有一点紧张。", "corrected_sentence": "他在台上自若地演讲，没有一点紧张。", "error_description": "误用“得”：“得”用于动词后作补语，状语后应用“地”，应写“自若地演讲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
