INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90847, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "处在是说在某个地方或某种情况里。", "primary_collocate": null, "pronunciation": "chǔ zài", "ipa": "ʈʂʰu˨˩˦ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "这个村子处在两座山之间。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们现在处在很困难的时候。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂处在城市的东边。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处在一个很安静的环境里。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司现在处在发展的关键阶段。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城处在大海和森林中间。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她处在紧张的状态，睡不着觉。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家处在战争中。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家处在热闹的街道旁边。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人现在处在危险的情况中。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "處在", "label": "繁体"}], "register": "书面", "sense_fingerprint": "处在：身在某个地方或某种情况之中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "居住", "is_correct": false, "explanation": "语义：村子不能居住，“居住”要求主语是人或动物，与“村子”不合"}, {"text": "处在", "is_correct": true, "explanation": "正确。处在表示身处某个位置之中，与“两座山之间”的位置语境吻合"}, {"text": "哭", "is_correct": false, "explanation": "语义：村子不会哭，“哭”无法表示位置关系"}, {"text": "挤压", "is_correct": false, "explanation": "配价：“挤压”需要受事宾语，不能直接说“村子挤压在两座山之间”"}], "explanations": {"居住": "语义：村子不能居住，“居住”要求主语是人或动物，与“村子”不合", "处在": "正确。处在表示身处某个位置之中，与“两座山之间”的位置语境吻合", "哭": "语义：村子不会哭，“哭”无法表示位置关系", "挤压": "配价：“挤压”需要受事宾语，不能直接说“村子挤压在两座山之间”"}, "sentence_index": 0, "correct_answer": "处在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他处在休息。", "explanation": "这里应该用〈在〉。处在不能直接带动词作宾语，表示正在做某事应说“他在休息”。"}, {"text": "这个方法处在很好的效果。", "explanation": "这里应该用〈取得〉。处在说明所处的位置或状态，不能用来表示获得某种效果，应说“取得很好的效果”"}, {"text": "这件事处在昨天下午。", "explanation": "这里应该用〈发生〉。处在表示人或事物所处的状态或位置，不用来说明事情在某个时间出现"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“状态”作宾语，“吃紧张的状态”不成话"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“状态”作宾语，与“睡不着觉”的语境也不合"}, {"text": "使", "is_correct": false, "explanation": "配价：“使”后要接兼语或谓词性成分，不能直接跟“紧张的状态”这样的名词性成分"}, {"text": "处在", "is_correct": true, "explanation": "正确。处在表示身处某种状态之中，与“紧张的状态”相合"}], "explanations": {"吃": "搭配：“吃”不能带“状态”作宾语，“吃紧张的状态”不成话", "唱": "搭配：“唱”不能带“状态”作宾语，与“睡不着觉”的语境也不合", "使": "配价：“使”后要接兼语或谓词性成分，不能直接跟“紧张的状态”这样的名词性成分", "处在": "正确。处在表示身处某种状态之中，与“紧张的状态”相合"}, "sentence_index": 6, "correct_answer": "处在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这里处在三年。", "explanation": "这里应该用〈度过〉。处在表示身处某种状态或位置，不能用来计算经历的时长"}, {"text": "这个城市处在一百万人口。", "explanation": "这里应该用〈有〉。处在说明所处的位置或状态，不能用来说明人口数量"}, {"text": "这件事我们处在得很好。", "explanation": "这里应该用〈处理〉。处在表示所处的位置或状态，不能用来表示对事情进行安排解决，应说“处理得很好”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校处在给城市的北部。", "corrected_sentence": "这所学校处在城市的北部。", "error_description": "“处在”后不能接“给”，句中多了“给”，应去掉，说“这所学校处在城市的北部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块土地处在在河流的下游。", "corrected_sentence": "这块土地处在河流的下游。", "error_description": "“在”重复：“处在”后不应再接“在”，应去掉多余的“在”，说“这块土地处在河流的下游”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
