INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90848, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "位于，置身于某种地位或状态。", "primary_collocate": null, "pronunciation": "chǔ zài", "ipa": "ʈʂʰu˨˩˦ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "他处在领导的位置上，责任很大。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司处在行业的领先地位。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人处在需要别人帮助的境地中。", "target_word": "处在", "complexity_tier": "T3", "furigana": "lǎo rén chǔ zài xū yào bié rén bāng zhù de jìng dì zhōng", "sentence_source": "generated"}, {"text": "我们处在不利的位置，必须小心。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他处在两难的处境中。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队处在第一名的位置。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年人处在人生最重要的阶段。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她处在很高的地位，却很谦虚。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生处在学习的最好时期。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司处在竞争的压力下。", "target_word": "处在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "處在", "label": "繁体"}], "register": "书面", "sense_fingerprint": "处在：位于某种地位、位置或处境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发挥", "is_correct": false, "explanation": "搭配：“发挥”后接作用、才能等，不能带处所“领导的位置上”"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”不能表示身处某个职位或位置"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“责任很大”的语境不合，不能表示占据某个职位"}, {"text": "处在", "is_correct": true, "explanation": "正确。处在表示处于某个地位或位置，与“领导的位置上”相合"}], "explanations": {"发挥": "搭配：“发挥”后接作用、才能等，不能带处所“领导的位置上”", "哭": "语义：“哭”不能表示身处某个职位或位置", "唱": "语义：“唱”与“责任很大”的语境不合，不能表示占据某个职位", "处在": "正确。处在表示处于某个地位或位置，与“领导的位置上”相合"}, "sentence_index": 0, "correct_answer": "处在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她处在讲课。", "explanation": "这里应该用〈在〉。处在表示地位或处境，不能直接带动词短语表示正在做某事，应说“她在讲课”。"}, {"text": "这件事处在上周。", "explanation": "这里应该用〈发生〉。处在表示人或事物所处的地位或处境，不用来说明事情发生在某个时间"}, {"text": "他处在三碗饭。", "explanation": "这里应该用〈吃〉。处在表示所处的地位或状态，不能与“三碗饭”搭配表示进食，应说“吃了三碗饭”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：“穿”后接衣物，不能用来表示身处某个阶段"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”含丢弃之意，与“人生最重要的阶段”的语境相反"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语须是饮品，不能带“阶段”作宾语"}, {"text": "处在", "is_correct": true, "explanation": "正确。处在表示处于某个阶段之中，与“人生最重要的阶段”相合"}], "explanations": {"穿": "搭配：“穿”后接衣物，不能用来表示身处某个阶段", "扔": "语义：“扔”含丢弃之意，与“人生最重要的阶段”的语境相反", "喝": "搭配：“喝”的宾语须是饮品，不能带“阶段”作宾语", "处在": "正确。处在表示处于某个阶段之中，与“人生最重要的阶段”相合"}, "sentence_index": 6, "correct_answer": "处在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上处在一杯牛奶。", "explanation": "这里应该用〈喝〉。处在表示所处的位置或处境，不能带“一杯牛奶”表示饮用，应说“喝一杯牛奶”"}, {"text": "这个班级处在四十名学生。", "explanation": "这里应该用〈有〉。处在说明所处的位置或状态，不能用来说明人数"}, {"text": "这个学生处在好成绩。", "explanation": "这里应该用〈取得〉。处在说明所处的地位或状态，不能与“好成绩”搭配表示获得，应说“取得好成绩”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个品牌处在被市场的前列。", "corrected_sentence": "这个品牌处在市场的前列。", "error_description": "“处在”后不能接“被”，“被”字结构不成立，应去掉“被”，说“这个品牌处在市场的前列”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
