INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90851, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皮肤比较白的一类人。", "primary_collocate": null, "pronunciation": "bái rén", "ipa": "pai˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "街上有一位白人，他在问路。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个白人说的中文很好。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的邻居是一位白人老先生。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家咖啡店里坐着一位白人女孩，她在看书。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个白人小孩的头发是金色的。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是白人，不过会说一口流利的汉语。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里坐着一个白人学生。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳很大，那个白人的脸晒得通红。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个白人男孩正在学写汉字。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店门口站着几个白人游客。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "日常指皮肤较白的人，如邻居、游客、学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白人", "is_correct": true, "explanation": "正确：“一位白人”指一个人，后文“他在问路”也说得通。"}, {"text": "女士", "is_correct": false, "explanation": "语义：“女士”指女性，后文的“他”是男性，两者无法指同一人。"}, {"text": "孕妇", "is_correct": false, "explanation": "语义：“孕妇”指怀孕的女性，与后文的“他”不能指同一人。"}, {"text": "老太太", "is_correct": false, "explanation": "语义：“老太太”指女性，后文的“他”是男性，两者无法指同一人。"}], "explanations": {"白人": "正确：“一位白人”指一个人，后文“他在问路”也说得通。", "女士": "语义：“女士”指女性，后文的“他”是男性，两者无法指同一人。", "孕妇": "语义：“孕妇”指怀孕的女性，与后文的“他”不能指同一人。", "老太太": "语义：“老太太”指女性，后文的“他”是男性，两者无法指同一人。"}, "sentence_index": 0, "correct_answer": "白人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在车站看到一只白人。", "explanation": "量词用错了。“只”用于动物，指人应该用“位”或“个”，这里应该用〈个〉。"}, {"text": "街角站着一件白人，他在等车。", "explanation": "量词用错了。“件”用于物品、衣服等，不能用来数人，这里应该用〈位〉或〈个〉。"}, {"text": "他拿的是白人护照，所以出入境很方便。", "explanation": "这里应该用〈外国〉。白人指人种，不指国籍；护照表示国籍，要说“外国护照”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白人", "is_correct": true, "explanation": "正确：“一个白人学生”指皮肤较白的学生，句子通顺。"}, {"text": "教授", "is_correct": false, "explanation": "语义：“教授”是教师职称，不能同时是“学生”。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：“园丁”指照料花草的人，与“学生”的身份不符。"}, {"text": "老板", "is_correct": false, "explanation": "搭配：“老板学生”不是常用说法，“老板”不宜作“学生”的身份修饰语。"}], "explanations": {"白人": "正确：“一个白人学生”指皮肤较白的学生，句子通顺。", "教授": "语义：“教授”是教师职称，不能同时是“学生”。", "园丁": "语义：“园丁”指照料花草的人，与“学生”的身份不符。", "老板": "搭配：“老板学生”不是常用说法，“老板”不宜作“学生”的身份修饰语。"}, "sentence_index": 6, "correct_answer": "白人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在街上遇到一条白人，吓了一跳。", "explanation": "量词用错了。“条”多用于狗、蛇、河流等，指人应该用〈个〉或〈位〉。"}, {"text": "我们班来了一张白人新同学。", "explanation": "量词用错了。“张”用于纸、桌子、脸等扁平的事物，指人应该用〈位〉或〈个〉。"}, {"text": "路边坐着一棵白人，正在晒太阳。", "explanation": "量词用错了。“棵”用于树木、植物，指人应该用〈位〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只白人是从美国来的。", "corrected_sentence": "那位白人是从美国来的。", "error_description": "错误在量词：白人指人，量词要用“位”或“个”，“只”只用于动物。正确说法是：那位白人是从美国来的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个很白人老师教得好。", "corrected_sentence": "那个白人老师教得好。", "error_description": "错误在程度副词：“白人”是名词，不能被“很”修饰，“很”应删去。正确说法是：那个白人老师教得好。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
