INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皮肤浅色的人种。", "primary_collocate": null, "pronunciation": "bái rén", "ipa": "pai˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家的白人占百分之六十。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这次调查中，白人和黑人的比例相差很大。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究白人和黄种人的差别。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白人是一种人种，不是国籍。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里的白人越来越少。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，白人曾经统治过这个地区。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在人种调查中写自己是白人。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区白人和黑人的收入不同。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白人、黄种人和黑人是常说的三大人种。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在这个小镇的大多数是白人。", "target_word": "白人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "作为人种分类，与黑人、黄种人并列，用于统计、调查、历史", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白人", "is_correct": true, "explanation": "正确：“白人”是人种类别，可以占人口的比例，句子通顺。"}, {"text": "首都", "is_correct": false, "explanation": "语义：“首都”是城市，不是人群，不能按比例占这个国家的人口。"}, {"text": "总统", "is_correct": false, "explanation": "语义：“总统”指一个人，不能占全国人口的百分之六十。"}, {"text": "娃娃", "is_correct": false, "explanation": "语义：“娃娃”指小孩，不是人种类别，不能占这个国家人口的百分之六十。"}], "explanations": {"白人": "正确：“白人”是人种类别，可以占人口的比例，句子通顺。", "首都": "语义：“首都”是城市，不是人群，不能按比例占这个国家的人口。", "总统": "语义：“总统”指一个人，不能占全国人口的百分之六十。", "娃娃": "语义：“娃娃”指小孩，不是人种类别，不能占这个国家人口的百分之六十。"}, "sentence_index": 0, "correct_answer": "白人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国有五十六个白人。", "explanation": "这里应该用〈民族〉。白人是人种分类，不是民族；中国的五十六个族群是按民族划分的。"}, {"text": "他拿着一本白人护照，很快就通过了海关。", "explanation": "这里应该用〈外国〉。白人指人种，不指国籍；护照表示国籍，要说“外国护照”。"}, {"text": "我昨天在医院门口看到一只白人。", "explanation": "量词用错了。“只”用于动物，指人应该用〈个〉或〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白人", "is_correct": true, "explanation": "正确：“写自己是白人”指人种类别，符合调查的内容。"}, {"text": "胖子", "is_correct": false, "explanation": "语义：调查的是人种，“胖子”不是人种类别，不能写在这里。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：“外星人”不属于人种分类，与“人种调查”的内容矛盾。"}, {"text": "老外", "is_correct": false, "explanation": "语义：“老外”指外国人，不是人种分类，不能写在人种调查里。"}], "explanations": {"白人": "正确：“写自己是白人”指人种类别，符合调查的内容。", "胖子": "语义：调查的是人种，“胖子”不是人种类别，不能写在这里。", "外星人": "语义：“外星人”不属于人种分类，与“人种调查”的内容矛盾。", "老外": "语义：“老外”指外国人，不是人种分类，不能写在人种调查里。"}, "sentence_index": 6, "correct_answer": "白人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在河边看见一块白人，吓了一跳。", "explanation": "量词用错了。“块”用于块状的东西，指人应该用〈个〉或〈位〉。"}, {"text": "我们学校来了一根白人，他是新老师。", "explanation": "量词用错了。“根”用于条状的东西，指人应该用〈位〉或〈个〉。"}, {"text": "墙角站着一颗白人，他在晒太阳。", "explanation": "量词用错了。“颗”用于粒状的东西，指人应该用〈位〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小镇上住着一只白人，他是医生。", "corrected_sentence": "小镇上住着一位白人，他是医生。", "error_description": "错误在量词：白人指人，量词要用“位”或“个”，“只”只用于动物。正确说法是：小镇上住着一位白人，他是医生。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区的很白人收入比较高。", "corrected_sentence": "这个地区的白人收入比较高。", "error_description": "错误在程度副词：“白人”作定语时不能被“很”修饰，“很”应删去。正确说法是：这个地区的白人收入比较高。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
