INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90853, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "处决是依法对判了死刑的人执行死刑。", "primary_collocate": null, "pronunciation": "chǔ jué", "ipa": "tʂʰu˨˩ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "法院判了死刑，三天后就处决他。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家昨天依法处决了那名罪犯。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院决定明天处决这个杀人犯。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代皇帝常常下令处决大臣。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府依法处决了三名毒贩。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他杀了很多人，法院决定处决他。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家已经很多年没有处决过犯人了。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "什么时候处决他，还没有决定。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时，军队处决了那个间谍。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判了他死刑，下周处决。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处决了", "label": "完成体"}, {"form": "处决过", "label": "经历体"}, {"form": "處決", "label": "繁体"}], "register": "正式", "sense_fingerprint": "依法对死刑犯执行死刑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "处决", "is_correct": true, "explanation": "正确。依法对判了死刑的人执行死刑，与“判了死刑”前后衔接。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”表示不追究过错，与“判了死刑”的结果相反。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与判处死刑的语境完全矛盾。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”是不及物动词，不能直接带“他”作宾语，应说“向他微笑”。"}], "explanations": {"处决": "正确。依法对判了死刑的人执行死刑，与“判了死刑”前后衔接。", "原谅": "语义：“原谅”表示不追究过错，与“判了死刑”的结果相反。", "表扬": "语义：“表扬”是称赞，与判处死刑的语境完全矛盾。", "微笑": "配价：“微笑”是不及物动词，不能直接带“他”作宾语，应说“向他微笑”。"}, "sentence_index": 0, "correct_answer": "处决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校处决了打架的学生。", "explanation": "这里应该用〈处罚〉。“处决”专指依法对判了死刑的人执行死刑，学生打架应受处罚。"}, {"text": "他处决了家里的那只老鼠。", "explanation": "这里应该用〈打死〉。“打死”指用力击打致死，“处决”只能用于依法执行死刑的人，不能用于老鼠。"}, {"text": "他负责处决公司的合同。", "explanation": "这里应该用〈处理〉。“处决”只用于执行死刑，处理合同要用“处理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处决", "is_correct": true, "explanation": "正确。“处决过犯人”指国家曾依法执行死刑，与“很多年没有”的语境相符。"}, {"text": "废除", "is_correct": false, "explanation": "搭配：“废除”的对象是制度、法律，不能说“废除犯人”。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：“哭泣”是不及物动词，不能带“犯人”作宾语。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎接、接纳，与“没有……犯人”的语境不符。"}], "explanations": {"处决": "正确。“处决过犯人”指国家曾依法执行死刑，与“很多年没有”的语境相符。", "废除": "搭配：“废除”的对象是制度、法律，不能说“废除犯人”。", "哭泣": "配价：“哭泣”是不及物动词，不能带“犯人”作宾语。", "欢迎": "语义：“欢迎”表示迎接、接纳，与“没有……犯人”的语境不符。"}, "sentence_index": 6, "correct_answer": "处决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题下周处决。", "explanation": "这里应该用〈解决〉。“处决”专指执行死刑，处理问题要用“解决”。"}, {"text": "妈妈处决了桌上的剩菜。", "explanation": "这里应该用〈吃完〉。“处决”专指依法执行死刑，不能用于饭菜。"}, {"text": "这把刀处决了那个人。", "explanation": "“处决”的主体必须是依法有权执行的机关或人员，刀不能执行，这里应该用〈杀〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院已经判决下周处决了那名杀人犯。", "corrected_sentence": "法院已经判决下周处决那名杀人犯。", "error_description": "“了”表示动作已经完成，而“下周”指将来，二者矛盾。应去掉“处决”后的“了”，改为“下周处决那名杀人犯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当地法院昨天处决着那个逃犯。", "corrected_sentence": "当地法院昨天处决了那个逃犯。", "error_description": "“着”表示动作持续，而“处决”是一次性完成的动作，且“昨天”指已完成的事。应把“着”改为完成体“了”，即“处决了那个逃犯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
