INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90854, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "执行死刑。", "primary_collocate": null, "pronunciation": "chǔ jué", "ipa": "tʂʰu˨˩ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "今天早上，监狱处决了一名罪犯。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王下令处决那个叛徒。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，一周后处决这个犯人。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家不再处决犯人了。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，新政府处决了很多旧官员。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，他们要处决一个无辜的人。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把犯人带到院子里处决。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院已经批准处决那名毒枭。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，这位将军处决过上百个俘虏。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让大家害怕，他处决了几个人。", "target_word": "处决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处决了", "label": "完成体"}, {"form": "处决过", "label": "经历体"}, {"form": "處決", "label": "繁体"}], "register": "正式", "sense_fingerprint": "执行死刑，杀死犯人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "处决", "is_correct": true, "explanation": "正确。监狱依法对罪犯执行死刑，与“今天早上”的事件相符。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：“歌唱”是用歌声赞美，不能以“罪犯”为对象，与监狱执行死刑不符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“罪犯”作宾语。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”表示祝愿，与监狱对罪犯执行死刑的行为不符。"}], "explanations": {"处决": "正确。监狱依法对罪犯执行死刑，与“今天早上”的事件相符。", "歌唱": "语义：“歌唱”是用歌声赞美，不能以“罪犯”为对象，与监狱执行死刑不符。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“罪犯”作宾语。", "祝福": "语义：“祝福”表示祝愿，与监狱对罪犯执行死刑的行为不符。"}, "sentence_index": 0, "correct_answer": "处决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人处决了这批废弃的电池。", "explanation": "这里应该用〈回收〉。“回收”指把废旧物品收集起来再利用，“处决”只能用于依法执行死刑，不能用于废弃电池。"}, {"text": "这个孩子处决了他的玩具熊。", "explanation": "这里应该用〈扔掉〉。“扔掉”指丢弃不需要的东西，“处决”只能用于依法执行死刑的人，不能用于玩具。"}, {"text": "他们很快就处决了这场争论。", "explanation": "这里应该用〈解决〉。“解决”指消除问题或争议，“处决”指依法执行死刑，不能用于争论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处决", "is_correct": true, "explanation": "正确。“带到院子里处决”表示依法执行死刑，与前文的押送情景相符。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：“欢呼”表示高兴地呼喊，与押送犯人到院子里的情景不符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人生下来，不能用于被押送到院子里的犯人。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”需要说明对象和事由，这里没有宾语，语义不完整。"}], "explanations": {"处决": "正确。“带到院子里处决”表示依法执行死刑，与前文的押送情景相符。", "欢呼": "语义：“欢呼”表示高兴地呼喊，与押送犯人到院子里的情景不符。", "出生": "语义：“出生”指人生下来，不能用于被押送到院子里的犯人。", "祝贺": "配价：“祝贺”需要说明对象和事由，这里没有宾语，语义不完整。"}, "sentence_index": 6, "correct_answer": "处决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生在医院里处决了几个病人。", "explanation": "这里应该用〈救〉。“处决”是依法执行死刑，医生救治病人要用“救”。"}, {"text": "这只狗处决了几个人。", "explanation": "“处决”的主体必须是依法有权执行的机关或人员，狗不能执行，这里应该用〈咬伤〉。"}, {"text": "他把旧衣服都处决了。", "explanation": "这里应该用〈处理〉。“处决”专指执行死刑，处置旧物要用“处理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们处决得那名罪犯。", "corrected_sentence": "他们处决了那名罪犯。", "error_description": "“得”后面需要补语，而这里没有补语。应把“得”改为完成体“了”，即“处决了那名罪犯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们下周处决了那名罪犯。", "corrected_sentence": "他们下周处决那名罪犯。", "error_description": "“了”表示动作已经完成，而“下周”指将来，二者矛盾。应去掉“处决”后的“了”，改为“下周处决那名罪犯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
