INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我国省级行政区之一，由少数民族聚居地区设立，享有自治权。", "primary_collocate": null, "pronunciation": "zì zhì qū", "ipa": "tsz̩˥˩ ʈʂz̩˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "中国有五个自治区。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广西壮族自治区的首府是南宁。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内蒙古自治区在中国北方。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西藏自治区有很高的山。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宁夏回族自治区在中国西北部。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自治区和省一样，都是省级行政区。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新疆维吾尔自治区的面积很大。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自治区政府帮助当地人发展经济。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自治区的主席通常由当地少数民族的人担任。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这五个自治区都有自己的自治权。", "target_word": "自治区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自治區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "我国省级行政区，由少数民族聚居地区设立，享有自治权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自治区", "is_correct": true, "explanation": "正确：“中国有五个自治区”是说中国的省级行政区，说得通。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”是时间，不是可以数的地区，“中国有五个明天”说不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不是地区，“中国有五个星期”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的体形，不能用来数国家的地区。"}], "explanations": {"自治区": "正确：“中国有五个自治区”是说中国的省级行政区，说得通。", "明天": "语义：“明天”是时间，不是可以数的地区，“中国有五个明天”说不通。", "星期": "语义：“星期”是时间单位，不是地区，“中国有五个星期”说不通。", "身高": "体貌：“身高”指人的体形，不能用来数国家的地区。"}, "sentence_index": 0, "correct_answer": "自治区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "云南自治区有很多少数民族。", "explanation": "这里应该用〈省〉。云南是省，不是自治区；说云南要用“省”。"}, {"text": "香港是自治区，有自己的货币。", "explanation": "这里应该用〈特别行政区〉。香港属于特别行政区，不是自治区。"}, {"text": "西藏是一座自治区，有很多高山。", "explanation": "量词错误：自治区用“个”，“座”多用于山、桥、建筑，不能用于自治区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自治区", "is_correct": true, "explanation": "正确：“新疆维吾尔自治区的面积很大”说得通。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”没有“面积”，“人口的面积很大”说不通。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”不占有面积，“季节的面积很大”说不通。"}, {"text": "人", "is_correct": false, "explanation": "配价：“面积”是地方的属性，不能属于“人”，“人的面积很大”说不通。"}], "explanations": {"自治区": "正确：“新疆维吾尔自治区的面积很大”说得通。", "人口": "语义：“人口”没有“面积”，“人口的面积很大”说不通。", "季节": "语义：“季节”不占有面积，“季节的面积很大”说不通。", "人": "配价：“面积”是地方的属性，不能属于“人”，“人的面积很大”说不通。"}, "sentence_index": 6, "correct_answer": "自治区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北京是自治区，人口很多。", "explanation": "这里应该用〈直辖市〉。北京是直辖市，不是自治区。"}, {"text": "这五条自治区都有自己的自治权。", "explanation": "量词错误：自治区用“个”，不能用“条”。"}, {"text": "吉林自治区在中国东北部。", "explanation": "这里应该用〈省〉。吉林是省，不是自治区；说吉林要用“吉林省”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学过中国的五只自治区。", "corrected_sentence": "我们学过中国的五个自治区。", "error_description": "量词错误：应说“五个自治区”，“只”多用于动物，不能用于自治区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几座自治区的经济发展得都很快。", "corrected_sentence": "这几个自治区的经济发展得都很快。", "error_description": "量词错误：应说“这几个自治区”，“座”多用于山、桥、建筑，不能用于自治区。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
