INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书里讲了天下各种各样的知识。", "primary_collocate": null, "pronunciation": "bǎi kē", "ipa": "pai˨˩˦ kʰɤ˥", "syllable_count": 2, "sentences": [{"text": "这本百科很厚，里面什么都有。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套百科一共有十本。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师借给我一本百科。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥送了我一本儿童百科。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本百科里有很多漂亮的图片。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上读一点百科。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在百科里找到了鲸鱼的资料。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一本动物百科。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本百科是我小时候读的书。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上放着一本旧百科。", "target_word": "百科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "百科全书", "label": "复合"}], "register": "书面", "sense_fingerprint": "讲各种知识的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c5d38-188c-4474-8f42-65925038992f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90857, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "百科", "is_correct": true, "explanation": "正确：“百科”指讲各种知识的书，与“很厚”“什么都有”相符。"}, {"text": "相册", "is_correct": false, "explanation": "语义：相册只收照片，与“里面什么都有”不符。"}, {"text": "字帖", "is_correct": false, "explanation": "语义：字帖只收字的范本，与“里面什么都有”不符。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照只是出国用的证件，里面只有个人信息，不能说“里面什么都有”。"}], "explanations": {"百科": "正确：“百科”指讲各种知识的书，与“很厚”“什么都有”相符。", "相册": "语义：相册只收照片，与“里面什么都有”不符。", "字帖": "语义：字帖只收字的范本，与“里面什么都有”不符。", "护照": "语义：护照只是出国用的证件，里面只有个人信息，不能说“里面什么都有”。"}, "sentence_index": 0, "correct_answer": "百科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本百科很感人，我哭了好几次。", "explanation": "这里应该用〈小说〉。“百科”是讲各类知识的书，不是叙述故事的作品，不能说“很感人”。"}, {"text": "我买了一只百科，送给了朋友。", "explanation": "这里的量词应该用〈本〉。〈只〉用于动物等，书要用〈本〉。"}, {"text": "我每天都把这本百科穿在身上。", "explanation": "这里应该用〈衣服〉。“百科”是书，不能穿在身上；穿在身上的要用〈衣服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "百科", "is_correct": true, "explanation": "正确：“百科”是可以查找资料的书，与“找到了鲸鱼的资料”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不存放资料，查找资料的地方应是书或网络等。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜放衣物，不是查找资料的地方。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“在……里找到资料”一般指书籍、档案等，“花园”不能与之搭配。"}], "explanations": {"百科": "正确：“百科”是可以查找资料的书，与“找到了鲸鱼的资料”相符。", "冰箱": "语义：冰箱不存放资料，查找资料的地方应是书或网络等。", "衣柜": "语义：衣柜放衣物，不是查找资料的地方。", "花园": "搭配：“在……里找到资料”一般指书籍、档案等，“花园”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "百科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上放着一把旧百科。", "explanation": "这里的量词应该用〈本〉。〈把〉用于有柄或可握的东西，书要用〈本〉。"}, {"text": "他饿了，就去翻百科找吃的。", "explanation": "这里应该用〈菜谱〉。“百科”讲的是各类知识，不是做菜的方法；找吃的要看〈菜谱〉。"}, {"text": "我在图书馆借了一张百科。", "explanation": "这里的量词应该用〈本〉。〈张〉用于纸张、桌子等扁平物，书要用〈本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在书店买了一张百科。", "corrected_sentence": "我昨天在书店买了一本百科。", "error_description": "错误：书的量词用了“张”。正确：书应该用量词“本”，“张”用于纸张、桌子等扁平物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这本百科借了给同学。", "corrected_sentence": "我把这本百科借给了同学。", "error_description": "错误：“了”放错了位置，写成了“借了给”。正确：“借给”是一个词，“了”应放在“借给”之后，说“借给了同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90859, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
