INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行书是一种写起来比较快、字连在一起的字体。", "primary_collocate": null, "pronunciation": "xíng shū", "ipa": "ɕiŋ˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "写行书比写楷书快。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行书的字常常连在一起。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他签名时爱用行书，写得很快。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记笔记时，我常写行书，不写楷书。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行书不像楷书那样一笔一画地写。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信是用行书写的。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想写得快一点，就用行书吧。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行书的笔画连着，看起来很流畅。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的行书又快又好看。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写便条时，他习惯用行书。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写得较快、笔画连带的字体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90859, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：写得较快、笔画连带的字体。"}, {"text": "情书", "is_correct": false, "explanation": "qíng（第二声）与 xíng（第二声）声母不同（q 与 x），意思是写给恋人的信。"}, {"text": "行数", "is_correct": false, "explanation": "第二音节 shù（第四声）与 shū（第一声）只差声调，意思是行的数目。"}, {"text": "闲书", "is_correct": false, "explanation": "xián（第二声）与 xíng（第二声）韵尾不同（n 与 ng），意思是课外随便看的书。"}], "explanations": {"行书": "行书：写得较快、笔画连带的字体。", "情书": "qíng（第二声）与 xíng（第二声）声母不同（q 与 x），意思是写给恋人的信。", "行数": "第二音节 shù（第四声）与 shū（第一声）只差声调，意思是行的数目。", "闲书": "xián（第二声）与 xíng（第二声）韵尾不同（n 与 ng），意思是课外随便看的书。"}, "sentence_index": null, "correct_answer": "行书"}, "level_3": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：写得较快的字体，与“写……比写楷书快”相合。"}, {"text": "篆书", "is_correct": false, "explanation": "语义：篆书是更古老、更费时的字体，写篆书并不比写楷书快。"}, {"text": "印章", "is_correct": false, "explanation": "搭配：“写”的对象应是字体，不能说写印章。"}, {"text": "毛笔", "is_correct": false, "explanation": "搭配：“写”的对象应是字体，毛笔是工具，不能说写毛笔。"}], "explanations": {"行书": "行书：写得较快的字体，与“写……比写楷书快”相合。", "篆书": "语义：篆书是更古老、更费时的字体，写篆书并不比写楷书快。", "印章": "搭配：“写”的对象应是字体，不能说写印章。", "毛笔": "搭配：“写”的对象应是字体，毛笔是工具，不能说写毛笔。"}, "sentence_index": 0, "correct_answer": "行书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "行书要一笔一画地写，才能写得整齐。", "explanation": "这里应该用〈楷书〉。楷书一笔一画地写，才端正整齐；行书笔画相连、写得较快，不能说一笔一画地写。"}, {"text": "行书的字一个一个分开，写得很慢。", "explanation": "这里应该用〈楷书〉。楷书笔画分开、写得较慢；行书写得较快、字常连在一起。"}, {"text": "他找来一把行书，开始切菜。", "explanation": "这里应该用〈菜刀〉。切菜要用刀具，行书是字体，不能用来切菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90859, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：写得较快、笔画连带的字体。"}, {"text": "行使", "is_correct": false, "explanation": "第二音节 shǐ（第三声）与 shū（第一声）只差声调，意思是运用（权力等）。"}, {"text": "形势", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是事情发展的局面。"}, {"text": "刑事", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是与刑法、犯罪有关的。"}], "explanations": {"行书": "行书：写得较快、笔画连带的字体。", "行使": "第二音节 shǐ（第三声）与 shū（第一声）只差声调，意思是运用（权力等）。", "形势": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是事情发展的局面。", "刑事": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是与刑法、犯罪有关的。"}, "sentence_index": null, "correct_answer": "行书"}, "level_3": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：写得较快的字体，与“要想写得快一点”相合。"}, {"text": "楷书", "is_correct": false, "explanation": "语义：楷书一笔一画，写得慢，与“要想写得快一点”矛盾。"}, {"text": "墨汁", "is_correct": false, "explanation": "语义：墨汁是写字用的材料，不是字体，不能用来写得快。"}, {"text": "碑帖", "is_correct": false, "explanation": "搭配：“用”的对象应是书写的字体，碑帖是供临摹的字帖拓本，不能这样用。"}], "explanations": {"行书": "行书：写得较快的字体，与“要想写得快一点”相合。", "楷书": "语义：楷书一笔一画，写得慢，与“要想写得快一点”矛盾。", "墨汁": "语义：墨汁是写字用的材料，不是字体，不能用来写得快。", "碑帖": "搭配：“用”的对象应是书写的字体，碑帖是供临摹的字帖拓本，不能这样用。"}, "sentence_index": 6, "correct_answer": "行书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "写便条时，他习惯用行书，一笔一画地写。", "explanation": "这里应该用〈楷书〉。楷书一笔一画地写；行书笔画相连、写得较快，不能说一笔一画地写。"}, {"text": "我把行书倒进砚台里，准备写字。", "explanation": "这里应该用〈墨汁〉。墨汁是倒进砚台的液体；行书是一种字体，不能倒。"}, {"text": "行书的笔画都是分开的，每个字都很独立。", "explanation": "这里应该用〈楷书〉。楷书笔画分开、每字独立；行书笔画相连、字常连在一起，不能说笔画都是分开的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写了一只漂亮的行书。", "corrected_sentence": "他写了一手漂亮的行书。", "error_description": "错误：“只”用于动物等，不能用来数字迹；书写风格或字迹要用量词“手”，如“一手好字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈的行书写又快又好。", "corrected_sentence": "妈妈的行书写得又快又好。", "error_description": "错误：动词“写”后面带描述性补语时要用“得”，应写作“写得又快又好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
