INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "汉字书体之一，介于楷书和草书之间。", "primary_collocate": null, "pronunciation": "xíng shū", "ipa": "ɕiŋ˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "行书介于楷书和草书之间。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楷书很工整，行书比较自然。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王羲之的行书非常有名。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了三年行书。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "《兰亭序》是一幅有名的行书作品。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢用毛笔写行书。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草书很难认，行书比较好认。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅行书写得很漂亮。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么写行书。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一门行书课。", "target_word": "行书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "汉字书体名称，介于楷书与草书之间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：汉字书体之一，介于楷书和草书之间。"}, {"text": "情书", "is_correct": false, "explanation": "qíng（第二声）与 xíng（第二声）声母不同（q 与 x），意思是写给恋人的信。"}, {"text": "行数", "is_correct": false, "explanation": "第二音节 shù（第四声）与 shū（第一声）只差声调，意思是行的数目。"}, {"text": "闲书", "is_correct": false, "explanation": "xián（第二声）与 xíng（第二声）韵尾不同（n 与 ng），意思是课外随便看的书。"}], "explanations": {"行书": "行书：汉字书体之一，介于楷书和草书之间。", "情书": "qíng（第二声）与 xíng（第二声）声母不同（q 与 x），意思是写给恋人的信。", "行数": "第二音节 shù（第四声）与 shū（第一声）只差声调，意思是行的数目。", "闲书": "xián（第二声）与 xíng（第二声）韵尾不同（n 与 ng），意思是课外随便看的书。"}, "sentence_index": null, "correct_answer": "行书"}, "level_3": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：书体名，楷书与草书之间的字体，与“介于……之间”相合。"}, {"text": "篆书", "is_correct": false, "explanation": "语义：篆书是更古老的字体，不处在楷书和草书之间。"}, {"text": "毛笔", "is_correct": false, "explanation": "搭配：“介于……之间”说的是书体的位置，毛笔是工具，不能与楷书、草书并列比较。"}, {"text": "印章", "is_correct": false, "explanation": "语义：印章是刻制的印具，不是书体，不可能介于楷书和草书之间。"}], "explanations": {"行书": "行书：书体名，楷书与草书之间的字体，与“介于……之间”相合。", "篆书": "语义：篆书是更古老的字体，不处在楷书和草书之间。", "毛笔": "搭配：“介于……之间”说的是书体的位置，毛笔是工具，不能与楷书、草书并列比较。", "印章": "语义：印章是刻制的印具，不是书体，不可能介于楷书和草书之间。"}, "sentence_index": 0, "correct_answer": "行书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "行书比草书还难认，几乎没人看得懂。", "explanation": "这里应该用〈草书〉。草书最潦草难认；行书介于楷书和草书之间，比草书好认。"}, {"text": "行书的字一笔一画，很工整。", "explanation": "这里应该用〈楷书〉。楷书一笔一画、端正工整；行书笔画相连、写得较快，不能说一笔一画。"}, {"text": "他用行书削好了铅笔。", "explanation": "这里应该用〈小刀〉。削铅笔要用刀；行书是书体，不能用来削东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90860, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：汉字书体之一，介于楷书和草书之间。"}, {"text": "行使", "is_correct": false, "explanation": "第二音节 shǐ（第三声）与 shū（第一声）只差声调，意思是运用（权力等）。"}, {"text": "形势", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是事情发展的局面。"}, {"text": "行事", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是做事、办事。"}], "explanations": {"行书": "行书：汉字书体之一，介于楷书和草书之间。", "行使": "第二音节 shǐ（第三声）与 shū（第一声）只差声调，意思是运用（权力等）。", "形势": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是事情发展的局面。", "行事": "第二音节 shì（第四声）与 shū（第一声）韵母不同（i 与 u），意思是做事、办事。"}, "sentence_index": null, "correct_answer": "行书"}, "level_3": {"options": [{"text": "行书", "is_correct": true, "explanation": "行书：字体，比草书好认，与后半句“比较好认”相合。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“好认”说的是字迹，墨水不能用“好认”来形容。"}, {"text": "信纸", "is_correct": false, "explanation": "语义：信纸是写字的纸，不是字体，不能与草书比较好认与否。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是书写工具，不是字体，不能与草书比较好认与否。"}], "explanations": {"行书": "行书：字体，比草书好认，与后半句“比较好认”相合。", "墨水": "搭配：“好认”说的是字迹，墨水不能用“好认”来形容。", "信纸": "语义：信纸是写字的纸，不是字体，不能与草书比较好认与否。", "粉笔": "语义：粉笔是书写工具，不是字体，不能与草书比较好认与否。"}, "sentence_index": 6, "correct_answer": "行书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行书比楷书更工整，一笔一画都分开。", "explanation": "这里应该用〈楷书〉。楷书最工整、笔画分开；行书比楷书自然流畅，笔画常相连。"}, {"text": "学校开了一门行书课，老师教我们一笔一画地写。", "explanation": "这里应该用〈楷书〉。楷书一笔一画地写，端正工整；行书笔画相连，写得较快，不能说一笔一画地写。"}, {"text": "行书的字都很对称，像图画一样。", "explanation": "这里应该用〈篆书〉。篆书字形对称、像图画；行书字形灵活、笔画相连，不能说字都很对称、像图画一样。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家挂着一只行书。", "corrected_sentence": "我家挂着一幅行书。", "error_description": "错误：量词“只”用于动物等，书法作品应用量词“幅”，写作“一幅行书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的行书写很漂亮。", "corrected_sentence": "他的行书写得很漂亮。", "error_description": "错误：动词“写”后面带描述性补语时要用“得”，应写作“写得很漂亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
