INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事艺术创作或表演、有一定成就的人。", "primary_collocate": null, "pronunciation": "yì shù jiā", "ipa": "i˥˩ ʂu˥˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "这位艺术家的作品在国外很有名。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位著名的艺术家。", "target_word": "艺术家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "艺术家一辈子都在创作。", "target_word": "艺术家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位艺术家的音乐让很多人感动。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻的艺术家正在准备明天的表演。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位艺术家得过很多奖。", "target_word": "艺术家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术家需要很多时间来创作。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美术馆里有一位艺术家正在现场画画。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位艺术家的画我看了很多次。", "target_word": "艺术家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想做一个有名的艺术家，所以每天练习。", "target_word": "艺术家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "藝術家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "艺术家：从事艺术创作或表演、有一定成就的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4256b07-2d2b-4db1-830f-e6bafd30f388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "艺术家", "is_correct": true, "explanation": "正确：“这位”指人，“艺术家”能创作作品，与“的作品”搭配。"}, {"text": "公司", "is_correct": false, "explanation": "语义：“这位”要指人，“公司”不是人。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“作品”需要人创作，石头不能有作品。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“这位”要指人，“书包”不是人。"}], "explanations": {"艺术家": "正确：“这位”指人，“艺术家”能创作作品，与“的作品”搭配。", "公司": "语义：“这位”要指人，“公司”不是人。", "石头": "搭配：“作品”需要人创作，石头不能有作品。", "书包": "语义：“这位”要指人，“书包”不是人。"}, "sentence_index": 0, "correct_answer": "艺术家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只艺术家的音乐让很多人感动。", "explanation": "这里应该用〈位〉。〈只〉不用于人。"}, {"text": "这首艺术家让很多人感动。", "explanation": "这里〈艺术家〉指人，不能指一首歌，应说〈这首歌〉。"}, {"text": "这架艺术家的音乐让很多人感动。", "explanation": "这里应该用〈位〉。〈架〉用于飞机、钢琴等器械，不用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "艺术家", "is_correct": true, "explanation": "正确：“艺术家”是需要时间创作的人，可以作主语。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“创作”指做艺术作品，咖啡不能创作。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“创作”的主体应是人，“河水”不能进行创作。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“创作”需要有思维的主体，冰箱不能创作。"}], "explanations": {"艺术家": "正确：“艺术家”是需要时间创作的人，可以作主语。", "咖啡": "语义：“创作”指做艺术作品，咖啡不能创作。", "河水": "搭配：“创作”的主体应是人，“河水”不能进行创作。", "冰箱": "语义：“创作”需要有思维的主体，冰箱不能创作。"}, "sentence_index": 6, "correct_answer": "艺术家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想做一座有名的艺术家，所以每天练习。", "explanation": "这里应该用〈位〉或〈个〉。〈座〉用于山、楼等大型固定物，不能用来数人。"}, {"text": "他想成为一把有名的艺术家，所以每天练习。", "explanation": "这里应该用〈位〉。〈把〉用于有柄的器具，不能用来数人。"}, {"text": "他的新作品是一首很好听的艺术家。", "explanation": "这里〈艺术家〉指人，不能指歌曲，应说〈歌〉。〈首〉用于歌曲，但不能用〈艺术家〉来称呼歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗著名的艺术家明天来学校演讲。", "corrected_sentence": "这位著名的艺术家明天来学校演讲。", "error_description": "错误：指人的“艺术家”前用了量词“颗”，“颗”多用于小而圆的东西，应为“这位著名的艺术家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三位艺术家们参加了这次展览。", "corrected_sentence": "三位艺术家参加了这次展览。", "error_description": "错误：“艺术家们”与数量词“三位”同时使用，重复表示复数；应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
