INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "要点是一件事里最要紧的几点。", "primary_collocate": null, "pronunciation": "yào diǎn", "ipa": "jɑʊ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件事有三个要点，请你记住。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学游泳有几个要点，第一是不怕水。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要点一共四条，我都写在本子上。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做这道菜，要点是火不能太大。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车的要点是先要看清楚路。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说了学习的要点，大家都记下来了。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面试的三个要点，我已经准备好了。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把要点列在一张纸上。", "target_word": "要点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写信的要点是要把话说清楚。", "target_word": "要点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛有两个要点，不能忘。", "target_word": "要点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个要点", "label": "量词"}, {"form": "一条要点", "label": "量词"}], "register": "中性", "sense_fingerprint": "一件事里最要紧的几点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c25b5f-321c-4d4e-a8d4-6527f919495c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90863, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要点", "is_correct": true, "explanation": "要点：一件事里最要紧的几点，可以数，也可以记住。"}, {"text": "价格", "is_correct": false, "explanation": "语义：一件事没有“三个价格”这样的说法，“价格”与这里的语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体外形，不能用“三个”来计数一件事。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指人或动物的重量，一件事不能有“三个体重”。"}], "explanations": {"要点": "要点：一件事里最要紧的几点，可以数，也可以记住。", "价格": "语义：一件事没有“三个价格”这样的说法，“价格”与这里的语境不符。", "身高": "体貌：“身高”指人的身体外形，不能用“三个”来计数一件事。", "体重": "体貌：“体重”指人或动物的重量，一件事不能有“三个体重”。"}, "sentence_index": 0, "correct_answer": "要点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厂家对产品的要点很高，检查得很严格。", "explanation": "这里应该用〈要求〉。要点指重要内容，不能用“高”来形容；“对产品的要求很高”才是固定说法。"}, {"text": "他走路时不小心踩到了一个要点。", "explanation": "这句把“要点”当成了地上具体的小点。“要点”只指一件事里最要紧的内容，不能踩到。"}, {"text": "问题的要点很高，需要马上解决。", "explanation": "要点指一件事里最要紧的内容，不能用“高”来说明问题有多严重。应说“问题很严重，需要马上解决”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要点", "is_correct": true, "explanation": "要点：面试时需要准备的重要内容，与“准备好了”搭配。"}, {"text": "气味", "is_correct": false, "explanation": "语义：面试的内容没有气味，“面试的三个气味”不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：面试的准备内容没有颜色，“面试的三个颜色”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“三个”计数的是可以列出的内容，“脾气”不能这样数。"}], "explanations": {"要点": "要点：面试时需要准备的重要内容，与“准备好了”搭配。", "气味": "语义：面试的内容没有气味，“面试的三个气味”不成立。", "颜色": "语义：面试的准备内容没有颜色，“面试的三个颜色”说不通。", "脾气": "搭配：“三个”计数的是可以列出的内容，“脾气”不能这样数。"}, "sentence_index": 6, "correct_answer": "要点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "球员在比赛中拿下了两个要点。", "explanation": "这句说的是比赛中的得分，“要点”不指比赛中的分数。"}, {"text": "地板上洒了几个要点。", "explanation": "这句把“要点”当成了地上的具体小点，“要点”只指抽象的重要内容，不指具体的点。"}, {"text": "他把要点吃掉了。", "explanation": "这句把“要点”当成了可以吃的东西，“要点”不指食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他列出了三只要点。", "corrected_sentence": "他列出了三条要点。", "error_description": "量词错误：“要点”应用“条”或“个”，不能用“只”，应为“三条要点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把要点列了好。", "corrected_sentence": "我已经把要点列好了。", "error_description": "补语位置错误：“好”是动词“列”的补语，应紧接动词，应为“列好了”，不能说“列了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
