INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "为大家做好事，帮助很多人。", "primary_collocate": null, "pronunciation": "shè huì fú wù", "ipa": "ʂɤ˥˩ xweɪ˥˩ fu˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "周末我去医院做社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求学生每年做社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢做社会服务，帮助老人。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班去公园做了社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做社会服务让我很开心。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个月都去做一次社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生常常去村里做社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会服务可以帮助很多人。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸退休后常做社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想不想和我一起做社会服务？", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "社会服务活动", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人或团体做好事、帮助别人的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会服务", "is_correct": true, "explanation": "“周末我去医院做社会服务”：指去为大家做好事，去医院帮忙符合句意。"}, {"text": "生意", "is_correct": false, "explanation": "语义：“生意”是买卖经营，去医院不是做生意的地方，句子说不通。"}, {"text": "家务", "is_correct": false, "explanation": "语义：“家务”指家里的活，去医院探望或看病时不会“做家务”，句子不合理。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，“去医院做作业”指的不是为人帮忙的活动，句意不通。"}], "explanations": {"社会服务": "“周末我去医院做社会服务”：指去为大家做好事，去医院帮忙符合句意。", "生意": "语义：“生意”是买卖经营，去医院不是做生意的地方，句子说不通。", "家务": "语义：“家务”指家里的活，去医院探望或看病时不会“做家务”，句子不合理。", "作业": "语义：“作业”是学习任务，“去医院做作业”指的不是为人帮忙的活动，句意不通。"}, "sentence_index": 0, "correct_answer": "社会服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班去公园，在社会服务里吃了午饭。", "explanation": "“社会服务”是为大家做的好事，不是可以吃午饭的场所，这里把它当成了地方。"}, {"text": "我们班去公园，把社会服务刷成了红色。", "explanation": "“社会服务”是为大家做的好事，不是有颜色的物品，不能刷成红色，这里把它当成了东西。"}, {"text": "我们班的社会服务今天生病了。", "explanation": "“社会服务”是为大家做的好事，不是有身体的人，不能说“生病了”，这里把它当成了生命体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会服务", "is_correct": true, "explanation": "“大学生常常去村里做社会服务”：指大学生去村里帮助别人，句意完整。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生课后的练习，去村里做作业不是帮助别人的活动。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”是自己吃的一顿饭，“去村里做早饭”不是帮助大家的公益活动，与句意不符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”要说“领”或“发”，不与“做”搭配。"}], "explanations": {"社会服务": "“大学生常常去村里做社会服务”：指大学生去村里帮助别人，句意完整。", "作业": "语义：“作业”是学生课后的练习，去村里做作业不是帮助别人的活动。", "早饭": "语义：“早饭”是自己吃的一顿饭，“去村里做早饭”不是帮助大家的公益活动，与句意不符。", "工资": "搭配：“工资”要说“领”或“发”，不与“做”搭配。"}, "sentence_index": 6, "correct_answer": "社会服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台洗衣机正在做社会服务。", "explanation": "“社会服务”是人做的好事，洗衣机不能去做它，这个词不能用在无生命的物体上。"}, {"text": "我弟弟的社会服务比我高。", "explanation": "“社会服务”是抽象的，不是人，不能说“比我高”，这里把它当成了有身高的人。"}, {"text": "你想不想和我一起吃社会服务？", "explanation": "“社会服务”是为大家做的好事，不是可以吃的东西，这里把它当成了食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动社会服务，大家都很开心。", "corrected_sentence": "这次活动是社会服务，大家都很开心。", "error_description": "“是”漏掉：“这次活动”作主语，后面判断它属于社会服务要用“是”连接，应说“这次活动是社会服务”，不说“这次活动社会服务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班去年做了一条社会服务。", "corrected_sentence": "我们班去年做了一次社会服务。", "error_description": "量词错误：“社会服务”指一次活动，应用“次”计量，不能用“条”。正确的说法是“做了一次社会服务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
