INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "面向社会提供的公益或公共服务。", "primary_collocate": null, "pronunciation": "shè huì fú wù", "ipa": "ʂɤ˥˩ xweɪ˥˩ fu˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "这个城市的社会服务很好。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆提供免费的社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为老人提供社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司提供社会服务，不收钱。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区里的社会服务越来越多了。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会服务让生活更方便。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳馆对外开放是一项社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项社会服务对所有人免费。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市需要更多的社会服务。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在管理社会服务的部门工作。", "target_word": "社会服务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "社会服务活动", "label": "复合"}], "register": "中性", "sense_fingerprint": "面向公众提供的公益、公共服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会服务", "is_correct": true, "explanation": "“这个城市的社会服务很好”：指城市提供的公共服务质量好，句意完整。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”通常说“多”或“少”，不用“很好”来评价。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用来形容一个城市。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，城市没有年龄，不能用“很好”来评价。"}], "explanations": {"社会服务": "“这个城市的社会服务很好”：指城市提供的公共服务质量好，句意完整。", "人口": "搭配：“人口”通常说“多”或“少”，不用“很好”来评价。", "身高": "体貌：“身高”指人的高矮，不能用来形容一个城市。", "年龄": "语义：“年龄”是人的岁数，城市没有年龄，不能用“很好”来评价。"}, "sentence_index": 0, "correct_answer": "社会服务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司在社会服务里开会。", "explanation": "“社会服务”是抽象的服务，不是可以开会的场所，这里把它当成了地点。"}, {"text": "这家公司的社会服务在走路。", "explanation": "“社会服务”是抽象的服务，不是人或动物，不能说“在走路”，这里把它当成了会走路的生命体。"}, {"text": "这家公司把社会服务放在桌子上了。", "explanation": "“社会服务”是抽象的，不能像物品一样放在桌子上，这个词不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会服务", "is_correct": true, "explanation": "“游泳馆对外开放是一项社会服务”：指向公众开放的公共服务，句意完整。"}, {"text": "商品", "is_correct": false, "explanation": "语义：“商品”是用于买卖的东西，游泳馆对外开放不是商品，句子说不通。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“食物”用“种”或“份”计数，不能用“项”。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“衣服”用“件”计数，不能用“项”。"}], "explanations": {"社会服务": "“游泳馆对外开放是一项社会服务”：指向公众开放的公共服务，句意完整。", "商品": "语义：“商品”是用于买卖的东西，游泳馆对外开放不是商品，句子说不通。", "食物": "搭配：“食物”用“种”或“份”计数，不能用“项”。", "衣服": "搭配：“衣服”用“件”计数，不能用“项”。"}, "sentence_index": 6, "correct_answer": "社会服务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的社会服务比他爸爸还高。", "explanation": "“社会服务”是抽象的，不是人，不能说“比他爸爸还高”，这里把它当成了有身高的人。"}, {"text": "这家超市的社会服务今年十岁了。", "explanation": "“社会服务”是抽象的，不是人或动物，不能说“十岁了”，这里把它当成了有年龄的个体。"}, {"text": "我妈妈把社会服务炒了一下。", "explanation": "“社会服务”是提供给大家的公益服务，不是食材，不能用“炒”，这里把它当成了食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些免费讲座社会服务，大家都很需要。", "corrected_sentence": "这些免费讲座是社会服务，大家都很需要。", "error_description": "“是”漏掉：“这些免费讲座”作主语，后面判断它属于社会服务要用“是”连接，应说“这些免费讲座是社会服务”，不说“这些免费讲座社会服务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府新增了一件社会服务。", "corrected_sentence": "政府新增了一项社会服务。", "error_description": "量词错误：“社会服务”应用“项”，不用“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
