INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事诗歌创作的人。", "primary_collocate": null, "pronunciation": "shī rén", "ipa": "ʂz̩˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "李白是中国很有名的诗人。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人写过很多关于月亮的诗。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想做一个诗人。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位诗人一辈子都在写诗。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人的作品很多人都读过。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人在书里写了自己的故事。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的诗人是杜甫。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个诗人出生在南方的小城。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人常常看着窗外，慢慢想新的句子。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多诗人都爱写春天。", "target_word": "诗人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "詩人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从事诗歌创作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90868, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诗人", "is_correct": true, "explanation": "诗人（shī rén）指从事诗歌创作的人，是正确答案。"}, {"text": "世人", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是世上的人。"}, {"text": "私人", "is_correct": false, "explanation": "sī 与 shī 声母不同（s/sh），意思是个人的、非公共的。"}, {"text": "吃人", "is_correct": false, "explanation": "chī 与 shī 声母不同（ch/sh），意思是吃人。"}], "explanations": {"诗人": "诗人（shī rén）指从事诗歌创作的人，是正确答案。", "世人": "shì（第四声）与 shī（第一声）声调不同，意思是世上的人。", "私人": "sī 与 shī 声母不同（s/sh），意思是个人的、非公共的。", "吃人": "chī 与 shī 声母不同（ch/sh），意思是吃人。"}, "sentence_index": null, "correct_answer": "诗人"}, "level_3": {"options": [{"text": "诗人", "is_correct": true, "explanation": "诗人：李白是唐代著名的诗人，与句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：李白以写诗著称，不是厨师，句子说的是他的名气。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：李白以写诗闻名，并不是小偷，句子说的是他的诗名。"}, {"text": "医生", "is_correct": false, "explanation": "语义：李白是诗人，不是医生，句中“很有名”指的是他的诗作。"}], "explanations": {"诗人": "诗人：李白是唐代著名的诗人，与句意相符。", "厨师": "语义：李白以写诗著称，不是厨师，句子说的是他的名气。", "小偷": "语义：李白以写诗闻名，并不是小偷，句子说的是他的诗名。", "医生": "语义：李白是诗人，不是医生，句中“很有名”指的是他的诗作。"}, "sentence_index": 0, "correct_answer": "诗人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一首诗人。", "explanation": "这里应该用〈位〉。“首”用于诗歌，指人要用“位”或“个”。"}, {"text": "这位诗人一辈子只写小说，从没写过一句诗。", "explanation": "这里应该用〈作家〉。诗人指写诗的人，这句说他从不写诗，与词义矛盾。"}, {"text": "图书馆里放着一本诗人。", "explanation": "这里应该用〈位〉。“本”用于书籍，不能用来计量人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗人", "is_correct": true, "explanation": "诗人：杜甫是唐代的诗人，句意成立。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：杜甫是诗人，不是歌手。"}, {"text": "司机", "is_correct": false, "explanation": "语义：杜甫不是司机，句子说的是喜爱的人物身份。"}, {"text": "帅哥", "is_correct": false, "explanation": "体貌：“帅哥”评价的是外貌，句中没有外貌线索，也不能用来指杜甫这样的古代诗人。"}], "explanations": {"诗人": "诗人：杜甫是唐代的诗人，句意成立。", "歌手": "语义：杜甫是诗人，不是歌手。", "司机": "语义：杜甫不是司机，句子说的是喜爱的人物身份。", "帅哥": "体貌：“帅哥”评价的是外貌，句中没有外貌线索，也不能用来指杜甫这样的古代诗人。"}, "sentence_index": 6, "correct_answer": "诗人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家来了一张诗人。", "explanation": "这里应该用〈位〉。“张”用于纸、桌子等平面或扁平的东西，不用于人。"}, {"text": "我们村来了一头诗人。", "explanation": "这里应该用〈位〉。“头”用于牲畜，不用于人。"}, {"text": "门口立着一座诗人。", "explanation": "这里应该用〈位〉。“座”用于山、房屋等大型固定的东西，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天来了一只诗人，大家都很高兴。", "corrected_sentence": "昨天来了一位诗人，大家都很高兴。", "error_description": "量词错误：“只”多用于动物，不能用来计量人。“诗人”指人，用“个”或“位”都可以，应说“一位诗人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不诗人，只是喜欢写诗。", "corrected_sentence": "他不是诗人，只是喜欢写诗。", "error_description": "否定句中“是”不能省略，应说“他不是诗人”，不能说“他不诗人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
