INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90869, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "亲王是皇帝的亲兄弟或儿子，地位很高。", "primary_collocate": null, "pronunciation": "qīn wáng", "ipa": "tɕʰin˥ waŋ˧˥", "syllable_count": 2, "sentences": [{"text": "皇帝把亲弟弟封为亲王。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老皇帝有三个儿子，大儿子是亲王。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲王的地位比大官还高。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代，亲王可以住在大房子里。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝很爱他的哥哥，封他做亲王。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个亲王每天骑马去城外。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父亲是皇帝，所以他是亲王。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲王有很多人帮他做事。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的亲王不能随便离开京城。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多人羡慕亲王的地位与财富。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "亲王府", "label": "复合"}], "register": "书面语", "sense_fingerprint": "皇帝的兄弟或儿子，地位很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲王", "is_correct": true, "explanation": "正确。“亲王”是皇帝封的爵位，与“皇帝把亲弟弟封为___”相符。"}, {"text": "公主", "is_correct": false, "explanation": "语义：“公主”指女性皇族，不能用于男性的亲弟弟。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是职业，不是皇帝可以封的爵位。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“封为”的对象须是人或身份，不能用于房间。"}], "explanations": {"亲王": "正确。“亲王”是皇帝封的爵位，与“皇帝把亲弟弟封为___”相符。", "公主": "语义：“公主”指女性皇族，不能用于男性的亲弟弟。", "老师": "语义：“老师”是职业，不是皇帝可以封的爵位。", "房间": "搭配：“封为”的对象须是人或身份，不能用于房间。"}, "sentence_index": 0, "correct_answer": "亲王"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的亲王，我想你了。", "explanation": "这里应该用〈亲爱的〉。“亲王”是爵位名称，不用来称呼亲近的人，称呼亲人要用〈亲爱的〉。"}, {"text": "她是皇帝的妹妹，人们叫她亲王。", "explanation": "这里应该用〈公主〉。“亲王”是男性爵位，皇帝的妹妹要用〈公主〉。"}, {"text": "妈妈是一位亲王，每天在厨房做饭。", "explanation": "这里应该用〈厨师〉。“亲王”是封建爵位，不指做饭的职业，描述做饭要用〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲王", "is_correct": true, "explanation": "正确。“亲王”是由皇帝的身份带来的爵位，与“他的父亲是皇帝，所以他是___”相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”是种地的人，与“父亲是皇帝”的身份不相称，“所以他是农民”不合逻辑。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”指偷东西的人，与“父亲是皇帝”的身份矛盾，句子不合逻辑。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”不是身份，句子不通。"}], "explanations": {"亲王": "正确。“亲王”是由皇帝的身份带来的爵位，与“他的父亲是皇帝，所以他是___”相符。", "农民": "语义：“农民”是种地的人，与“父亲是皇帝”的身份不相称，“所以他是农民”不合逻辑。", "小偷": "语义：“小偷”指偷东西的人，与“父亲是皇帝”的身份矛盾，句子不合逻辑。", "饮料": "语义：“饮料”不是身份，句子不通。"}, "sentence_index": 6, "correct_answer": "亲王"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的亲王住在北京，每年春节都回来看我。", "explanation": "这里应该用〈亲戚〉。“亲王”是封建爵位，指皇室成员，不用来泛指亲戚，一般的亲戚要用〈亲戚〉。"}, {"text": "我哥哥是一位亲王，每天在学校修理电脑。", "explanation": "这里应该用〈维修员〉。“亲王”是爵位，不是职业，修理电脑的人要用〈维修员〉。"}, {"text": "她是皇帝的女儿，后来被封为亲王。", "explanation": "这里应该用〈公主〉。“亲王”是男性爵位，皇帝的女儿要用〈公主〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一座亲王在王府里读书。", "corrected_sentence": "一位亲王在王府里读书。", "error_description": "量词错误：“亲王”指人，量词应用“位”，不能用“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只亲王很喜欢音乐。", "corrected_sentence": "这位亲王很喜欢音乐。", "error_description": "量词错误：“亲王”指人，量词应用“位”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
