INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90870, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90870, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "封建时代皇帝的近亲被封的爵位最高者；也指某些国家君主家族的男性成员。", "primary_collocate": null, "pronunciation": "qīn wáng", "ipa": "tɕʰin˥ waŋ˧˥", "syllable_count": 2, "sentences": [{"text": "清朝的亲王是地位最高的贵族。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位亲王住在很大的王府里。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝封他的弟弟为亲王。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国的菲利普亲王是女王的丈夫。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的亲王来中国访问。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是皇帝的儿子，后来成了亲王。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲王的家人都穿着漂亮的衣服。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，那位亲王很喜欢读书。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲王每年都要去见皇帝。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上有一位外国亲王在说话。", "target_word": "亲王", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "亲王府", "label": "复合"}], "register": "书面语", "sense_fingerprint": "最高爵位；君主家族男性成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲王", "is_correct": true, "explanation": "正确。“亲王”是封建时代最高的爵位之一，与“地位最高的贵族”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指教书的人，不是爵位，“清朝的老师是地位最高的贵族”不成立。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“地位最高”说人或职位，不能用于房间。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”是可以喝的东西，与“贵族”无关。"}], "explanations": {"亲王": "正确。“亲王”是封建时代最高的爵位之一，与“地位最高的贵族”相符。", "老师": "语义：“老师”指教书的人，不是爵位，“清朝的老师是地位最高的贵族”不成立。", "房间": "搭配：“地位最高”说人或职位，不能用于房间。", "饮料": "语义：“饮料”是可以喝的东西，与“贵族”无关。"}, "sentence_index": 0, "correct_answer": "亲王"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的亲王，你回来了！", "explanation": "这里应该用〈亲爱的〉。“亲王”是爵位名称，不用来称呼亲近的人，称呼亲人要用〈亲爱的〉。"}, {"text": "她是国王的女儿，人们叫她亲王。", "explanation": "这里应该用〈公主〉。“亲王”是男性爵位，国王的女儿要用〈公主〉。"}, {"text": "我的爸爸是一位亲王，每天在公司工作。", "explanation": "这里应该用〈职员〉。“亲王”是封建爵位，不指职业，描述公司工作要用〈职员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲王", "is_correct": true, "explanation": "正确。“亲王”是爵位称号，指拥有此爵位的贵族，与“___的家人都穿着漂亮的衣服”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，没有家人，也不会穿衣服，句子不通。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“家人”与“穿着漂亮的衣服”都需要人作主语，“汽车”不能与之搭配。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”不是人，句子不通。"}], "explanations": {"亲王": "正确。“亲王”是爵位称号，指拥有此爵位的贵族，与“___的家人都穿着漂亮的衣服”相符。", "桌子": "语义：“桌子”是家具，没有家人，也不会穿衣服，句子不通。", "汽车": "搭配：“家人”与“穿着漂亮的衣服”都需要人作主语，“汽车”不能与之搭配。", "玩具": "语义：“玩具”不是人，句子不通。"}, "sentence_index": 6, "correct_answer": "亲王"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这个国家的亲王，经过选举产生。", "explanation": "这里应该用〈总统〉。“亲王”是世袭爵位，不经选举产生，经选举产生的要用〈总统〉。"}, {"text": "我的亲王在农村种地，每年春节都会回来看我。", "explanation": "这里应该用〈亲戚〉。“亲王”是封建爵位，指皇室成员，不用来泛指一般的亲戚，应说〈亲戚〉。"}, {"text": "他是我们学校的亲王，每天早上都讲话。", "explanation": "这里应该用〈校长〉。“亲王”是封建爵位，不用于学校的管理者，应说〈校长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一座亲王住在城外的王府里。", "corrected_sentence": "一位亲王住在城外的王府里。", "error_description": "量词错误：“亲王”指人，量词应用“位”，不能用“座”（“座”用于建筑等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只亲王很有钱。", "corrected_sentence": "那位亲王很有钱。", "error_description": "量词错误：“亲王”指人，量词应用“位”，不能用“只”（“只”多用于动物或成对事物中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
