INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "货车是专门拉东西的大车。", "primary_collocate": null, "pronunciation": "huò chē", "ipa": "xwo˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "货车是用来拉东西的车。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一辆货车。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家那天，我们租了一辆货车。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车很大，但坐不了很多人。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的货车装满了大米。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开货车拉了一天的煤。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车的车厢又大又长。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店门口来了一辆新货车。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车停在门口，叔叔在卸货。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上货车多，路上要小心。", "target_word": "货车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "小货车", "label": "复合"}, {"form": "大货车", "label": "复合"}, {"form": "货车司机", "label": "复合"}], "register": "中性", "sense_fingerprint": "专门拉东西的大车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90875, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "货车", "is_correct": true, "explanation": "正确答案。货车是专门拉东西的大车。"}, {"text": "火车", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火车，不是拉货的大车。"}, {"text": "候车", "is_correct": false, "explanation": "hòu 与 huò 韵母不同，意思是等车。"}, {"text": "会车", "is_correct": false, "explanation": "huì 与 huò 韵母不同，意思是两车相遇交会通过。"}], "explanations": {"货车": "正确答案。货车是专门拉东西的大车。", "火车": "huǒ（第三声）与 huò（第四声）声调不同，意思是火车，不是拉货的大车。", "候车": "hòu 与 huò 韵母不同，意思是等车。", "会车": "huì 与 huò 韵母不同，意思是两车相遇交会通过。"}, "sentence_index": null, "correct_answer": "货车"}, "level_3": {"options": [{"text": "货车", "is_correct": true, "explanation": "正确答案。货车是用来拉东西的车，句子说的正是它。"}, {"text": "公交车", "is_correct": false, "explanation": "搭配：“拉东西”与公交车不搭配，公交车用于载客。"}, {"text": "轿车", "is_correct": false, "explanation": "语义：轿车主要用来载人，不是拉东西的车。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是车，不能说它是“用来拉东西的车”。"}], "explanations": {"货车": "正确答案。货车是用来拉东西的车，句子说的正是它。", "公交车": "搭配：“拉东西”与公交车不搭配，公交车用于载客。", "轿车": "语义：轿车主要用来载人，不是拉东西的车。", "冰箱": "语义：冰箱不是车，不能说它是“用来拉东西的车”。"}, "sentence_index": 0, "correct_answer": "货车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天买一张货车票去上班。", "explanation": "这里应该用〈公交车〉。货车不载客，不卖票，上班应买公交车票。"}, {"text": "货车每天接送孩子上学。", "explanation": "这里应该用〈校车〉。货车运的是货物，不接送学生。"}, {"text": "货车的票价很便宜。", "explanation": "这里应该用〈公交车〉。货车不载客，不卖票，不说票价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90875, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "货车", "is_correct": true, "explanation": "正确答案。货车是专门拉东西的大车。"}, {"text": "火柴", "is_correct": false, "explanation": "huǒ chái：第一个字是第三声，不是第四声；第二个字是 chái，不是 chē。火柴是用来点火的小木棍。"}, {"text": "货船", "is_correct": false, "explanation": "huò chuán：第二个字是 chuán，不是 chē。货船是在水上运货的船，不是车。"}, {"text": "货仓", "is_correct": false, "explanation": "huò cāng：第二个字是 cāng，不是 chē。货仓是放货物的房子，不是车。"}], "explanations": {"货车": "正确答案。货车是专门拉东西的大车。", "火柴": "huǒ chái：第一个字是第三声，不是第四声；第二个字是 chái，不是 chē。火柴是用来点火的小木棍。", "货船": "huò chuán：第二个字是 chuán，不是 chē。货船是在水上运货的船，不是车。", "货仓": "huò cāng：第二个字是 cāng，不是 chē。货仓是放货物的房子，不是车。"}, "sentence_index": null, "correct_answer": "货车"}, "level_3": {"options": [{"text": "货车", "is_correct": true, "explanation": "正确答案。“车厢”属于车辆，货车的车厢又大又长。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发没有车厢，“沙发的车厢”说不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“车厢”只用于车辆，房间不说“车厢”。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌不是车，没有车厢。"}], "explanations": {"货车": "正确答案。“车厢”属于车辆，货车的车厢又大又长。", "沙发": "语义：沙发没有车厢，“沙发的车厢”说不通。", "房间": "搭配：“车厢”只用于车辆，房间不说“车厢”。", "书桌": "语义：书桌不是车，没有车厢。"}, "sentence_index": 6, "correct_answer": "货车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我坐货车去机场，再坐货车飞到北京。", "explanation": "这里应该用〈飞机〉。货车在路上跑，不能飞。"}, {"text": "妈妈把剩菜放进货车里，免得坏掉。", "explanation": "这里应该用〈冰箱〉。货车是拉东西的车，不是保存食物的电器。"}, {"text": "我们一家三口坐货车去旅游，车上有很多座位。", "explanation": "这里应该用〈大巴〉。货车是拉货的，不是给很多乘客坐的车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆货车每天拉五十位乘客去上班。", "corrected_sentence": "这辆公交车每天拉五十位乘客去上班。", "error_description": "用词错误：货车是拉货物的车，不载乘客，载乘客上班应该用“公交车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一座货车停在了门口。", "corrected_sentence": "一辆货车停在了门口。", "error_description": "量词错误：货车的量词是“辆”。“座”用于山、楼等大型固定物，不能用于车辆，应说“一辆货车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
