INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90879, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向法院提出诉讼，请求依法处理纠纷或追究责任。", "primary_collocate": null, "pronunciation": "qǐ sù", "ipa": "tɕʰi˨˩˦ su˥˩", "syllable_count": 2, "sentences": [{"text": "邻居吵得太厉害，我想起诉他。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骗了我的钱，我要起诉他。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友劝我别起诉，先谈一谈。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店卖假货，客人去法院起诉它。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有还钱，我只好起诉她。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们起诉过那个医生。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不给工资，工人决定起诉。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有证据，就可以起诉他。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报社写假新闻，有人起诉了它。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他撞坏了我的车，还不认错，我起诉他。", "target_word": "起诉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起诉了", "label": "体标"}, {"form": "起诉过", "label": "体标"}, {"form": "起诉书", "label": "复合"}], "register": "书面", "sense_fingerprint": "有人做错事请法院管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf72999-cc70-48ab-a55f-436b9cac05ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起诉", "is_correct": true, "explanation": "正确：起诉是向法院提出诉讼，适用于邻居吵闹这类可以依法处理的纠纷。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定对方的好表现，与“吵得太厉害”的情形相反。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：祝贺是为好事高兴，与邻居吵闹的情形不符。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所或展品，不能直接带“他”这样的人。"}], "explanations": {"起诉": "正确：起诉是向法院提出诉讼，适用于邻居吵闹这类可以依法处理的纠纷。", "表扬": "语义：表扬是肯定对方的好表现，与“吵得太厉害”的情形相反。", "祝贺": "语义：祝贺是为好事高兴，与邻居吵闹的情形不符。", "参观": "配价：“参观”的宾语是场所或展品，不能直接带“他”这样的人。"}, "sentence_index": 0, "correct_answer": "起诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "客人向工商局起诉它卖假货。", "explanation": "这里应该用〈投诉〉。向工商部门反映商家的问题应说投诉，起诉只能向法院提出。"}, {"text": "经理起诉了那个迟到的员工。", "explanation": "这里应该用〈训斥〉。起诉是向法院提起诉讼，经理对迟到员工的责备应说训斥。"}, {"text": "店员起诉了那个乱跑的孩子。", "explanation": "这里应该用〈责备〉。店员因孩子乱跑而说他，应说责备，起诉是法律行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起诉", "is_correct": true, "explanation": "正确：工人在劳资纠纷中决定起诉，指向法院提起诉讼，与“老板不给工资”相符。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝是为喜事高兴，与老板不给工资的处境矛盾。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：道歉通常由过错方提出，工人是利益受损的一方，句意不合。"}, {"text": "殉职", "is_correct": false, "explanation": "语义：殉职指因公牺牲，与工人因工资问题要采取的行动毫不相干。"}], "explanations": {"起诉": "正确：工人在劳资纠纷中决定起诉，指向法院提起诉讼，与“老板不给工资”相符。", "庆祝": "语义：庆祝是为喜事高兴，与老板不给工资的处境矛盾。", "道歉": "语义：道歉通常由过错方提出，工人是利益受损的一方，句意不合。", "殉职": "语义：殉职指因公牺牲，与工人因工资问题要采取的行动毫不相干。"}, "sentence_index": 6, "correct_answer": "起诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我要起诉你的热情帮助。", "explanation": "这里应该用〈感谢〉。起诉的对象必须是人或机构，不能是“帮助”。"}, {"text": "老师起诉了他的作文。", "explanation": "这里应该用〈夸奖〉。作文不能成为起诉的对象，老师称赞作文应说夸奖。"}, {"text": "我起诉了他的道歉。", "explanation": "这里应该用〈接受〉。起诉的对象是人或机构，接受别人的道歉应说接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天起诉了他。", "corrected_sentence": "我明天起诉他。", "error_description": "错误在“了”：“明天”指将来，动作尚未发生，不能用“了”表示已经完成，应去掉“了”，说“我明天起诉他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没起诉了那家公司。", "corrected_sentence": "他没起诉那家公司。", "error_description": "错误在“了”：“没”否定已发生的动作时，后面不再加“了”，应说“他没起诉那家公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
