INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90883, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一点也不会，一定不。", "primary_collocate": null, "pronunciation": "jué bù", "ipa": "tɕɥe˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我绝不会忘记你的帮助。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说过的话，绝不会改变。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我绝不会告诉别人。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，我绝不迟到。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他那么爱孩子，绝不会不管他们。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有准备好，我绝不会上台。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我答应过你，绝不骗你。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很诚实，绝不会说谎。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要我在，就绝不会让你受伤。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么重要的会，他绝不会忘。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絕不", "label": "繁体"}], "register": "书面", "sense_fingerprint": "表示一定不会做某事、保证不发生，常接绝不会＋动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝不", "is_correct": true, "explanation": "正确：“绝不会”表示一定不会忘记，与句子的语气一致。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已完成，不与表示将来的“会”搭配。"}, {"text": "再也", "is_correct": false, "explanation": "搭配：“再也”要和否定词“不”一起用，“再也会”不成立。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去，与句子表示的将来意愿不符。"}], "explanations": {"绝不": "正确：“绝不会”表示一定不会忘记，与句子的语气一致。", "已经": "搭配：“已经”表示已完成，不与表示将来的“会”搭配。", "再也": "搭配：“再也”要和否定词“不”一起用，“再也会”不成立。", "曾经": "语义：“曾经”表示过去，与句子表示的将来意愿不符。"}, "sentence_index": 0, "correct_answer": "绝不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我绝不能考满分，我有信心。", "explanation": "这里应该用〈绝对〉。“绝不”表示坚决否定，与“有信心”的肯定语气矛盾；表示肯定的把握要用“绝对”。"}, {"text": "他已经答应了我，所以他绝不会来。", "explanation": "这里应该用〈一定会〉。“绝不”表示坚决否定，与“已经答应”的肯定理由矛盾；表示肯定的预测要用“一定会”。"}, {"text": "听到这个好消息，我绝不高兴。", "explanation": "这里应该用〈并不〉。“绝不”表示坚决拒绝或保证，不用来描述自然的情绪反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝不", "is_correct": true, "explanation": "正确：“答应过你，绝不骗你”表示坚决的承诺，句子通顺。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与“答应过你”的承诺相矛盾。"}, {"text": "也许", "is_correct": false, "explanation": "语义：“也许”表示不确定，与“答应过你”的承诺不相符。"}, {"text": "压根", "is_correct": false, "explanation": "搭配：“压根”一般与“不”连用，“压根骗你”不成立。"}], "explanations": {"绝不": "正确：“答应过你，绝不骗你”表示坚决的承诺，句子通顺。", "偶尔": "语义：“偶尔”表示有时，与“答应过你”的承诺相矛盾。", "也许": "语义：“也许”表示不确定，与“答应过你”的承诺不相符。", "压根": "搭配：“压根”一般与“不”连用，“压根骗你”不成立。"}, "sentence_index": 6, "correct_answer": "绝不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些花绝不开，它们一直是塑料的。", "explanation": "这里应该用〈不会〉。“绝不”指有意志的人做出的坚决保证，不用来描述花、机器等没有意志的事物。"}, {"text": "这块石头绝不动，因为没有人推它。", "explanation": "这里应该用〈不会〉。“绝不”指有意志的人做出的坚决保证，不用来描述石头这类没有意志的事物。"}, {"text": "这台机器绝不运转，因为它没有通电。", "explanation": "这里应该用〈不会〉。“绝不”指有意志的人做出的坚决保证，不用来描述机器这类没有意志的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我向你保证，绝不泄露了这个秘密。", "corrected_sentence": "我向你保证，绝不泄露这个秘密。", "error_description": "错误在“了”：“绝不”表示坚决不做某事，是对将来的保证，不能与表示完成的“了”一起用。正确说法是：我向你保证，绝不泄露这个秘密。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个男孩很善良，很绝不欺负同学。", "corrected_sentence": "这个男孩很善良，绝不欺负同学。", "error_description": "错误在程度副词：“绝不”是副词，不能再被“很”修饰，“很”应删去。正确说法是：这个男孩很善良，绝不欺负同学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
