INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90884, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示坚决否定。", "primary_collocate": null, "pronunciation": "jué bù", "ipa": "tɕɥe˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我们绝不接受这样的条件。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，我们绝不能马虎。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种错误绝不允许再发生。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他绝不同意这个办法。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们绝不放弃，一定要坚持到底。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在考试中，绝不能作弊。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，绝不可以迟到。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们绝不向困难低头。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家绝不允许这样的事情。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他态度很坚决，绝不后退。", "target_word": "绝不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絕不", "label": "繁体"}], "register": "书面", "sense_fingerprint": "表示坚决的态度或禁止，常说绝不能、绝不允许、绝不接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝不", "is_correct": true, "explanation": "正确：“我们绝不接受这样的条件”表示坚决拒绝，语气与句子一致。"}, {"text": "再也", "is_correct": false, "explanation": "搭配：“再也”要和否定词“不”一起用，“再也接受”不成立。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示白费、没有好处，与“接受这样的条件”的语境不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数不多，与表示坚决态度的句子不协调。"}], "explanations": {"绝不": "正确：“我们绝不接受这样的条件”表示坚决拒绝，语气与句子一致。", "再也": "搭配：“再也”要和否定词“不”一起用，“再也接受”不成立。", "白白": "语义：“白白”表示白费、没有好处，与“接受这样的条件”的语境不合。", "偶尔": "语义：“偶尔”表示次数不多，与表示坚决态度的句子不协调。"}, "sentence_index": 0, "correct_answer": "绝不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天绝不下雨，因为预报说是晴天。", "explanation": "这里应该用〈不会〉。“绝不”表示坚决的态度，不能用来描述天气这类非意志的自然现象。"}, {"text": "这个消息让大家很激动，他却绝不兴奋。", "explanation": "这里应该用〈并不〉。“绝不”表示坚决拒绝，与“大家很激动”的语境不协调；表示没有兴奋要用“并不”。"}, {"text": "他的成绩绝不提高，因为他从来不复习。", "explanation": "这里应该用〈不会〉。“绝不”表示坚决的态度，不用来预测成绩这类客观结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝不", "is_correct": true, "explanation": "正确：“老师说，绝不可以迟到”表示坚决的禁止，语气通顺。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”后面要接“不”“别”或“要”，“千万可以迟到”不成立。"}, {"text": "差点", "is_correct": false, "explanation": "搭配：“差点”表示几乎发生，不能修饰“可以”，“差点可以迟到”不成立。"}, {"text": "压根", "is_correct": false, "explanation": "搭配：“压根”一般与“不”连用，“压根可以迟到”不成立。"}], "explanations": {"绝不": "正确：“老师说，绝不可以迟到”表示坚决的禁止，语气通顺。", "千万": "搭配：“千万”后面要接“不”“别”或“要”，“千万可以迟到”不成立。", "差点": "搭配：“差点”表示几乎发生，不能修饰“可以”，“差点可以迟到”不成立。", "压根": "搭配：“压根”一般与“不”连用，“压根可以迟到”不成立。"}, "sentence_index": 6, "correct_answer": "绝不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子绝不后退，它一直站在原地。", "explanation": "这里应该用〈不会〉。“绝不”表示有意识的坚决态度，不用来描述物体。"}, {"text": "这台电脑绝不开机，因为它没有插电源。", "explanation": "这里应该用〈不会〉。“绝不”表示坚决拒绝，不用来描述机器这类没有意志的事物。"}, {"text": "这个班的学生绝不高兴，但他们都在笑。", "explanation": "这里应该用〈并不〉。“绝不”表示坚决否定，与后文“都在笑”前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考场上绝不能不作弊。", "corrected_sentence": "考场上绝不能作弊。", "error_description": "错误在多出一个“不”：“绝不能不作弊”字面意思变成了“必须作弊”，与原意“绝不能作弊”正好相反。正确说法是：考场上绝不能作弊。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种做法很绝不可取。", "corrected_sentence": "这种做法绝不可取。", "error_description": "错误在程度副词：“绝不”是副词，不能被“很”修饰，“很”应删去。正确说法是：这种做法绝不可取。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
