INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "载是用车、船把东西或人带到别的地方。", "primary_collocate": null, "pronunciation": "zài", "ipa": "tsai˥˩", "syllable_count": 1, "sentences": [{"text": "这辆小车载着一家四口去海边。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船载着我们过河。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大卡车载着很多苹果开走了。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的自行车载着女儿去学校。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条船载着游客慢慢地向岛上开去。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车载着学生回家了。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开车载我去机场。", "target_word": "载", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出租车载着他们到了火车站。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船载着一些鱼回到了岸边。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船明天载我们到对岸去。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "载着", "label": "进行体"}, {"form": "载了", "label": "完成体"}, {"form": "載", "label": "繁体"}], "register": "中性", "sense_fingerprint": "载：用车船把人或东西带到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c1563-16f3-4d23-b8d9-2411ca5ce2db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "载", "is_correct": true, "explanation": "载 zài：用车、船把人或东西运到别处，是本义，正确答案。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 zài 声母不同（c/z），意思是蔬菜。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zài 韵母不同（an/ai），意思是称赞。"}, {"text": "造", "is_correct": false, "explanation": "zào 与 zài 韵母不同（ao/ai），意思是制造。"}, {"text": "灾", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。"}, {"text": "宰", "is_correct": false, "explanation": "zǎi（第三声）与 zài（第四声）声调不同，意思是宰杀。"}], "explanations": {"载": "载 zài：用车、船把人或东西运到别处，是本义，正确答案。", "菜": "cài（第四声）与 zài 声母不同（c/z），意思是蔬菜。", "赞": "zàn 与 zài 韵母不同（an/ai），意思是称赞。", "造": "zào 与 zài 韵母不同（ao/ai），意思是制造。", "灾": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。", "宰": "zǎi（第三声）与 zài（第四声）声调不同，意思是宰杀。"}, "sentence_index": null, "correct_answer": "载"}, "level_3": {"options": [{"text": "载", "is_correct": true, "explanation": "正确：“载”表示用车运送人，与“小车”“一家四口”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说小车吃着一家人去海边。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，与运送一家人去海边无关。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能接“一家四口”。"}], "explanations": {"载": "正确：“载”表示用车运送人，与“小车”“一家四口”相合。", "吃": "语义：“吃”指进食，不能说小车吃着一家人去海边。", "唱": "语义：“唱”指发声歌唱，与运送一家人去海边无关。", "穿": "搭配：“穿”的宾语是衣物，不能接“一家四口”。"}, "sentence_index": 0, "correct_answer": "载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他载着行李走路回家。", "explanation": "这里应该用〈提〉。“载”的运送者须是车船等交通工具，徒步提着行李要用〈提〉。"}, {"text": "奶奶载着孙子在公园散步。", "explanation": "这里应该用〈牵〉。“载”指借助车船等交通工具运送，奶奶牵着孙子散步，不能用“载”。"}, {"text": "她载着两桶水走过院子。", "explanation": "这里应该用〈挑〉。“载”的运送者须是车船等交通工具，挑着水步行要用〈挑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90885, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "载", "is_correct": true, "explanation": "载 zài：用车、船运送，是本义，正确答案。"}, {"text": "带", "is_correct": false, "explanation": "dài 与 zài 声母不同（d/z），意思是带领。"}, {"text": "栽", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是栽种。"}, {"text": "债", "is_correct": false, "explanation": "zhài 与 zài 声母不同（zh/z），意思是债务。"}, {"text": "寨", "is_correct": false, "explanation": "zhài 与 zài 声母不同（zh/z），意思是村寨。"}], "explanations": {"载": "载 zài：用车、船运送，是本义，正确答案。", "带": "dài 与 zài 声母不同（d/z），意思是带领。", "栽": "zāi（第一声）与 zài（第四声）声调不同，意思是栽种。", "债": "zhài 与 zài 声母不同（zh/z），意思是债务。", "寨": "zhài 与 zài 声母不同（zh/z），意思是村寨。"}, "sentence_index": null, "correct_answer": "载"}, "level_3": {"options": [{"text": "载", "is_correct": true, "explanation": "正确：“载”表示用车运送，与“爸爸开车”“我”相合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是物品，不能接人，且与“开车去机场”不合。"}, {"text": "扛", "is_correct": false, "explanation": "语义：“扛”指用肩背举重物，不能用于开车带人。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，与开车送人去机场无关。"}], "explanations": {"载": "正确：“载”表示用车运送，与“爸爸开车”“我”相合。", "洗": "搭配：“洗”的宾语是物品，不能接人，且与“开车去机场”不合。", "扛": "语义：“扛”指用肩背举重物，不能用于开车带人。", "唱": "语义：“唱”指发声歌唱，与开车送人去机场无关。"}, "sentence_index": 6, "correct_answer": "载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员载着托盘走进包间。", "explanation": "这里应该用〈端〉。“载”指借助车船等交通工具运送，端着托盘步行要用〈端〉。"}, {"text": "几个人载着木箱走在山路上。", "explanation": "这里应该用〈抬〉。“载”指借助车船等交通工具运送，几个人徒步抬着木箱要用〈抬〉。"}, {"text": "他把书载进书包里。", "explanation": "这里应该用〈装〉。“载”指用车船运送，把书放进书包要用〈装〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = E