INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用交通工具装运。", "primary_collocate": null, "pronunciation": "zài", "ipa": "tsai˥˩", "syllable_count": 1, "sentences": [{"text": "这辆卡车载货，不载人。", "target_word": "载", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机载着很多客人飞向北京。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大船能载一千吨货。", "target_word": "载", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车一次可以载很多人。", "target_word": "载", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这辆车最多载五吨东西。", "target_word": "载", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "货车载着水果开往城里。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机今天载了二百个客人。", "target_word": "载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种小船只能载三个人。", "target_word": "载", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大轮船载着汽车去国外。", "target_word": "载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车载满了煤，慢慢开走。", "target_word": "载", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "载着", "label": "进行体"}, {"form": "载了", "label": "完成体"}, {"form": "載", "label": "繁体"}], "register": "中性", "sense_fingerprint": "载：交通工具装运货物或乘客", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c1563-16f3-4d23-b8d9-2411ca5ce2db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, 