INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "载", "is_correct": true, "explanation": "载 zài：用交通工具装运，是本义，正确答案。"}, {"text": "栽", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是栽种。"}, {"text": "债", "is_correct": false, "explanation": "zhài 与 zài 声母不同（zh/z），意思是债务。"}, {"text": "赛", "is_correct": false, "explanation": "sài 与 zài 声母不同（s/z），意思是比赛。"}, {"text": "带", "is_correct": false, "explanation": "dài 与 zài 声母不同（d/z），意思是带领。"}], "explanations": {"载": "载 zài：用交通工具装运，是本义，正确答案。", "栽": "zāi（第一声）与 zài（第四声）声调不同，意思是栽种。", "债": "zhài 与 zài 声母不同（zh/z），意思是债务。", "赛": "sài 与 zài 声母不同（s/z），意思是比赛。", "带": "dài 与 zài 声母不同（d/z），意思是带领。"}, "sentence_index": null, "correct_answer": "载"}, "level_3": {"options": [{"text": "载", "is_correct": true, "explanation": "正确：“载货”指用卡车装运货物，与“不载人”相呼应。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说卡车吃货。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能接“货”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是清洗对象，不能指卡车装运货物。"}], "explanations": {"载": "正确：“载货”指用卡车装运货物，与“不载人”相呼应。", "吃": "语义：“吃”指进食，不能说卡车吃货。", "穿": "搭配：“穿”的宾语是衣物，不能接“货”。", "洗": "搭配：“洗”的宾语是清洗对象，不能指卡车装运货物。"}, "sentence_index": 0, "correct_answer": "载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈载着菜步行去市场。", "explanation": "这里应该用〈拎〉。“载”指借助车船等交通工具运送，步行拎着菜要用〈拎〉。"}, {"text": "他把水果载进了箱子里。", "explanation": "这里应该用〈放〉。“载”指用交通工具装运，把水果放进箱子要用〈放〉。"}, {"text": "他载着两桶水回家。", "explanation": "这里应该用〈挑〉。“载”的运送者须是交通工具，用肩挑水要用〈挑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 