INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "产生效果，发挥作用。", "primary_collocate": null, "pronunciation": "qǐ zuò yòng", "ipa": "tɕʰi˨˩ tswo˥˩ jʊŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种药对头疼很起作用。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试了很多方法，都没起作用。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的规定已经开始起作用了。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机地图在山里没起作用，因为没有信号。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的安慰对孩子起作用了。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新药在他身上一点也不起作用。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说的学习方法，对我真的起作用。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机坏了，这个按钮已经不起作用。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格降了以后，广告才开始起作用。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的钱再多，在这里也不起作用。", "target_word": "起作用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不起作用", "label": "否定"}, {"form": "没起作用", "label": "否定"}], "register": "中性", "sense_fingerprint": "产生效果，发挥作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起作用", "is_correct": true, "explanation": "正确。“起作用”表示药产生效果，与“这种药对头疼很___”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：药不会“睡觉”，而且“很睡觉”不成立，句子不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指人的情绪表现，药不会哭，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语须是人，不能用于“这种药”。"}], "explanations": {"起作用": "正确。“起作用”表示药产生效果，与“这种药对头疼很___”相符。", "睡觉": "语义：药不会“睡觉”，而且“很睡觉”不成立，句子不通。", "哭": "语义：“哭”指人的情绪表现，药不会哭，句子不通。", "结婚": "搭配：“结婚”的主语须是人，不能用于“这种药”。"}, "sentence_index": 0, "correct_answer": "起作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话让妈妈很起作用。", "explanation": "这里应该用〈生气〉。“起作用”指办法或事物产生效果，不能用来形容人的情绪。"}, {"text": "这件事让我很起作用。", "explanation": "这里应该用〈着急〉。“起作用”不用于描述人的心理状态。"}, {"text": "这个消息让弟弟很起作用。", "explanation": "这里应该用〈兴奋〉。“起作用”指产生效果，表达人的激动情绪要用〈兴奋〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起作用", "is_correct": true, "explanation": "正确。“起作用”表示学习方法产生效果，与“对我真的___”相符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能以“学习方法”为施事，句子不通。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”说人的身体状况，学习方法不会感冒。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”的主语须是人，不能说“学习方法结婚”。"}], "explanations": {"起作用": "正确。“起作用”表示学习方法产生效果，与“对我真的___”相符。", "散步": "配价：“散步”是不及物动词，不能以“学习方法”为施事，句子不通。", "感冒": "语义：“感冒”说人的身体状况，学习方法不会感冒。", "结婚": "搭配：“结婚”的主语须是人，不能说“学习方法结婚”。"}, "sentence_index": 6, "correct_answer": "起作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈让我早点起作用，我却想再睡一会儿。", "explanation": "这里应该用〈起床〉。“起作用”指产生效果，不指从床上起来，早上起床要用〈起床〉。"}, {"text": "老师说：请大家起作用，把作业交上来。", "explanation": "这里应该用〈起立〉。“起作用”指产生效果，不指站起来，请大家站起来要用〈起立〉。"}, {"text": "这篇讲稿是他起作用的，写得很好。", "explanation": "这里应该用〈起草〉。“起作用”指产生效果，不指写文件，写讲稿的草稿要用〈起草〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药对咳嗽很起作用过。", "corrected_sentence": "这种药对咳嗽很起作用。", "error_description": "体标错误：“起作用”后不能直接加“过”，应删去句末的“过”，说“这种药对咳嗽很起作用”；表示经历时“过”应放在“起”和“作用”之间，说“起过作用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方法对提高成绩很起作用过。", "corrected_sentence": "这个方法对提高成绩很起作用。", "error_description": "体标错误：“起作用”后不能直接加“过”，应删去句末的“过”，说“很起作用”；表示经历时“过”应放在“起”和“作用”之间，说“起过作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
