INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头发是长在头上的细细的毛，有黑的，也有黄的。", "primary_collocate": null, "pronunciation": "tóu fa", "ipa": "tʰoʊ˧˥ fa", "syllable_count": 2, "sentences": [{"text": "中国人的头发大多是黑色的。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头发是黄色的，像金子一样。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的头发好细，摸起来很软。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小宝宝刚出生，头发还很少。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟的头发是卷的。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她有一头长长的黑头发。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外国人的头发有黄的，也有红的。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一根头发很细，很难看清楚。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的头发又细又软，很好看。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳下面，他的头发看起来是金色的。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "頭髮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长在头上的细毛；有黑、黄等颜色和粗细、软硬之分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：声音不能是黑色的，句子说不通。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌不能是黑色的，句子说不通。"}, {"text": "手指", "is_correct": false, "explanation": "体貌：颜色描写多用于头发、眼睛等，手指不说“黑色的”。"}, {"text": "头发", "is_correct": true, "explanation": "正确：中国人的头发大多是黑色的，符合常识。"}], "explanations": {"声音": "语义：声音不能是黑色的，句子说不通。", "歌": "语义：歌不能是黑色的，句子说不通。", "手指": "体貌：颜色描写多用于头发、眼睛等，手指不说“黑色的”。", "头发": "正确：中国人的头发大多是黑色的，符合常识。"}, "sentence_index": 0, "correct_answer": "头发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟身上的头发很软。", "explanation": "这里应该用〈羽毛〉。头发只长在人的头上，鸟身上的毛要说羽毛。"}, {"text": "我的书包里有一支头发。", "explanation": "这里应该用〈根〉。“支”用于笔等细长的东西，头发要用“根”。"}, {"text": "秋天到了，草地上的头发都绿了。", "explanation": "这里应该用〈草〉。草会变绿，人的头发不会长在草地上，这里说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语言", "is_correct": false, "explanation": "语义：语言不能有颜色，句子说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是数字，不说“黄的，红的”。"}, {"text": "头发", "is_correct": true, "explanation": "正确：头发可以有黄的、红的等不同颜色。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字没有颜色，不能说“有黄的，也有红的”。"}], "explanations": {"语言": "语义：语言不能有颜色，句子说不通。", "身高": "体貌：身高是数字，不说“黄的，红的”。", "头发": "正确：头发可以有黄的、红的等不同颜色。", "名字": "语义：名字没有颜色，不能说“有黄的，也有红的”。"}, "sentence_index": 6, "correct_answer": "头发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的头发每天都要去上学。", "explanation": "头发是身体的一部分，不会去上学。这里把头发当成了人。"}, {"text": "妈妈用头发做了一顿饭。", "explanation": "头发不能用来做饭，这里把头发当成了工具。"}, {"text": "这根头发很可爱，会说话。", "explanation": "这里把头发当成了能说话的人或动物。头发是长在头上的毛，不会说话，“会说话”只能用于人或动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在饭里发现了一张头发。", "corrected_sentence": "我在饭里发现了一根头发。", "error_description": "量词错误：“张”用于扁平的东西，头发是细长的，要用“根”。应把“一张头发”改为“一根头发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我拔了一条头发。", "corrected_sentence": "我拔了一根头发。", "error_description": "量词错误：“条”用于长条形的东西，头发要用“根”。应把“一条头发”改为“一根头发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
