INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人头上长的毛。", "primary_collocate": null, "pronunciation": "tóu fa", "ipa": "tʰoʊ˧˥ fa", "syllable_count": 2, "sentences": [{"text": "她的头发很长，一直到腰。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈每天早上都梳头发。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头发是黑色的。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "洗完澡以后，我用吹风机吹头发。", "target_word": "头发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的头发白了，他已经老了。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去理发店，把头发剪短一点。", "target_word": "头发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她染了头发，现在是金黄色的。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大，吹乱了我的头发。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子的头发又黑又亮。", "target_word": "头发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他生病以后，头发掉了很多。", "target_word": "头发", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "頭髮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人头上长的毛；可梳、洗、剪、染", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耳朵", "is_correct": false, "explanation": "语义：耳朵不会很长，更不会长到腰，句子说不通。"}, {"text": "手指", "is_correct": false, "explanation": "体貌：手指不会长到腰那么长，不符合人的身体特征。"}, {"text": "头发", "is_correct": true, "explanation": "正确：头发是长在头上的毛，可以长到腰。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“很长”不能用来形容眼睛。"}], "explanations": {"耳朵": "语义：耳朵不会很长，更不会长到腰，句子说不通。", "手指": "体貌：手指不会长到腰那么长，不符合人的身体特征。", "头发": "正确：头发是长在头上的毛，可以长到腰。", "眼睛": "搭配：“很长”不能用来形容眼睛。"}, "sentence_index": 0, "correct_answer": "头发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的枕头上有一粒头发。", "explanation": "这里应该用〈根〉。“粒”用于小颗粒，头发是细长的，要用“根”。"}, {"text": "弟弟把头发当成零食吃了。", "explanation": "这里应该用〈饼干〉。饼干是食物，可以当零食吃；头发不是食物，不能吃。"}, {"text": "她用头发写字，字写得很好。", "explanation": "这里应该用〈钢笔〉。钢笔是工具，可以用来写字；头发不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墙", "is_correct": false, "explanation": "搭配：“染”不用于墙，墙要说“刷”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不能被染成金黄色，句子说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能被染成颜色，句子说不通。"}, {"text": "头发", "is_correct": true, "explanation": "正确：头发可以染色，染完会变成金黄色。"}], "explanations": {"墙": "搭配：“染”不用于墙，墙要说“刷”。", "作业": "语义：作业不能被染成金黄色，句子说不通。", "房子": "语义：房子不能被染成颜色，句子说不通。", "头发": "正确：头发可以染色，染完会变成金黄色。"}, "sentence_index": 6, "correct_answer": "头发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的头发，我很喜欢他。", "explanation": "头发是长在头上的毛，不指人。这里把头发当成了人，说不通。"}, {"text": "我把头发借给了朋友，他很开心。", "explanation": "这里把头发当成了可以借出的物品。头发长在头上，是身体的一部分，不是物品，不能借给朋友。"}, {"text": "头发每天都去学校上学。", "explanation": "头发不会去学校，这里把头发当成了有行动能力的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块头发是我的。", "corrected_sentence": "这根头发是我的。", "error_description": "量词错误：“块”用于块状的东西，头发是细长的，要用“根”。应把“这块头发”改为“这根头发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地上有一张头发。", "corrected_sentence": "地上有一根头发。", "error_description": "量词错误：“张”用于扁平的东西，头发要用“根”。应把“一张头发”改为“一根头发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90894, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
