INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体和精神。", "primary_collocate": null, "pronunciation": "shēn xīn", "ipa": "ʂən˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "运动对身心都有好处。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行让我的身心得到了放松。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的身心还在成长。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙会影响身心健康。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天练瑜伽，身心都很平静。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好睡一觉，身心就会恢复。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期压力让他身心疲惫。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人需要身心两方面的照顾。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个假期，我想让身心好好休息。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐能让人身心愉快。", "target_word": "身心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身心健康", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体和精神两方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身心", "is_correct": true, "explanation": "身心指身体和精神两方面，符合“运动对身心都有好处”的语境。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有身体和精神，运动对它不会有好处，句子说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能从运动中获益，这里需要指有身体和精神的人。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“对……有好处”的对象应是人或生物，不能说运动对房子有好处。"}], "explanations": {"身心": "身心指身体和精神两方面，符合“运动对身心都有好处”的语境。", "电脑": "语义：电脑没有身体和精神，运动对它不会有好处，句子说不通。", "手机": "语义：手机不能从运动中获益，这里需要指有身体和精神的人。", "房子": "搭配：“对……有好处”的对象应是人或生物，不能说运动对房子有好处。"}, "sentence_index": 0, "correct_answer": "身心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身心很高，打篮球很好。", "explanation": "这里应该用〈身材〉。身心指身体和精神，不用来说个子高矮；说个子高要用身材或身高。"}, {"text": "这台电脑的身心很好，运行得很快。", "explanation": "这里应该用〈机身〉。身心指人的身体和精神，不能用来说机器的外壳；说电脑的外形要用机身。"}, {"text": "医生给他量了一下身心，说他比去年高了两厘米。", "explanation": "这里应该用〈身高〉。量身高指测量身体的高度，身心是身体和精神的整体，不能用来量高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身心", "is_correct": true, "explanation": "身心指身体和精神，符合“压力让人身心疲惫”的语境。"}, {"text": "电视", "is_correct": false, "explanation": "语义：压力不会让电视疲惫，“疲惫”说的是人的状态。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有身体和精神，不会因为压力而疲惫。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“疲惫”形容人的身心状态，不能用来形容书包。"}], "explanations": {"身心": "身心指身体和精神，符合“压力让人身心疲惫”的语境。", "电视": "语义：压力不会让电视疲惫，“疲惫”说的是人的状态。", "窗户": "语义：窗户没有身体和精神，不会因为压力而疲惫。", "书包": "搭配：“疲惫”形容人的身心状态，不能用来形容书包。"}, "sentence_index": 6, "correct_answer": "身心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支笔的身心很长，写起来很顺。", "explanation": "这里应该用〈笔身〉。身心指人的身体和精神，笔没有身心；说笔的外形要用笔身。"}, {"text": "这个孩子的身心很聪明，一学就会。", "explanation": "这里应该用〈头脑〉。聪明只指智力，身心强调身体和精神两方面，不能用来说聪明。"}, {"text": "蚊子咬了他的身心，他身上起了几个包。", "explanation": "这里应该用〈身体〉。被蚊子咬只涉及皮肤，句子说的是身上的变化，不适合用身心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "散步对身心都很好处。", "corrected_sentence": "散步对身心都很有好处。", "error_description": "「好处」是名词，不能直接受「很」修饰，须说「很有好处」，缺少「有」即不通；正确形式是「散步对身心都很有好处」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该照顾得身心。", "corrected_sentence": "我们应该照顾好身心。", "error_description": "补语错误：“照顾”后的结果补语应用“好”，不能用“得”，应说“照顾好身心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
