INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把所有钱加在一起的总数。", "primary_collocate": null, "pronunciation": "zǒng é", "ipa": "tsʊŋ˨˩˦ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我把所有的钱加起来，总额是五百元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天买菜花的钱，总额是六十元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟数了数存钱罐，总额有两百元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三张发票的总额是一千二百元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个人的钱，总额够买这台电脑。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把每个月的房租加在一起，总额很大。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看账本，说今年花的总额不少。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这些东西价钱的总额。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱的总额比我想的少。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市小票上的总额是四十五元。", "target_word": "总额", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把各笔钱加起来得到的总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd39432ac-a2b3-4cb2-a82d-341df50f8430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总额", "is_correct": true, "explanation": "“总额”正确：把所有钱加起来的数目就是总额，符合语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用于钱的数目。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“地址”指位置，不能说“地址是五百元”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指年数，与钱的数目不合。"}], "explanations": {"总额": "“总额”正确：把所有钱加起来的数目就是总额，符合语境。", "身材": "体貌：“身材”指人的体形，不能用于钱的数目。", "地址": "搭配：“地址”指位置，不能说“地址是五百元”。", "年龄": "语义：“年龄”指年数，与钱的数目不合。"}, "sentence_index": 0, "correct_answer": "总额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货的总额是三百箱。", "explanation": "这里应该用〈数量〉。“总额”指钱的总数，货物的件数要说“数量”。"}, {"text": "这台电脑的总额是十五寸。", "explanation": "这里应该用〈尺寸〉。“总额”指金额，屏幕大小要说“尺寸”。"}, {"text": "这座城市的总额是两百万人。", "explanation": "这里应该用〈人口〉。“总额”只用于金额，城市的人数要说“人口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总额", "is_correct": true, "explanation": "“总额”正确：今年花的钱合计起来不少，符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用于花的钱。"}, {"text": "路线", "is_correct": false, "explanation": "搭配：“路线”指行走的路径，不能说“花的路线”。"}, {"text": "时刻", "is_correct": false, "explanation": "语义：“时刻”指时间点，与花钱的数目不合。"}], "explanations": {"总额": "“总额”正确：今年花的钱合计起来不少，符合语境。", "身高": "体貌：“身高”指人的高矮，不能用于花的钱。", "路线": "搭配：“路线”指行走的路径，不能说“花的路线”。", "时刻": "语义：“时刻”指时间点，与花钱的数目不合。"}, "sentence_index": 6, "correct_answer": "总额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的总额是一米八。", "explanation": "这里应该用〈身高〉。“总额”指钱的总数，人的高矮要说“身高”。"}, {"text": "比赛的总额是两小时。", "explanation": "这里应该用〈时间〉。“总额”指金额，比赛的时长要说“时间”。"}, {"text": "这箱苹果的总额是十斤。", "explanation": "这里应该用〈重量〉。“总额”指金额，不能用来说斤两，表示轻重要说“重量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行花的钱，总额是三千个。", "corrected_sentence": "这次旅行花的钱，总额是三千元。", "error_description": "单位错误：“总额”是钱的总数，要用“元”等货币单位，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这半年的电费总额是九百斤。", "corrected_sentence": "这半年的电费总额是九百元。", "error_description": "单位错误：“总额”是钱的总数，要用“元”，不能用重量单位“斤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fd59d53-ad08-4927-8fe7-2a41bf7a4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
