INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "餐厅是可以去吃饭的地方，有很多桌子和椅子。", "primary_collocate": null, "pronunciation": "cān tīng", "ipa": "tsʰan˥ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "餐厅里有很多桌子和椅子。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的餐厅不大，只有一张桌子。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭做好了，大家都到餐厅来吃。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在餐厅里一边吃饭，一边说话。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间餐厅有二十张桌子，能坐八十个人。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司的餐厅中午十二点开饭。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把椅子搬到餐厅，请客人坐下。", "target_word": "餐厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍楼下有一个大餐厅，学生都在那儿吃饭。", "target_word": "餐厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请大家先去餐厅，再回教室。”", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐厅的灯很亮，桌子上放着一束花。", "target_word": "餐厅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "自助餐厅", "label": "复合"}, {"form": "餐廳", "label": "繁体"}], "register": "通用", "sense_fingerprint": "摆着桌椅、供人坐下吃饭的房间或大厅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐厅", "is_correct": true, "explanation": "正确：餐厅是摆着桌椅的房间，「餐厅里有很多桌子和椅子」说得通。"}, {"text": "森林", "is_correct": false, "explanation": "语义：森林里是树木，不会有桌子和椅子。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋里不会有桌子和椅子，与句子矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：「天空里」不能与桌椅搭配，句子说的是室内的房间。"}], "explanations": {"餐厅": "正确：餐厅是摆着桌椅的房间，「餐厅里有很多桌子和椅子」说得通。", "森林": "语义：森林里是树木，不会有桌子和椅子。", "海洋": "语义：海洋里不会有桌子和椅子，与句子矛盾。", "天空": "搭配：「天空里」不能与桌椅搭配，句子说的是室内的房间。"}, "sentence_index": 0, "correct_answer": "餐厅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在一条餐厅里一边吃饭，一边说话。", "explanation": "这里应该用〈间〉。〈条〉用于细长的东西，不用来量餐厅。"}, {"text": "妈妈在餐厅里一边做饭，一边照看孩子。", "explanation": "这里应该用〈厨房〉。餐厅摆着桌椅供人吃饭，做饭要在〈厨房〉里。"}, {"text": "这家餐厅有一百间客房，周末客人很多。", "explanation": "这里应该用〈饭店〉。客房供人住宿，餐厅只供吃饭，不能说有客房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐厅", "is_correct": true, "explanation": "正确：「她把椅子搬到餐厅，请客人坐下」中，餐厅是可以放椅子并请客人坐下的房间。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：椅子不能搬到垃圾桶里，也不能请客人在那里坐下。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：椅子不会搬进冰箱，「请客人坐下」也不适用于冰箱。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：「搬到」后面的地点不能是花瓶，花瓶装不下椅子。"}], "explanations": {"餐厅": "正确：「她把椅子搬到餐厅，请客人坐下」中，餐厅是可以放椅子并请客人坐下的房间。", "垃圾桶": "语义：椅子不能搬到垃圾桶里，也不能请客人在那里坐下。", "冰箱": "语义：椅子不会搬进冰箱，「请客人坐下」也不适用于冰箱。", "花瓶": "搭配：「搬到」后面的地点不能是花瓶，花瓶装不下椅子。"}, "sentence_index": 6, "correct_answer": "餐厅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张餐厅的灯很亮，桌子上放着一束花。", "explanation": "这里应该用〈间〉。〈张〉用于桌子、纸张等平面的东西，不用来量餐厅。"}, {"text": "这家餐厅的客房很干净，床头放着一束花。", "explanation": "这里应该用〈宾馆〉。餐厅只供吃饭，没有客房。"}, {"text": "这把餐厅的灯很亮，桌子上放着一束花。", "explanation": "这里应该用〈间〉。〈把〉用于有柄的东西，不用来量餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只餐厅有两张大桌子。", "corrected_sentence": "这间餐厅有两张大桌子。", "error_description": "量词错误：餐厅应该用「间」，不能用「只」。「只」用于动物或成对物品中的一个，正确的说法是「这间餐厅」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在餐厅上等我们。", "corrected_sentence": "老师在餐厅里等我们。", "error_description": "方位词错误：表示在房间内应说「餐厅里」。「上」指在物体的表面，不能用于餐厅，正确的说法是「老师在餐厅里等我们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
