INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人就餐的地方。", "primary_collocate": null, "pronunciation": "cān tīng", "ipa": "tsʰan˥ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "这家餐厅的菜很好吃。", "target_word": "餐厅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在餐厅里点了三个菜。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐厅的服务员很热情，笑着问我们吃什么。", "target_word": "餐厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末这家餐厅人很多，我们要先订位子。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一家中国餐厅做经理。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校旁边新开了一家餐厅。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店的餐厅早上七点开门。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅的菜单上有中文和英文。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在餐厅门口等了二十分钟才有位子。", "target_word": "餐厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个餐厅很安静，适合朋友一起聊天。", "target_word": "餐厅", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "西餐厅", "label": "复合"}, {"form": "餐廳", "label": "繁体"}], "register": "通用", "sense_fingerprint": "供客人点菜吃饭的营业场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐厅", "is_correct": true, "explanation": "正确：餐厅是供客人点菜吃饭的地方，「这家餐厅的菜」说得通。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店卖书，不做菜，「这家书店的菜很好吃」说不通。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店提供理发服务，不供应菜肴，与「菜很好吃」矛盾。"}, {"text": "药店", "is_correct": false, "explanation": "搭配：药店不供应菜，「药店的菜」不能与「很好吃」搭配。"}], "explanations": {"餐厅": "正确：餐厅是供客人点菜吃饭的地方，「这家餐厅的菜」说得通。", "书店": "语义：书店卖书，不做菜，「这家书店的菜很好吃」说不通。", "理发店": "语义：理发店提供理发服务，不供应菜肴，与「菜很好吃」矛盾。", "药店": "搭配：药店不供应菜，「药店的菜」不能与「很好吃」搭配。"}, "sentence_index": 0, "correct_answer": "餐厅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去了一条餐厅，人很多。", "explanation": "这里应该用〈家〉。〈条〉用于细长的东西，不用来量餐厅。"}, {"text": "这家餐厅专门卖鞋子，每天来买的人很多。", "explanation": "这里应该用〈鞋店〉。餐厅是供人吃饭的地方，不卖鞋子，「专门卖鞋子」说的是鞋店。"}, {"text": "周末这家餐厅有一百间客房，人很多，我们要先订房。", "explanation": "这里应该用〈饭店〉。客房供人住宿，餐厅只供客人吃饭，不能说有客房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐厅", "is_correct": true, "explanation": "正确：酒店的餐厅是供客人吃饭的营业场所，早上七点开门说得通。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是供客人住宿的地方，不说早上七点开门。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是营业场所，「开门」不适用于手机。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：「开门」不与「行李」搭配，行李没有营业时间。"}], "explanations": {"餐厅": "正确：酒店的餐厅是供客人吃饭的营业场所，早上七点开门说得通。", "房间": "语义：房间是供客人住宿的地方，不说早上七点开门。", "手机": "语义：手机不是营业场所，「开门」不适用于手机。", "行李": "搭配：「开门」不与「行李」搭配，行李没有营业时间。"}, "sentence_index": 6, "correct_answer": "餐厅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张餐厅很安静，适合朋友一起聊天。", "explanation": "这里应该用〈家〉。〈张〉用于桌子、纸张等平面的东西，不用来量餐厅。"}, {"text": "这个餐厅很安静，适合朋友一起住。", "explanation": "这里应该用〈宾馆〉。餐厅只供吃饭，不能住宿。"}, {"text": "这把餐厅很安静，适合朋友一起聊天。", "explanation": "这里应该用〈家〉。〈把〉用于有柄的东西，不用来量餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条餐厅明天开业。", "corrected_sentence": "这家餐厅明天开业。", "error_description": "量词错误：餐厅应该用「家」，不能用「条」。「条」用于细长的东西，正确的说法是「这家餐厅」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这家餐厅吃过晚饭。", "corrected_sentence": "我们在这家餐厅吃过晚饭。", "error_description": "介词漏掉：表示地点的“在”不能省，动作发生在餐厅，应说“我们在这家餐厅吃过晚饭”，不说“我们这家餐厅吃过晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
