INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90899, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "较场是古时候训练兵士的地方。", "primary_collocate": null, "pronunciation": "jiào chǎng", "ipa": "tɕjɑʊ˥˩ tʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "古时候，士兵每天都在较场练武。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个较场很大，能站几千个兵士。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候常听爷爷讲较场里的故事。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上，将军带着兵士来到较场。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兵士们在较场里跑步、练刀。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，古代的较场外面有很高的墙。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "较场上的兵士每天要练好几个小时。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老兵把新兵带到较场，教他们用刀。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事发生在一座古城的较场。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在这里没有较场了，只剩一块空地。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "較場", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "古代兵士练武的场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较场", "is_correct": true, "explanation": "较场是古时候训练兵士的地方，正合「古时候士兵每天在较场练武」。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是现代的游览场所，与古时候的练武不合。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：练武需要宽阔的场地，不能在教室里进行。"}, {"text": "集市", "is_correct": false, "explanation": "语义：集市是买卖东西的地方，与士兵练武无关。"}], "explanations": {"较场": "较场是古时候训练兵士的地方，正合「古时候士兵每天在较场练武」。", "公园": "语义：公园是现代的游览场所，与古时候的练武不合。", "教室": "搭配：练武需要宽阔的场地，不能在教室里进行。", "集市": "语义：集市是买卖东西的地方，与士兵练武无关。"}, "sentence_index": 0, "correct_answer": "较场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在较场上跑步。", "explanation": "这里应该用〈操场〉。较场是古时练兵的地方，不用来指现代学校的操场。"}, {"text": "他生病了，去较场看医生。", "explanation": "这里应该用〈医院〉。较场是古时练兵的地方，不是看病的地方。"}, {"text": "老师在较场里讲课。", "explanation": "这里应该用〈教室〉。较场指古代练兵的场地，不能用来指讲课的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较场", "is_correct": true, "explanation": "较场是练兵的地方，正合「较场上的兵士每天练习」。"}, {"text": "书房", "is_correct": false, "explanation": "搭配：兵士不会在书房里练武，「上」也不能搭配「书房」。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房与练兵无关。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是住宿的地方，不是练兵的场地。"}], "explanations": {"较场": "较场是练兵的地方，正合「较场上的兵士每天练习」。", "书房": "搭配：兵士不会在书房里练武，「上」也不能搭配「书房」。", "厨房": "语义：厨房与练兵无关。", "宿舍": "语义：宿舍是住宿的地方，不是练兵的场地。"}, "sentence_index": 6, "correct_answer": "较场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在较场上踢足球。", "explanation": "这里应该用〈球场〉。较场是古代练兵的地方，不是现代踢足球的场地。"}, {"text": "妈妈在较场买了很多菜。", "explanation": "这里应该用〈菜场〉。较场不是卖菜的地方。"}, {"text": "我把车停在较场了。", "explanation": "这里应该用〈停车场〉。较场是练兵的地方，不用于停车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只较场很大，能容纳几千人。", "corrected_sentence": "那个较场很大，能容纳几千人。", "error_description": "量词错误：「只」多用于动物或成对的东西，场所应用「个」，应为「那个较场」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们每天较场上练武。", "corrected_sentence": "士兵们每天在较场上练武。", "error_description": "介词「在」不能省略，场所前要用「在」引出，应为「士兵们每天在较场上练武」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
