INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧时训练、检阅军队或比武的场地。", "primary_collocate": null, "pronunciation": "jiào chǎng", "ipa": "tɕjɑʊ˥˩ tʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "皇帝到较场看兵士们比武。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧时，将军常在较场检查兵士的练习。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比武那天，较场边站满了人。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个武士在较场上比了三天，最后没有分出高低。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把较场打扫干净，等着将军来检阅。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "较场很宽，旧时兵士都在这里集合。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说里有一段较场比武的故事。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城东有一个旧较场，老人们常去那里散步。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兵士们站在较场中间，听将军说话。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父带着徒弟去较场看比武。", "target_word": "较场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "較場", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "旧时练兵、检阅军队、比武的场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较场", "is_correct": true, "explanation": "较场是旧时练兵、检阅、比武的场地，正合「皇帝到较场看兵士们比武」。"}, {"text": "码头", "is_correct": false, "explanation": "语义：码头是停靠船只的地方，与看比武无关。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：比武需要宽阔的场地，厨房不能容纳比武。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房用于治病，与比武毫无关系。"}], "explanations": {"较场": "较场是旧时练兵、检阅、比武的场地，正合「皇帝到较场看兵士们比武」。", "码头": "语义：码头是停靠船只的地方，与看比武无关。", "厨房": "搭配：比武需要宽阔的场地，厨房不能容纳比武。", "病房": "语义：病房用于治病，与比武毫无关系。"}, "sentence_index": 0, "correct_answer": "较场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考生们在较场上认真答题。", "explanation": "这里应该用〈考场〉。考场是考试的地方，较场是旧时练兵比武的场地，不能用于答题。"}, {"text": "农民在较场里养猪。", "explanation": "这里应该用〈农场〉。农场是种植、养殖的地方，较场是旧时练兵比武的场地，不能用于养猪。"}, {"text": "他在较场里借书。", "explanation": "这里应该用〈图书馆〉。图书馆是借阅书籍的地方，较场是旧时练兵比武的场地，不能用于借书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较场", "is_correct": true, "explanation": "较场是旧时比武的场地，正合「这本小说里有一段较场比武的故事」。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：比武需要场地，书架上不能进行比武。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，与比武无关。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜用来存放衣物，与比武不合。"}], "explanations": {"较场": "较场是旧时比武的场地，正合「这本小说里有一段较场比武的故事」。", "书架": "搭配：比武需要场地，书架上不能进行比武。", "冰箱": "语义：冰箱是家用电器，与比武无关。", "衣柜": "语义：衣柜用来存放衣物，与比武不合。"}, "sentence_index": 6, "correct_answer": "较场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们在较场上盖楼。", "explanation": "这里应该用〈工地〉。较场是旧时练兵比武的场地，不是施工建楼的地方。"}, {"text": "孩子们在较场玩滑梯。", "explanation": "这里应该用〈游乐场〉。较场不是供孩子玩耍的场所。"}, {"text": "科学家在较场做实验。", "explanation": "这里应该用〈实验室〉。较场是练兵比武的场地，不用于科学实验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "较场很大得能站满几千名兵士。", "corrected_sentence": "较场大得能站满几千名兵士。", "error_description": "「大得」已引出程度补语，前面不能再加「很」，应为「较场大得能站满几千名兵士」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旧时，士兵们较场上比武。", "corrected_sentence": "旧时，士兵们在较场上比武。", "error_description": "介词「在」不能省略，场所前要用「在」引出，应为「士兵们在较场上比武」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
