INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90901, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很好吃的东西。", "primary_collocate": null, "pronunciation": "měi shí", "ipa": "meɪ˨˩˦ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "成都有很多美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢和朋友一起找美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有很多美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们最爱吃妈妈做的美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每到一个城市就先找美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去吃美食吧。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的美食种类很多，价格也很便宜。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广州的美食让我忘不了。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了很多美食的照片。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最爱的美食是什么？", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美食家", "label": "复合"}, {"form": "美食街", "label": "复合"}], "register": "中性", "sense_fingerprint": "让人想吃的、很好吃的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美食", "is_correct": true, "explanation": "正确答案：美食 měi shí，指很好吃的东西。"}, {"text": "没事", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是没有关系。"}, {"text": "美事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是美好的事情。"}, {"text": "美式", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是美国式的。"}], "explanations": {"美食": "正确答案：美食 měi shí，指很好吃的东西。", "没事": "méi（第二声）与 měi（第三声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是没有关系。", "美事": "shì（第四声）与 shí（第二声）声调不同，意思是美好的事情。", "美式": "shì（第四声）与 shí（第二声）声调不同，意思是美国式的。"}, "sentence_index": null, "correct_answer": "美食"}, "level_3": {"options": [{"text": "美食", "is_correct": true, "explanation": "正确：美食指很好吃的东西，「成都有很多美食」说得通。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：成都是城市，不是沙漠，「有很多沙漠」与句子的背景矛盾。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是工作的报酬，「成都有很多工资」说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是人的性格，城市没有脾气，句子不成立。"}], "explanations": {"美食": "正确：美食指很好吃的东西，「成都有很多美食」说得通。", "沙漠": "语义：成都是城市，不是沙漠，「有很多沙漠」与句子的背景矛盾。", "工资": "语义：工资是工作的报酬，「成都有很多工资」说不通。", "脾气": "语义：脾气是人的性格，城市没有脾气，句子不成立。"}, "sentence_index": 0, "correct_answer": "美食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天吃了一只美食。", "explanation": "这里应该用〈道〉或〈份〉。〈只〉用于动物或成对物品中的一个，不用来量美食。"}, {"text": "妈妈做的美食有点难吃，我们都没吃完。", "explanation": "这里应该用〈食物〉。美食指很好吃的东西，说「有点难吃」自相矛盾。"}, {"text": "这碗美食已经放了三天，馊了。", "explanation": "这里应该用〈剩菜〉。美食是好吃的东西，「馊了」说的是剩菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美食", "is_correct": true, "explanation": "正确：「这家店的美食种类很多」说得通，美食指好吃的东西。"}, {"text": "病历", "is_correct": false, "explanation": "语义：店里卖东西，不会有「种类很多的病历」，与「这家店」矛盾。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「种类很多」不能与「年龄」搭配，年龄不分种类。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于人，不能说店的脾气种类很多。"}], "explanations": {"美食": "正确：「这家店的美食种类很多」说得通，美食指好吃的东西。", "病历": "语义：店里卖东西，不会有「种类很多的病历」，与「这家店」矛盾。", "年龄": "搭配：「种类很多」不能与「年龄」搭配，年龄不分种类。", "脾气": "语义：脾气属于人，不能说店的脾气种类很多。"}, "sentence_index": 6, "correct_answer": "美食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这包美食有点苦，你还要吃吗？", "explanation": "这里应该用〈零食〉。美食指很好吃的东西，「有点苦」与之矛盾。"}, {"text": "这盒美食太难吃了，我们都扔了。", "explanation": "这里应该用〈点心〉。美食指很好吃的东西，不能说「太难吃」。"}, {"text": "厨师把面粉、鸡蛋和糖等美食一起放进碗里。", "explanation": "这里应该用〈食材〉。美食指做好的、很好吃的东西，面粉、鸡蛋和糖还没做成菜，不能叫美食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今天点了三只美食。", "corrected_sentence": "我们今天点了三道美食。", "error_description": "量词错误：「美食」应该用「道」或「份」，不能用「只」。「只」用于动物或成对物品中的一个，正确的说法是「三道美食」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起美食吧。", "corrected_sentence": "我们一起做美食吧。", "error_description": "缺少动词：「美食」是名词，不能直接放在「一起」之后作谓语，应补上动词「做」，正确的说法是「我们一起做美食吧」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
