INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "美味的食物。", "primary_collocate": null, "pronunciation": "měi shí", "ipa": "meɪ˨˩˦ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "中国有很多地方的美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了各地的美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜市里有各种美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，桌上摆满了美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到美食，孩子们都笑了。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美食和好朋友，都让人开心。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都想尝各地的美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一边看电影，一边吃美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做美食需要时间。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我最想尝当地的美食。", "target_word": "美食", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美食家", "label": "复合"}, {"form": "美食街", "label": "复合"}], "register": "中性", "sense_fingerprint": "味道好的食物、菜肴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90902, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美食", "is_correct": true, "explanation": "正确答案：美食 měi shí，指美味的食物。"}, {"text": "没事", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是没有关系。"}, {"text": "美事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是美好的事情。"}, {"text": "美式", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是美国式的。"}], "explanations": {"美食": "正确答案：美食 měi shí，指美味的食物。", "没事": "méi（第二声）与 měi（第三声）声调不同，shì（第四声）与 shí（第二声）声调不同，意思是没有关系。", "美事": "shì（第四声）与 shí（第二声）声调不同，意思是美好的事情。", "美式": "shì（第四声）与 shí（第二声）声调不同，意思是美国式的。"}, "sentence_index": null, "correct_answer": "美食"}, "level_3": {"options": [{"text": "美食", "is_correct": true, "explanation": "正确：「中国有很多地方的美食」指各地好吃的食物，说得通。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是医疗记录，与各地的食物无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「地方的年龄」不成立，年龄属于人，不能与地方搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重属于人或物体，「地方的体重」说不通。"}], "explanations": {"美食": "正确：「中国有很多地方的美食」指各地好吃的食物，说得通。", "病历": "语义：病历是医疗记录，与各地的食物无关。", "年龄": "搭配：「地方的年龄」不成立，年龄属于人，不能与地方搭配。", "体重": "语义：体重属于人或物体，「地方的体重」说不通。"}, "sentence_index": 0, "correct_answer": "美食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过年的时候，妈妈做了一只美食。", "explanation": "这里应该用〈道〉。〈只〉用于动物或成对物品中的一个，不用来量美食。"}, {"text": "过年的时候，饭桌上只剩下一些难吃的美食。", "explanation": "这里应该用〈食物〉。美食指美味的食物，说「难吃」自相矛盾。"}, {"text": "过年的时候，桌上的美食都馊了。", "explanation": "这里应该用〈剩菜〉。美食是美味的食物，「馊了」说的是剩菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美食", "is_correct": true, "explanation": "正确：「她每天都想尝各地的美食」说得通，美食是可以品尝的好吃的食物。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气属于人的性格，不能用来品尝。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「尝年龄」不成立，年龄不能品尝。"}, {"text": "车钥匙", "is_correct": false, "explanation": "语义：车钥匙是小物件，不能用来品尝。"}], "explanations": {"美食": "正确：「她每天都想尝各地的美食」说得通，美食是可以品尝的好吃的食物。", "脾气": "语义：脾气属于人的性格，不能用来品尝。", "年龄": "搭配：「尝年龄」不成立，年龄不能品尝。", "车钥匙": "语义：车钥匙是小物件，不能用来品尝。"}, "sentence_index": 6, "correct_answer": "美食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的美食又咸又苦，我们不想吃了。", "explanation": "这里应该用〈饭菜〉。美食指美味的食物，「又咸又苦」与之矛盾。"}, {"text": "厨房的架子上摆着酱油、醋和盐等美食。", "explanation": "这里应该用〈调料〉。美食指做好的、很好吃的东西，酱油、醋和盐是调料，不能叫美食。"}, {"text": "这盒美食有点苦，你还要吃吗？", "explanation": "这里应该用〈饼干〉。美食指美味的食物，「有点苦」与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅有一只特色美食。", "corrected_sentence": "这家餐厅有一道特色美食。", "error_description": "量词错误：「美食」应该用「道」，不能用「只」。「只」用于动物或成对物品中的一个，正确的说法是「一道特色美食」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在网上美食。", "corrected_sentence": "她在网上分享美食。", "error_description": "缺少动词：「美食」是名词，不能直接作谓语，应补上动词「分享」，正确的说法是「她在网上分享美食」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
