INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主管是管着一件事或一群人的人。", "primary_collocate": null, "pronunciation": "zhǔ guǎn", "ipa": "ʈ͡ʂu˨˩˦ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们的主管今天要开会。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主管让我把报告交给他。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的主管对大家很客气。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有事想找主管谈一谈。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的主管是一位女士。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主管说明天不用早来。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李很快就当上了主管。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主管请大家吃了一顿饭。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们部门的主管，人很好。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给主管发了一封邮件。", "target_word": "主管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位主管", "label": "量词"}, {"form": "部门主管", "label": "复合"}], "register": "通用", "sense_fingerprint": "主管：管事或管人的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c1563-16f3-4d23-b8d9-2411ca5ce2db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90903, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主管", "is_correct": true, "explanation": "正确：主管是管着一件事或一群人的人。"}, {"text": "主观", "is_correct": false, "explanation": "guān（第一声）与 guǎn（第三声）声调不同，意思是“主观”，指带有个人看法。"}, {"text": "竹管", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子做的管子。"}, {"text": "乳管", "is_correct": false, "explanation": "rǔ 与 zhǔ 声母不同（r 与 zh），意思是乳腺的导管。"}, {"text": "猪倌", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，guān（第一声）与 guǎn（第三声）声调也不同，意思是放猪的人。"}], "explanations": {"主管": "正确：主管是管着一件事或一群人的人。", "主观": "guān（第一声）与 guǎn（第三声）声调不同，意思是“主观”，指带有个人看法。", "竹管": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是竹子做的管子。", "乳管": "rǔ 与 zhǔ 声母不同（r 与 zh），意思是乳腺的导管。", "猪倌": "zhū（第一声）与 zhǔ（第三声）声调不同，guān（第一声）与 guǎn（第三声）声调也不同，意思是放猪的人。"}, "sentence_index": null, "correct_answer": "主管"}, "level_3": {"options": [{"text": "树木", "is_correct": false, "explanation": "语义：树木不会开会，与“今天要开会”的人物主体冲突。"}, {"text": "主管", "is_correct": true, "explanation": "正确：主管指管事的负责人，填入后“我们的主管今天要开会”成立。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能参加会议。"}, {"text": "会议", "is_correct": false, "explanation": "搭配：“会议”本身就是开会，不能说“我们的会议今天要开会”。"}], "explanations": {"树木": "语义：树木不会开会，与“今天要开会”的人物主体冲突。", "主管": "正确：主管指管事的负责人，填入后“我们的主管今天要开会”成立。", "窗户": "语义：窗户是物件，不能参加会议。", "会议": "搭配：“会议”本身就是开会，不能说“我们的会议今天要开会”。"}, "sentence_index": 0, "correct_answer": "主管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块主管很认真。", "explanation": "这里应该用〈位〉或〈个〉。“块”用于块状或片状的东西，主管指人，不能用“块”。"}, {"text": "昨天主管下了一场大雨。", "explanation": "这里应该用〈天〉。主管是人，不能下雨。"}, {"text": "这座主管很高大。", "explanation": "这里应该用〈位〉或〈个〉。“座”用于山、楼等大型固定物，主管指人，不能用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能当上职务。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“当上了”后面要接职务或身份，不能接处所“厨房”。"}, {"text": "主管", "is_correct": true, "explanation": "正确：主管是职务，“小李很快就当上了主管”成立。"}, {"text": "灯笼", "is_correct": false, "explanation": "语义：灯笼是物件，不能当上职务。"}], "explanations": {"春天": "语义：春天是季节，不能当上职务。", "厨房": "搭配：“当上了”后面要接职务或身份，不能接处所“厨房”。", "主管": "正确：主管是职务，“小李很快就当上了主管”成立。", "灯笼": "语义：灯笼是物件，不能当上职务。"}, "sentence_index": 6, "correct_answer": "主管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司新来了一只主管。", "explanation": "这里应该用〈位〉或〈个〉。主管指人，“只”多用于动物。"}, {"text": "这部电影的主管都演得很好。", "explanation": "这里应该用〈演员〉。主管指管事的负责人，不指表演的人。"}, {"text": "他是一辆主管。", "explanation": "这里应该用〈位〉或〈个〉。“辆”用于车辆，主管指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天找了过主管。", "corrected_sentence": "我昨天找过主管。", "error_description": "“过”表示经历，“找过”已含完成义，不能再与“了”连用；应说“找过主管”，这里的“了”要去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他前年就当了上主管。", "corrected_sentence": "他前年就当上了主管。", "error_description": "“当上”是动补结构，“了”要放在补语“上”之后，应说“当上了主管”，不能说“当了上主管”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90905, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "送", "is_correct": true, "explanation": "正确。“迎送”是一对反义词：迎指人来了去接，送指人走时去送。"}, {"text": "跑", "is_correct": false, "explanation": "跑指快速移动，与“迎”没有反义关系。"}, {"text": "等", "is_correct": false, "explanation": "等指等候，与“迎”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃指进食，与“迎”没有反义关系。"}], "correct_answer": "送", "explanations": {"送": "正确。“迎送”是一对反义词：迎指人来了去接，送指人走时去送。", "跑": "跑指快速移动，与“迎”没有反义关系。", "等": "等指等候，与“迎”没有反义关系。", "吃": "吃指进食，与“迎”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
