INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迎是人来了，去接他。", "primary_collocate": null, "pronunciation": "yíng", "ipa": "iŋ˧˥", "syllable_count": 1, "sentences": [{"text": "客人来了，我们到门口迎他。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在车站迎我。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶走出门迎孙子。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟跑出去迎爸爸。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师站在校门口迎同学们。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去机场迎朋友，他坐飞机来。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着迎上去，拉住朋友的手。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你几点到？我去车站迎你。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人都出来迎远方的客人。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等在路口，要迎刚下车的叔叔。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎了", "label": "体标"}, {"form": "迎过", "label": "体标"}, {"form": "迎接", "label": "复合"}], "register": "中性", "sense_fingerprint": "人来了，走过去接他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迎", "is_correct": true, "explanation": "正确。迎是人来了去接他，读 yíng（第二声）。"}, {"text": "影", "is_correct": false, "explanation": "yǐng 与 yíng 声调不同（第三声与第二声），意思是影子。"}, {"text": "银", "is_correct": false, "explanation": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子或银色。"}, {"text": "硬", "is_correct": false, "explanation": "yìng 与 yíng 声调不同（第四声与第二声），意思是坚硬。"}, {"text": "明", "is_correct": false, "explanation": "míng 与 yíng 声母不同（m 与零声母），意思是明亮。"}], "explanations": {"迎": "正确。迎是人来了去接他，读 yíng（第二声）。", "影": "yǐng 与 yíng 声调不同（第三声与第二声），意思是影子。", "银": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子或银色。", "硬": "yìng 与 yíng 声调不同（第四声与第二声），意思是坚硬。", "明": "míng 与 yíng 声母不同（m 与零声母），意思是明亮。"}, "sentence_index": null, "correct_answer": "迎"}, "level_3": {"options": [{"text": "迎", "is_correct": true, "explanation": "正确。迎是人来了去接他，与“客人来了”相合。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指人离开时去送别，句中是客人刚到，不能说送。"}, {"text": "躲", "is_correct": false, "explanation": "语义：客人来了，主人不会躲他，“躲”与迎客的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不带“他”作宾语表示迎接，“吃他”不成立。"}], "explanations": {"迎": "正确。迎是人来了去接他，与“客人来了”相合。", "送": "语义：“送”指人离开时去送别，句中是客人刚到，不能说送。", "躲": "语义：客人来了，主人不会躲他，“躲”与迎客的语境相反。", "吃": "搭配：“吃”不带“他”作宾语表示迎接，“吃他”不成立。"}, "sentence_index": 0, "correct_answer": "迎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我到车站迎你，祝你一路平安。", "explanation": "这里应该用〈送〉。迎指人来了去接，人要走时要说送。"}, {"text": "我每周给爸爸迎一封信。", "explanation": "这里应该用〈寄〉。迎只用于迎接来人，寄信要用寄。"}, {"text": "我去车站迎行李。", "explanation": "这里应该用〈取〉。迎只用于去接人，行李要说取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎", "is_correct": true, "explanation": "正确。迎上去指迎着人走过去，与“拉住朋友的手”相合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔上去”不能与“笑着”和“拉住朋友的手”的动作连贯。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍上去”是攻击的动作，与笑着拉手的语境相反。"}, {"text": "赴", "is_correct": false, "explanation": "语域：“赴”是书面语，指前往，口语叙述中不说“赴上去”。"}], "explanations": {"迎": "正确。迎上去指迎着人走过去，与“拉住朋友的手”相合。", "扔": "语义：“扔上去”不能与“笑着”和“拉住朋友的手”的动作连贯。", "砍": "语义：“砍上去”是攻击的动作，与笑着拉手的语境相反。", "赴": "语域：“赴”是书面语，指前往，口语叙述中不说“赴上去”。"}, "sentence_index": 6, "correct_answer": "迎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快迎下了朋友的邀请。", "explanation": "这里应该用〈接下〉。迎指去接人，接受邀请要说接下。"}, {"text": "他一把迎住了掉下来的球。", "explanation": "这里应该用〈接住〉。迎指去接人，接球要用接住。"}, {"text": "他很快迎到了一封信。", "explanation": "这里应该用〈收到〉。迎用于迎接人，收信要用收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友来了，我们到楼下他迎。", "corrected_sentence": "朋友来了，我们到楼下迎他。", "error_description": "语序错误：“迎”是及物动词，宾语“他”应放在“迎”之后，应说“迎他”，不说“他迎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我明天去车站迎过你。", "corrected_sentence": "我明天去车站迎你。", "error_description": "体标错误：“明天”是将来的事，“迎”后面不能加表示过去经历的“过”，应删去“过”，说“迎你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
