INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90906, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "面对着迎面而来的风、雨、困难等事物向前。", "primary_collocate": null, "pronunciation": "yíng", "ipa": "iŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他迎着风骑车，骑得很慢。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟迎着太阳飞。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她迎着大雨走进学校。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她迎着困难往前走，从不说累。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船迎着大浪往前走。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她迎着大家的眼光，大声说话。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕冷，迎着雪走回家。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在广场上迎着风放风筝，很热闹。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员迎着观众的欢呼声走进球场。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走在山上，迎着风，人觉得很舒服。", "target_word": "迎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迎着", "label": "体标"}], "register": "中性", "sense_fingerprint": "面对着迎面而来的风、雨、困难等向前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd51ad7a1-a286-491d-9bbd-bb1f05a74ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迎", "is_correct": true, "explanation": "正确。迎表示面对着风、雨、困难等向前，读 yíng（第二声）。"}, {"text": "影", "is_correct": false, "explanation": "yǐng 与 yíng 声调不同（第三声与第二声），意思是影子。"}, {"text": "银", "is_correct": false, "explanation": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子或银色。"}, {"text": "硬", "is_correct": false, "explanation": "yìng 与 yíng 声调不同（第四声与第二声），意思是坚硬。"}, {"text": "明", "is_correct": false, "explanation": "míng 与 yíng 声母不同（m 与零声母），意思是明亮。"}], "explanations": {"迎": "正确。迎表示面对着风、雨、困难等向前，读 yíng（第二声）。", "影": "yǐng 与 yíng 声调不同（第三声与第二声），意思是影子。", "银": "yín 与 yíng 韵尾不同（n 与 ng），意思是银子或银色。", "硬": "yìng 与 yíng 声调不同（第四声与第二声），意思是坚硬。", "明": "míng 与 yíng 声母不同（m 与零声母），意思是明亮。"}, "sentence_index": null, "correct_answer": "迎"}, "level_3": {"options": [{"text": "迎", "is_correct": true, "explanation": "正确。迎着风表示面对风前进，与“骑得很慢”的语境相合。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送着风”不能表示骑车前进，“送”指送别。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“风”搭配，“吃着风”不成立。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不带“风”作宾语，“笑着风”不成立。"}], "explanations": {"迎": "正确。迎着风表示面对风前进，与“骑得很慢”的语境相合。", "送": "语义：“送着风”不能表示骑车前进，“送”指送别。", "吃": "搭配：“吃”不能与“风”搭配，“吃着风”不成立。", "笑": "搭配：“笑”不带“风”作宾语，“笑着风”不成立。"}, "sentence_index": 0, "correct_answer": "迎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们迎着河往下走，看风景。", "explanation": "这里应该用〈顺着〉。迎着指面对迎面而来的人或事物，沿河往下游走要用顺着。"}, {"text": "迎着时间的推移，孩子慢慢长大了。", "explanation": "这里应该用〈随着〉。迎着指面对迎面而来的事物，时间推移不会迎面而来，要用随着。"}, {"text": "我站在门口，迎着朋友的背影，祝他一路平安。", "explanation": "这里应该用〈送〉。迎着指面对迎面而来的人或事物，朋友已背对着走远，要说送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎", "is_correct": true, "explanation": "正确。迎着雪表示顶着雪前进，与“不怕冷”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“雪”作宾语，“唱着雪走回家”不成立。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能带“雪”作宾语，“喝着雪走回家”不成立。"}, {"text": "叹", "is_correct": false, "explanation": "搭配：“叹”一般不带“雪”作宾语，只说叹气等。"}], "explanations": {"迎": "正确。迎着雪表示顶着雪前进，与“不怕冷”的语境相合。", "唱": "搭配：“唱”不能带“雪”作宾语，“唱着雪走回家”不成立。", "喝": "搭配：“喝”不能带“雪”作宾语，“喝着雪走回家”不成立。", "叹": "搭配：“叹”一般不带“雪”作宾语，只说叹气等。"}, "sentence_index": 6, "correct_answer": "迎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他迎着行李走在山上。", "explanation": "这里应该用〈扛〉。迎着指面向迎面而来的风雨等，行李要说扛着。"}, {"text": "小明迎着书包走进教室。", "explanation": "这里应该用〈背〉。迎着指面对迎面而来的事物，书包不会迎面而来，背书包要用背着。"}, {"text": "他迎着西瓜走进厨房。", "explanation": "这里应该用〈抱〉。迎着指面对迎面而来的事物，西瓜不会迎面而来，抱西瓜要用抱着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他迎雨着走回家，很辛苦。", "corrected_sentence": "他迎着雨走回家，很辛苦。", "error_description": "“着”位置错误：“着”应紧跟动词“迎”，应说“迎着雨”，不说“迎雨着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天很冷，他迎着了北风跑回家。", "corrected_sentence": "天很冷，他迎着北风跑回家。", "error_description": "体标错误：“着”表示持续，已用“着”就不能再加“了”，应说“迎着北风”，不说“迎着了北风”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c1eec5c-5bd0-4bd2-94a4-dfd84b5ed39f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
