INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90907, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头，在脖子上面。", "primary_collocate": null, "pronunciation": "nǎo dai", "ipa": "naʊ˨˩ taɪ", "syllable_count": 2, "sentences": [{"text": "他的脑袋上戴着一顶红帽子。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把脑袋放在我的腿上。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不小心用脑袋撞到了门。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子的脑袋圆圆的，很可爱。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出脑袋看窗外的雪。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的脑袋两边各扎了一个辫子。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的脑袋没有受伤。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长颈鹿的脑袋离地面很远。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他低着脑袋，不敢看老师。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理发师轻轻按着他的脑袋。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "脑袋瓜", "label": "复合词"}, {"form": "腦袋", "label": "繁体"}], "register": "口语", "sense_fingerprint": "身体位置：脖子上面的头部，可戴帽子、可受伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90907, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脑袋", "is_correct": true, "explanation": "脑袋：帽子戴在头上，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子上不能“戴”帽子，句意不通。"}, {"text": "脚", "is_correct": false, "explanation": "语义：帽子一般戴在头上，戴在脚上不合常理。"}, {"text": "手腕", "is_correct": false, "explanation": "搭配：“戴”帽子的部位应是头部，手腕与“戴帽子”搭配不通。"}], "explanations": {"脑袋": "脑袋：帽子戴在头上，符合句意。", "桌子": "语义：桌子上不能“戴”帽子，句意不通。", "脚": "语义：帽子一般戴在头上，戴在脚上不合常理。", "手腕": "搭配：“戴”帽子的部位应是头部，手腕与“戴帽子”搭配不通。"}, "sentence_index": 0, "correct_answer": "脑袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里放着一根脑袋。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，人的头不用“根”计量。"}, {"text": "她的脑袋很长，披在肩上。", "explanation": "这里应该用〈头发〉。“披在肩上”指头发，头部不能说披在肩上。"}, {"text": "门口的桌子上摆着一盏脑袋。", "explanation": "这里应该用〈个〉。“盏”用于灯，人的头不用“盏”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90907, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脑袋", "is_correct": true, "explanation": "脑袋：医生检查的是头部，“没有受伤”符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会受伤，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“受伤”多用于身体，与“心情”搭配不通，医生也不会检查心情。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不会受伤，医生不会检查名字。"}], "explanations": {"脑袋": "脑袋：医生检查的是头部，“没有受伤”符合句意。", "作业": "语义：作业不会受伤，句意不通。", "心情": "搭配：“受伤”多用于身体，与“心情”搭配不通，医生也不会检查心情。", "名字": "语义：名字不会受伤，医生不会检查名字。"}, "sentence_index": 6, "correct_answer": "脑袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一块脑袋。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，人的头不用“块”计量。"}, {"text": "他的脑袋很宽，能扛很重的东西。", "explanation": "这里应该用〈肩膀〉。扛东西要靠肩膀，脑袋不能用来扛。"}, {"text": "墙上挂着一张脑袋。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，人的头不用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一只脑袋上戴着一顶蓝帽子。", "corrected_sentence": "他的脑袋上戴着一顶蓝帽子。", "error_description": "“一只”用于动物，人的头不能用“只”计量，应去掉“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长颈鹿的脑袋树梢很近。", "corrected_sentence": "长颈鹿的脑袋离树梢很近。", "error_description": "表示距离时要用“离”引出比较对象，省去“离”后句子不通顺，应说“离树梢很近”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
