INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头；脑瓜。", "primary_collocate": null, "pronunciation": "nǎo dai", "ipa": "naʊ˨˩ taɪ", "syllable_count": 2, "sentences": [{"text": "他听了以后，抓着脑袋想了半天。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的脑袋好疼，想早点睡觉。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸笑着拍了拍我的脑袋。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不同意，一直摇脑袋。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车的时候，要戴头盔保护脑袋。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点了点脑袋，表示同意。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的脑袋比我的大一圈。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热，我把毛巾盖在脑袋上。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫的脑袋小小的，眼睛很大。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球打到了他的脑袋，他有点晕。", "target_word": "脑袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "脑袋瓜", "label": "复合词"}, {"form": "腦袋", "label": "繁体"}], "register": "口语", "sense_fingerprint": "口语里指人或动物的头，常用于点头、摇头、拍头等动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脑袋", "is_correct": true, "explanation": "脑袋：手抓着头部，符合“想了半天”的思考动作。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，手抓不到，句意不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能用手抓着，句意不通。"}, {"text": "墙", "is_correct": false, "explanation": "配价：墙不能被抓着作为思考的动作对象，句意不通。"}], "explanations": {"脑袋": "脑袋：手抓着头部，符合“想了半天”的思考动作。", "月亮": "语义：月亮在天上，手抓不到，句意不通。", "太阳": "语义：太阳不能用手抓着，句意不通。", "墙": "配价：墙不能被抓着作为思考的动作对象，句意不通。"}, "sentence_index": 0, "correct_answer": "脑袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上放着一本脑袋。", "explanation": "这里应该用〈个〉。“本”用于书籍，不用于头。"}, {"text": "墙角放着一把脑袋。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，人的头不用“把”计量。"}, {"text": "他家门口停着一辆脑袋。", "explanation": "这里应该用〈个〉。“辆”用于车，人的头不能用“辆”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脑袋", "is_correct": true, "explanation": "脑袋：可以比较大小，“比我的大一圈”符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能用“大一圈”来比较，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“大一圈”多用于比较体积，年龄不能这样比较。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有“大一圈”的比较方式，句意不通。"}], "explanations": {"脑袋": "脑袋：可以比较大小，“比我的大一圈”符合句意。", "名字": "语义：名字不能用“大一圈”来比较，句意不通。", "年龄": "搭配：“大一圈”多用于比较体积，年龄不能这样比较。", "颜色": "语义：颜色没有“大一圈”的比较方式，句意不通。"}, "sentence_index": 6, "correct_answer": "脑袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片里有一张脑袋。", "explanation": "这里应该用〈个〉。“张”用于照片、纸张等扁平的东西，人的头不用“张”计量。"}, {"text": "衣柜里挂着一顶脑袋。", "explanation": "这里应该用〈个〉。“顶”用于帽子，人的头不能用“顶”计量。"}, {"text": "我买了一副脑袋。", "explanation": "这里应该用〈个〉。“副”用于成对的东西，人的头不用“副”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一只脑袋有点疼，今天不想出门。", "corrected_sentence": "我的脑袋有点疼，今天不想出门。", "error_description": "“只”用于动物，人的头不能用“只”计量；“我的脑袋”前不需要量词，应去掉“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口露出一本小脑袋，是邻居家的孩子。", "corrected_sentence": "门口露出一个小脑袋，是邻居家的孩子。", "error_description": "量词错误：“本”用于书籍，脑袋应该用量词“个”，应说“一个小脑袋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
