INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人像是画出来或拍出来的人的样子。", "primary_collocate": null, "pronunciation": "rén xiàng", "ipa": "ʐən˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "墙上挂着一张老人的人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画的人像很像本人。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家最会画人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张人像拍得很清楚。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想请朋友给他画一张人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张人像里的女孩在笑。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相册里有很多孩子的人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街头艺人五分钟就能画好一张人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅人像画的是我的奶奶。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用铅笔画了一张人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "幅", "label": "量词"}, {"form": "人像画", "label": "复合"}, {"form": "人像摄影", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常指画出来或拍出来的某个人的样子，如一张人像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人像", "is_correct": true, "explanation": "人像指画出来或拍出来的人的样子，可以挂在墙上。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音听得见，不能像画一样挂在墙上。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格，不是能挂在墙上的东西。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“张”不能修饰“年龄”，“一张老人的年龄”不成立。"}], "explanations": {"人像": "人像指画出来或拍出来的人的样子，可以挂在墙上。", "声音": "语义：声音听得见，不能像画一样挂在墙上。", "脾气": "语义：脾气是性格，不是能挂在墙上的东西。", "年龄": "搭配：“张”不能修饰“年龄”，“一张老人的年龄”不成立。"}, "sentence_index": 0, "correct_answer": "人像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张人像拍得很美，拍的是一座雪山。", "explanation": "这里应该用〈照片〉。人像只指人的形象，拍雪山等风景要用照片。"}, {"text": "这张人像会说话，还会唱歌。", "explanation": "语义：人像是画出来或拍出来的人的样子，不是真人，不会说话唱歌。"}, {"text": "我弟弟的人像每天早上去上学。", "explanation": "语义：人像是画或拍出来的形象，不是真人，不能去上学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人像", "is_correct": true, "explanation": "人像指拍出来的人的形象，相册里放的是这种照片。"}, {"text": "作业", "is_correct": false, "explanation": "语义：相册里放的是照片，不会放作业。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是相册里的东西，句子说的是相册中的图像。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的重量数值，不能放进相册里。"}], "explanations": {"人像": "人像指拍出来的人的形象，相册里放的是这种照片。", "作业": "语义：相册里放的是照片，不会放作业。", "课本": "语义：课本不是相册里的东西，句子说的是相册中的图像。", "体重": "语义：体重是人的重量数值，不能放进相册里。"}, "sentence_index": 6, "correct_answer": "人像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅人像画的是一片湖。", "explanation": "这里应该用〈风景画〉。人像只表现人物，画湖泊等风景要用风景画。"}, {"text": "墙上挂着一张人像，画的是一只猫。", "explanation": "这里应该用〈动物画〉。人像只表现人物，画猫要用动物画。"}, {"text": "这张人像昨天自己去公园散步了。", "explanation": "语义：人像是画或拍出来的形象，不是真人，不能自己去散步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座人像画得很像他本人。", "corrected_sentence": "这幅人像画得很像他本人。", "error_description": "量词错误：句中“画得”说明这是一幅画，平面的人像应用“幅”或“张”；“座”用于山、大楼或立体的大型雕像。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一把人像送给了妈妈。", "corrected_sentence": "他把一张人像送给了妈妈。", "error_description": "量词错误：“人像”是平面的画或照片，应用“张”；“把”用于伞、椅子、刀等有柄的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
