INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用绘画、雕塑或摄影表现出的人的形象。", "primary_collocate": null, "pronunciation": "rén xiàng", "ipa": "ʐən˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "博物馆里有很多石头做的人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场上的人像是用铜做的。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学的是摄影，最爱拍人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位艺术家的人像作品很有名。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍人像时，光线要柔和。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古老的人像已经有两千年了。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美术课上，我们学习怎么画人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次展览有二十幅油画人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最擅长雕刻人像。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位摄影师把她的人像拍得很美。", "target_word": "人像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "幅", "label": "量词"}, {"form": "人像画", "label": "复合"}, {"form": "人像摄影", "label": "复合"}], "register": "中性", "sense_fingerprint": "艺术题材，用绘画、雕塑、摄影表现的人物形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人像", "is_correct": true, "explanation": "人像指用石头雕成的人形，可以陈列在博物馆里。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：石头做的东西不能吃，“石头做的饼干”不成立。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不是石头做成的东西。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生要完成的练习，不是石头做成的东西。"}], "explanations": {"人像": "人像指用石头雕成的人形，可以陈列在博物馆里。", "饼干": "语义：石头做的东西不能吃，“石头做的饼干”不成立。", "考试": "语义：考试是测验，不是石头做成的东西。", "作业": "语义：作业是学生要完成的练习，不是石头做成的东西。"}, "sentence_index": 0, "correct_answer": "人像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这座山拍成了人像，看起来很奇怪。", "explanation": "这里应该用〈照片〉。人像只指人物形象，给山拍照要说照片。"}, {"text": "广场上立着一个人像，正在吃午饭。", "explanation": "语义：人像是雕塑或画像，不是真人，不能吃午饭。"}, {"text": "他的人像每天都去超市买菜。", "explanation": "语义：人像是艺术作品，不是真人，不能去超市买菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人像", "is_correct": true, "explanation": "人像指人物的雕塑或画像，美术课上画的正是这种作品。"}, {"text": "意见", "is_correct": false, "explanation": "语义：意见是想法，看不见摸不着，不能画出来。"}, {"text": "数学", "is_correct": false, "explanation": "语义：美术课上学的是绘画，不画数学。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是一个数字概念，不能作为画的对象。"}], "explanations": {"人像": "人像指人物的雕塑或画像，美术课上画的正是这种作品。", "意见": "语义：意见是想法，看不见摸不着，不能画出来。", "数学": "语义：美术课上学的是绘画，不画数学。", "年龄": "语义：年龄是一个数字概念，不能作为画的对象。"}, "sentence_index": 6, "correct_answer": "人像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅人像画的是山和海。", "explanation": "这里应该用〈风景画〉。人像只表现人物，描绘山海要用风景画。"}, {"text": "展厅里放着一幅人像，画的是一座房子。", "explanation": "这里应该用〈建筑画〉。人像只表现人物，画房子要用建筑画。"}, {"text": "博物馆里的铜人像每天自己去吃饭。", "explanation": "语义：人像是雕塑或画像，不是真人，不能自己去吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展厅里放着一幅石膏人像。", "corrected_sentence": "展厅里放着一座石膏人像。", "error_description": "量词错误：“石膏人像”是立体雕塑，应用“座”；“幅”用于平面的画。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在展厅买了一条铜制人像。", "corrected_sentence": "他在展厅买了一座铜制人像。", "error_description": "量词错误：“铜制人像”是立体雕像，应用“座”；“条”用于细长的东西，不用于雕像。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
