INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90911, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追究是一直问下去，想找出原因和是谁做的。", "primary_collocate": null, "pronunciation": "zhuī jiū", "ipa": "tʂweɪ˥ tɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "老师没有追究是谁打破了窗户。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一直追究我今天回家这么晚的原因。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察追究了很久，还是不知道是谁做的。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢追究每件事的原因。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别再追究是谁先说的了。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理一直追究这件事，想知道是谁的错。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他追究过这件事，可是一直没有结果。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们追究了半天，也没找到是谁拿走的。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟追究到底，非要知道是谁告诉妈妈的。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把事情的原因追究清楚了。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追究了", "label": "完成体"}, {"form": "追究过", "label": "经历体"}, {"form": "追究着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "不断追问，要查出原因和做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90911, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "追究", "is_correct": true, "explanation": "正确答案。追究 zhuī jiū 指追问下去、查明原因或责任。"}, {"text": "追求", "is_correct": false, "explanation": "qiú（第二声）与 jiū（第一声）声母不同（q 与 j），意思是为理想而努力争取，不是查问。"}, {"text": "追加", "is_correct": false, "explanation": "jiā 与 jiū 只有韵母不同（ia 与 iu），意思是再增加，与查问无关。"}, {"text": "追击", "is_correct": false, "explanation": "jī 与 jiū 只有韵母不同（i 与 iu），意思是乘胜追赶敌人，不是查问原因。"}], "explanations": {"追究": "正确答案。追究 zhuī jiū 指追问下去、查明原因或责任。", "追求": "qiú（第二声）与 jiū（第一声）声母不同（q 与 j），意思是为理想而努力争取，不是查问。", "追加": "jiā 与 jiū 只有韵母不同（ia 与 iu），意思是再增加，与查问无关。", "追击": "jī 与 jiū 只有韵母不同（i 与 iu），意思是乘胜追赶敌人，不是查问原因。"}, "sentence_index": null, "correct_answer": "追究"}, "level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "追究指追问下去、查明原因，正合「没有追究是谁打破了窗户」的语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏是赞赏喜爱，不能指查问「是谁打破了窗户」。"}, {"text": "修理", "is_correct": false, "explanation": "配价：修理的对象应是具体物件，不能接「是谁打破了窗户」这样的事件从句。"}, {"text": "责怪", "is_correct": false, "explanation": "配价：责怪的对象应是人，不能直接接一个事件从句作宾语。"}], "explanations": {"追究": "追究指追问下去、查明原因，正合「没有追究是谁打破了窗户」的语境。", "欣赏": "语义：欣赏是赞赏喜爱，不能指查问「是谁打破了窗户」。", "修理": "配价：修理的对象应是具体物件，不能接「是谁打破了窗户」这样的事件从句。", "责怪": "配价：责怪的对象应是人，不能直接接一个事件从句作宾语。"}, "sentence_index": 0, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗在草地上追究蝴蝶。", "explanation": "这里应该用〈追赶〉。追究指查问原因或责任，不用于在地上追赶跑动的东西。"}, {"text": "公司又追究了一笔预算。", "explanation": "这里应该用〈追加〉。追加表示在原有的基础上再增加，追究表示查问原因或责任。"}, {"text": "他一生都在追究自由。", "explanation": "这里应该用〈追求〉。追求指为理想而努力争取，追究指查问原因或责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "追究指查问原因或责任，正合「他追究过这件事」的意思。"}, {"text": "装饰", "is_correct": false, "explanation": "配价：装饰的对象应是房间、物品等，不能接「这件事」作宾语，句子不成立。"}, {"text": "喂养", "is_correct": false, "explanation": "配价：喂养的对象应是人或动物，不能接「这件事」作宾语。"}, {"text": "讨好", "is_correct": false, "explanation": "配价：讨好的对象应是人，不能说讨好一件事。"}], "explanations": {"追究": "追究指查问原因或责任，正合「他追究过这件事」的意思。", "装饰": "配价：装饰的对象应是房间、物品等，不能接「这件事」作宾语，句子不成立。", "喂养": "配价：喂养的对象应是人或动物，不能接「这件事」作宾语。", "讨好": "配价：讨好的对象应是人，不能说讨好一件事。"}, "sentence_index": 6, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家属希望政府追究他的英雄称号。", "explanation": "这里应该用〈追认〉。追认指事后确认并授予荣誉，追究是查问原因或责任，不能用于确认英雄称号。"}, {"text": "人们在纪念碑前追究遇难的工人。", "explanation": "这里应该用〈追悼〉。追悼是哀悼死者，追究是查问原因或责任。"}, {"text": "老人常常追究童年的时光。", "explanation": "这里应该用〈追忆〉。追忆是回想过去，追究不能用于回忆童年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察事故的责任追究清楚了。", "corrected_sentence": "警察把事故的责任追究清楚了。", "error_description": "宾语提到动词前时，必须由「把」引出；漏掉「把」，「事故的责任追究清楚了」就不成句，应为「警察把事故的责任追究清楚了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他追究了过这件事的原因，可是没有结果。", "corrected_sentence": "他追究过这件事的原因，可是没有结果。", "error_description": "表示经历只用「过」，不能与「了」同用，应去掉「了」，改为「他追究过这件事的原因」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
